		end
		local decoded, err = util.jsonDecode(rawJson)
		if type(decoded) ~= "table" then
			return false, tostring(err or "Invalid JSON object")
		end
		M.data = decoded
		mergeDefaults(M.data, DEFAULTS)
		M.saveNow()
		M.changed:fire("*", M.data, nil)
		return true
	end

