		return M.mode() == "encrypted"
	end

	function M.isUnlocked()
		return M.isEncrypted() and (unlockedSecrets ~= nil) and (sessionEncKey ~= nil)
	end

	function M.hasVaultFile()
		local raw = fsx.read(VAULT_FILE)
		return type(raw) == "string" and raw ~= ""
	end

	function M.needsFirstBootPrompt()
		return M.mode() == "unset" and config.get("vault.promptedOnce", false) ~= true
	end
	M.shouldPromptFirstBoot = M.needsFirstBootPrompt

	function M.init()
		if M.hasVaultFile() then
			if M.mode() ~= "encrypted" then
				config.set("vault.mode", "encrypted", { quiet = true })
			end
			if config.get("github.token", "") ~= "" then
				config.set("github.token", "", { immediate = true })
			end
		end
		return M.mode()
	end

	local function writeVaultEnvelope()
		if not sessionEncKey or not sessionMacKey or not sessionSalt or not unlockedSecrets then
			return false, "Vault is locked"
		end
		local plainJson = util.jsonEncode(unlockedSecrets) or "{}"
		local nonce = randomBytes16()
		local ciphertext = cryptStream(sessionEncKey, nonce, plainJson)
		local authData = "VSRBLX-VAULT-V1|" .. sessionSalt .. "|" .. nonce .. "|" .. ciphertext
		local tag = M.hmacSha256Raw(sessionMacKey, authData)

		local envelope = util.jsonEncode({
			v = 1,
			iter = sessionIter,
			salt = toHex(sessionSalt),
			nonce = toHex(nonce),
			ct = toHex(ciphertext),
			tag = toHex(tag),
		})
		if not envelope then return false, "Failed to serialize vault envelope" end
		local ok, err = fsx.write(VAULT_FILE, envelope)
		if not ok then return false, err end
		return true
	end

	-- Opt out on first boot ("Leave It / Don't Want To") -> keeps everything unencrypted!
	function M.optOut()
		sessionEncKey = nil
		sessionMacKey = nil
		sessionSalt = nil
		unlockedSecrets = nil
		config.set("vault.mode", "off", { quiet = true })
		config.set("vault.promptedOnce", true, { immediate = true })
		log.info("vault", "User opted out of Master Vault encryption (unencrypted mode)")
		M.changed:fire("off")
		return true
	end

	-- Create a brand-new Master Vault Key and encrypt existing GitHub PAT immediately!
	function M.createMasterKey(passphrase)
		local pw = tostring(passphrase or "")
		if #pw < 4 then
			return false, "Master Vault Key must be at least 4 characters"
		end

		local salt = randomBytes16()
		local derived = M.pbkdf2(pw, salt, DEFAULT_ITERS, 64)
		sessionEncKey = derived:sub(1, 32)
		sessionMacKey = derived:sub(33, 64)
		sessionSalt = salt
		sessionIter = DEFAULT_ITERS

		-- Migrate any existing plaintext PAT and scrub it from `settings.json`!
		local existingPat = tostring(config.get("github.token", "") or "")
		unlockedSecrets = {}
		if existingPat ~= "" then
			unlockedSecrets["github.token"] = existingPat
		end

		local okW, wErr = writeVaultEnvelope()
		if not okW then
			sessionEncKey, sessionMacKey, sessionSalt, unlockedSecrets = nil, nil, nil, nil
			return false, tostring(wErr)
		end

		-- Scrub plaintext token from settings.json permanently!
		config.set("github.token", "", { quiet = true })
		config.set("vault.mode", "encrypted", { quiet = true })
		config.set("vault.promptedOnce", true, { immediate = true })
		config.saveNow()

		log.info("vault", "Created Zero-Knowledge Master Vault (`VSRBLX/vault.enc`) and scrubbed plaintext PAT")
		M.changed:fire("unlocked")
		return true
	end

	-- Unlock an existing `VSRBLX/vault.enc` using the player's Master Vault Key
	function M.unlock(passphrase)
		local pw = tostring(passphrase or "")
		if pw == "" then return false, "Enter your Master Vault Key" end

		local raw = fsx.read(VAULT_FILE)
		if not raw then return false, "Vault file `VSRBLX/vault.enc` not found" end

		local envObj = util.jsonDecode(raw)
		if type(envObj) ~= "table" or envObj.v ~= 1 then
			return false, "Corrupted or unsupported vault envelope"
		end

		local salt = fromHex(envObj.salt)
		local nonce = fromHex(envObj.nonce)
		local ct = fromHex(envObj.ct)
		local tag = fromHex(envObj.tag)
		local iters = math.max(256, math.min(20000, tonumber(envObj.iter) or DEFAULT_ITERS))
		if not salt or not nonce or not ct or not tag or #tag ~= 32 then
			return false, "Malformed cryptographic fields in `vault.enc`"
		end

		local derived = M.pbkdf2(pw, salt, iters, 64)
		local encKey = derived:sub(1, 32)
		local macKey = derived:sub(33, 64)

		local authData = "VSRBLX-VAULT-V1|" .. salt .. "|" .. nonce .. "|" .. ct
		local expectedTag = M.hmacSha256Raw(macKey, authData)
		if not constantTimeEquals(expectedTag, tag) then
			return false, "Incorrect Master Vault Key (decryption refused)"
		end

		local plainJson = cryptStream(encKey, nonce, ct)
		local secrets = util.jsonDecode(plainJson)
		if type(secrets) ~= "table" then
			return false, "Decrypted vault payload is invalid"
		end

		sessionEncKey = encKey
		sessionMacKey = macKey
		sessionSalt = salt
		sessionIter = iters
		unlockedSecrets = secrets

		-- Ensure plaintext config stays scrubbed
		if config.get("github.token", "") ~= "" then
			config.set("github.token", "", { immediate = true })
		end

		log.info("vault", "Master Vault unlocked in memory")
		M.changed:fire("unlocked")
		return true
	end

	-- Lock Vault immediately (wiping derived keys and decrypted PAT from RAM!)
	function M.lock()
		sessionEncKey = nil
		sessionMacKey = nil
		sessionSalt = nil
		unlockedSecrets = nil
		log.info("vault", "Master Vault locked (RAM secrets wiped)")
		M.changed:fire("locked")
		return true
	end

	function M.getSecret(key)
		if not M.isUnlocked() then return nil end
		return unlockedSecrets[tostring(key)]
	end

	function M.setSecret(key, val)
		if not M.isUnlocked() then
			return false, "Master Vault is locked — unlock with your Master Key first"
		end
		unlockedSecrets[tostring(key)] = val
		return writeVaultEnvelope()
	end

	-- Destructive reset if user forgot their Master Key (cannot recover encrypted PAT!)
	function M.resetVault()
		M.lock()
		pcall(function() fsx.delete(VAULT_FILE) end)
		config.set("github.token", "", { quiet = true })
		config.set("vault.mode", "off", { quiet = true })
		config.set("vault.promptedOnce", true, { immediate = true })
		config.saveNow()
		log.warn("vault", "Master Vault reset & wiped (`vault.enc` deleted)")
		M.changed:fire("off")
		return true
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/diagnostics
-- ==========================================================================
__VSRBLX_MODULES["runtime/diagnostics"] = (function()
-- Real-time syntax & bracket diagnostics feeding VS-RBLX editor gutter markers,
-- status bar error/warning counters, and the bottom Problems panel.
return function(env)
	local caps = env.require("runtime/caps")
	local util = env.require("runtime/util")
	local languages = env.require("runtime/languages")
	local signal = env.require("runtime/signal")

	local M = {
		byDoc = {},
		changed = signal.new("diagnostics.changed"),
	}

	local function checkBracketBalance(source)
		local issues = {}
		local stack = {}
		local pairsMap = { ["("] = ")", ["["] = "]", ["{"] = "}" }
		local closers = { [")"] = "(", ["]"] = "[", ["}"] = "{" }
		local lines = util.lines(source)

		for ln, line in ipairs(lines) do
			local inQuote = nil
			local i = 1
			while i <= #line do
				local c = line:sub(i, i)
				if inQuote then
					if c == "\\" then
						i = i + 1
					elseif c == inQuote then
						inQuote = nil
					end
				else
					if c == "/" and line:sub(i + 1, i + 1) == "/" then
						break
					elseif c == "#" then
						break
					elseif c == '"' or c == "'" then
						inQuote = c
					elseif pairsMap[c] then
						stack[#stack + 1] = { char = c, expect = pairsMap[c], line = ln, col = i }
					elseif closers[c] then
						local top = stack[#stack]
						if not top or top.char ~= closers[c] then
							issues[#issues + 1] = {
								severity = "error",
								line = ln,
								col = i,
								message = string.format("Unexpected closing '%s'", c),
							}
							return issues
						else
							stack[#stack] = nil
						end
					end
				end
				i = i + 1
			end
		end

		if #stack > 0 then
			local top = stack[#stack]
			issues[#issues + 1] = {
				severity = "error",
				line = top.line,
				col = top.col,
				message = string.format("Unclosed '%s' (expected '%s')", top.char, top.expect),
			}
		end
		return issues
	end

	function M.check(doc)
		if not doc or doc.isDiff then return {} end
		local source = tostring(doc.content or "")
		local lang = languages.get(doc.langId)
		local list = {}

		if lang.id == "luau" and caps.fn.loadstring then
			local fn, err = caps.fn.loadstring(source, doc.path or "chunk")
			if not fn and err then
				local ln = tonumber(tostring(err):match(":(%d+):")) or 1
				local msg = tostring(err):match(":%d+:%s*(.*)$") or tostring(err)
				list[#list + 1] = {
					severity = "error",
					line = ln,
					col = 1,
					message = msg,
					path = doc.path,
					docId = doc.id,
				}
			end
		elseif lang.id == "json" then
			if source:find("%S") then
				local decoded, err = util.jsonDecode(source)
				if decoded == nil and err then
					list[#list + 1] = {
						severity = "error",
						line = 1,
						col = 1,
						message = tostring(err),
						path = doc.path,
						docId = doc.id,
					}
				end
			end
		elseif lang.id == "javascript" or lang.id == "typescript" or lang.id == "python"
			or lang.id == "rust" or lang.id == "go" or lang.id == "cpp" or lang.id == "csharp" or lang.id == "java" then
			for _, issue in ipairs(checkBracketBalance(source)) do
				issue.path = doc.path
				issue.docId = doc.id
				list[#list + 1] = issue
			end
		end

		local lines = util.lines(source)
		for i, line in ipairs(lines) do
			if line:find("TODO", 1, true) or line:find("FIXME", 1, true) then
				list[#list + 1] = {
					severity = "warn",
					line = i,
					col = 1,
					message = "Note marker: " .. util.trim(line):sub(1, 70),
					path = doc.path,
					docId = doc.id,
				}
			end
		end

		M.byDoc[doc.id] = list
		M.changed:fire(doc.id, list)
		return list
	end

	function M.remove(docId)
		M.byDoc[docId] = nil
		M.changed:fire(docId, {})
	end

	function M.all()
		local errorsCount, warnsCount = 0, 0
		local items = {}
		for _, list in pairs(M.byDoc) do
			for _, item in ipairs(list) do
				items[#items + 1] = item
				if item.severity == "error" then
					errorsCount = errorsCount + 1
				else
					warnsCount = warnsCount + 1
				end
			end
		end
		table.sort(items, function(a, b)
			if a.path ~= b.path then return tostring(a.path) < tostring(b.path) end
			return (a.line or 1) < (b.line or 1)
		end)
		return items, errorsCount, warnsCount
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/dispose
-- ==========================================================================
__VSRBLX_MODULES["runtime/dispose"] = (function()
-- Deterministic cleanup registry so unloading VS-RBLX leaves zero dangling
-- connections, threads, or GUI instances behind.
return function(_env)
	local M = { draining = false }
	local items = {}

	function M.give(resource)
		if resource == nil then return function() end end
		items[#items + 1] = resource
		return function()
			for i = #items, 1, -1 do
				if items[i] == resource then
					table.remove(items, i)
					break
				end
			end
			M.releaseOne(resource)
		end
	end

	function M.connection(conn)
		return M.give(conn)
	end

	function M.instance(inst)
		return M.give(inst)
	end

	function M.thread(co)
		return M.give(co)
	end

	function M.releaseOne(resource)
		local kind = typeof and typeof(resource) or type(resource)
		if kind == "RBXScriptConnection" then
			pcall(function() resource:Disconnect() end)
		elseif kind == "Instance" then
			pcall(function() resource:Destroy() end)
		elseif type(resource) == "thread" then
			pcall(task.cancel, resource)
		elseif type(resource) == "function" then
			pcall(resource)
		elseif type(resource) == "table" then
			if type(resource.Disconnect) == "function" then
				pcall(function() resource:Disconnect() end)
			elseif type(resource.Destroy) == "function" then
				pcall(function() resource:Destroy() end)
			elseif type(resource.destroy) == "function" then
				pcall(resource.destroy)
			elseif type(resource.cancel) == "function" then
				pcall(resource.cancel)
			end
		end
	end

	function M.drain()
		M.draining = true
		for i = #items, 1, -1 do
			local item = items[i]
			items[i] = nil
			M.releaseOne(item)
		end
		M.draining = false
	end

	M.add = M.give
	M.all = M.drain
	M.cleanupAll = M.drain

	return M
end
end)()

-- ==========================================================================
-- runtime/editor_actions
-- ==========================================================================
__VSRBLX_MODULES["runtime/editor_actions"] = (function()
-- Pure-Luau Monaco-style Smart Typing & Line Editing Engine (`src/runtime/editor_actions.lua`).
-- Powers auto-closing brackets/quotes, smart Enter auto-indent, Tab/Shift+Tab block indent,
-- Ctrl+/ line comment toggle, Alt+Up/Down move line, Shift+Alt+Down duplicate, Ctrl+Shift+K
-- delete line, and Ctrl+D / Ctrl+L word & line selection.
return function(env)
	local util = env.require("runtime/util")
	local languages = env.require("runtime/languages")

	local BACKTICK = string.char(96)

	local AUTO_PAIRS = {
		["("] = ")",
		["["] = "]",
		["{"] = "}",
		['"'] = '"',
		["'"] = "'",
		[BACKTICK] = BACKTICK,
	}

	local CLOSERS = {
		[")"] = "(",
		["]"] = "[",
		["}"] = "{",
		['"'] = '"',
		["'"] = "'",
		[BACKTICK] = BACKTICK,
	}

	local M = {
		pairs = AUTO_PAIRS,
		closers = CLOSERS,
	}

	-- Splits `source` into lines and returns line range `[startLine, endLine]` covered by `(cursor, selStart)`
	function M.lineSpanForOffsets(source, cursorOffset, selOffset)
		local text = tostring(source or "")
		local lines = util.lines(text)
		local starts = {}
		local pos = 1
		for i = 1, #lines do
			starts[i] = pos
			pos = pos + #lines[i] + 1
		end

		local function lineAt(offset)
			local clamped = util.clamp(tonumber(offset) or 1, 1, #text + 1)
			local ln = 1
			for i = 1, #starts do
				if starts[i] <= clamped then ln = i else break end
			end
			return ln
		end

		local cPos = util.clamp(tonumber(cursorOffset) or 1, 1, #text + 1)
		local sPos = (tonumber(selOffset) and tonumber(selOffset) > 0) and util.clamp(tonumber(selOffset), 1, #text + 1) or cPos
		local minOff = math.min(cPos, sPos)
		local maxOff = math.max(cPos, sPos)
		local firstLine = lineAt(minOff)
		local lastLine = lineAt(maxOff)
		if maxOff > minOff and maxOff == starts[lastLine] and lastLine > firstLine then
			lastLine = lastLine - 1
		end
		return lines, starts, firstLine, lastLine, minOff, maxOff
	end

	-- 1. Toggle Line Comment (`Ctrl+/`)
	function M.toggleComment(source, cursorOffset, selOffset, langId)
		local lang = languages.get(langId)
		local prefix = lang.lineComment
		local suffix = ""
		if not prefix or prefix == "" then
			if lang.id == "html" or lang.id == "markdown" then
				prefix, suffix = "<!-- ", " -->"
			elseif lang.blockComment then
				prefix = lang.blockComment[1] .. " "
				suffix = " " .. lang.blockComment[2]
			else
				prefix = "--"
			end
		else
			prefix = prefix .. " "
		end

		local rawPrefix = util.trim(prefix)
		local lines, starts, firstLine, lastLine = M.lineSpanForOffsets(source, cursorOffset, selOffset)

		local allCommented = true
		local hasNonEmpty = false
		for i = firstLine, lastLine do
			local trimmed = util.trim(lines[i])
			if trimmed ~= "" then
				hasNonEmpty = true
				if not util.startsWith(trimmed, rawPrefix) then
					allCommented = false
					break
				end
			end
		end

		local deltaFirst = 0
		for i = firstLine, lastLine do
			local ln = lines[i]
			if allCommented and hasNonEmpty then
				local lead = ln:match("^(%s*)") or ""
				local rest = ln:sub(#lead + 1)
				if util.startsWith(rest, prefix) then
					rest = rest:sub(#prefix + 1)
				elseif util.startsWith(rest, rawPrefix) then
					rest = rest:sub(#rawPrefix + 1)
				end
				if suffix ~= "" and util.endsWith(rest, suffix) then
					rest = rest:sub(1, #rest - #suffix)
				end
				local updated = lead .. rest
				if i == firstLine then deltaFirst = #updated - #ln end
				lines[i] = updated
			elseif ln:find("%S") or firstLine == lastLine then
				local lead = ln:match("^(%s*)") or ""
				local rest = ln:sub(#lead + 1)
				local updated = lead .. prefix .. rest .. suffix
				if i == firstLine then deltaFirst = #updated - #ln end
				lines[i] = updated
			end
		end

		local result = table.concat(lines, "\n")
		local nextCursor = util.clamp((tonumber(cursorOffset) or 1) + deltaFirst, 1, #result + 1)
		return result, nextCursor
	end

	-- 2. Indent / Outdent Single Line or Selected Block (`Tab` / `Shift+Tab`)
	function M.indentBlock(source, cursorOffset, selOffset, tabSize, insertSpaces, outdent)
		local unit = (insertSpaces ~= false) and string.rep(" ", tonumber(tabSize) or 4) or "\t"
		local tSize = tonumber(tabSize) or 4
		local hasSel = tonumber(selOffset) and tonumber(selOffset) > 0 and tonumber(selOffset) ~= tonumber(cursorOffset)

		if not hasSel and not outdent then
			local text = tostring(source or "")
			local c = util.clamp(tonumber(cursorOffset) or 1, 1, #text + 1)
			local updated = text:sub(1, c - 1) .. unit .. text:sub(c)
			return updated, c + #unit, -1
		end

		local lines, starts, firstLine, lastLine, minOff, maxOff = M.lineSpanForOffsets(source, cursorOffset, selOffset)
		local totalDelta = 0
		local firstDelta = 0

		for i = firstLine, lastLine do
			local ln = lines[i]
			local updated = ln
			if outdent then
				if util.startsWith(ln, "\t") then
					updated = ln:sub(2)
				else
					local spaces = #(ln:match("^( +)") or "")
					local strip = math.min(spaces, tSize)
					updated = ln:sub(strip + 1)
				end
			else
				updated = unit .. ln
			end
			local d = #updated - #ln
			if i == firstLine then firstDelta = d end
			totalDelta = totalDelta + d
			lines[i] = updated
		end

		local result = table.concat(lines, "\n")
		if hasSel then
			return result, math.max(1, maxOff + totalDelta), math.max(1, minOff + firstDelta)
		end
		return result, util.clamp((tonumber(cursorOffset) or 1) + firstDelta, 1, #result + 1), -1
	end

	-- 3. Move Line(s) Up or Down (`Alt+Up` / `Alt+Down`)
	function M.moveLines(source, cursorOffset, selOffset, direction)
		local lines, starts, firstLine, lastLine = M.lineSpanForOffsets(source, cursorOffset, selOffset)
		local colOffset = math.max(0, (tonumber(cursorOffset) or 1) - starts[firstLine])

		if direction < 0 then
			if firstLine <= 1 then return source, cursorOffset, selOffset end
			local above = table.remove(lines, firstLine - 1)
			table.insert(lines, lastLine, above)
			firstLine = firstLine - 1
		else
			if lastLine >= #lines then return source, cursorOffset, selOffset end
			local below = table.remove(lines, lastLine + 1)
			table.insert(lines, firstLine, below)
			firstLine = firstLine + 1
		end

		local result = table.concat(lines, "\n")
		local _, newStarts = M.lineSpanForOffsets(result, 1, -1)
		local newCursor = math.min(#result + 1, newStarts[firstLine] + colOffset)
		return result, newCursor, -1
	end

	-- 4. Duplicate Line(s) Down or Up (`Shift+Alt+Down` / `Shift+Alt+Up`)
	function M.duplicateLines(source, cursorOffset, selOffset, direction)
		local lines, starts, firstLine, lastLine = M.lineSpanForOffsets(source, cursorOffset, selOffset)
		local colOffset = math.max(0, (tonumber(cursorOffset) or 1) - starts[firstLine])
		local block = {}
		for i = firstLine, lastLine do
			block[#block + 1] = lines[i]
		end

		local insertPos = direction < 0 and firstLine or (lastLine + 1)
		for idx = #block, 1, -1 do
			table.insert(lines, insertPos, block[idx])
		end

		local targetLine = direction < 0 and firstLine or (lastLine + 1)
		local result = table.concat(lines, "\n")
		local _, newStarts = M.lineSpanForOffsets(result, 1, -1)
		local newCursor = math.min(#result + 1, newStarts[targetLine] + colOffset)
		return result, newCursor
	end

	-- 5. Delete Line (`Ctrl+Shift+K`)
	function M.deleteLines(source, cursorOffset, selOffset)
		local lines, _, firstLine, lastLine = M.lineSpanForOffsets(source, cursorOffset, selOffset)
		for i = lastLine, firstLine, -1 do
			table.remove(lines, i)
		end
		if #lines == 0 then lines[1] = "" end
		local result = table.concat(lines, "\n")
		local _, newStarts = M.lineSpanForOffsets(result, 1, -1)
		local target = math.min(firstLine, #lines)
		return result, newStarts[target] or 1
	end

	-- 6. Select Word at Cursor (`Ctrl+D`) & Select Full Line (`Ctrl+L`)
	function M.wordAtCursor(source, cursorOffset)
		local text = tostring(source or "")
		if text == "" then return 1, 1, "" end
		local pos = util.clamp(tonumber(cursorOffset) or 1, 1, #text)
		if not text:sub(pos, pos):match("[%w_]") and pos > 1 and text:sub(pos - 1, pos - 1):match("[%w_]") then
			pos = pos - 1
		end
		if not text:sub(pos, pos):match("[%w_]") then
			return pos, pos, ""
		end
		local s = pos
		while s > 1 and text:sub(s - 1, s - 1):match("[%w_]") do s = s - 1 end
		local e = pos
		while e < #text and text:sub(e + 1, e + 1):match("[%w_]") do e = e + 1 end
		return s, e + 1, text:sub(s, e)
	end

	function M.lineBoundsAtCursor(source, cursorOffset)
		local lines, starts, firstLine = M.lineSpanForOffsets(source, cursorOffset, -1)
		local s = starts[firstLine] or 1
		local e = s + #(lines[firstLine] or "")
		if firstLine < #lines then e = e + 1 end
		return s, e
	end

	-- 7. Smart Typing Post-Processor: detects single-char insertions (auto-close pairs,
	-- overtype, smart Enter auto-indent, and empty-pair Backspace) between `prevText` and `newText`.
	local function shouldIncreaseIndent(lineBeforeCursor, langId)
		local trimmed = util.trim(lineBeforeCursor)
		if trimmed == "" then return false end
		local lastChar = trimmed:sub(-1)
		if lastChar == "{" or lastChar == "(" or lastChar == "[" or lastChar == ":" then
			return true
		end
		if langId == "luau" or langId == "lua" then
			if trimmed:match("%f[%w]then$")
				or trimmed:match("%f[%w]do$")
				or trimmed:match("%f[%w]repeat$")
				or trimmed:match("%f[%w]else$")
				or trimmed:match("function%s*[%w_%.:]*%s*%b()$") then
				return true
			end
		end
		return false
	end

	function M.applySmartTyping(prevText, newText, newCursor, opts)
		opts = opts or {}
		if type(prevText) ~= "string" or type(newText) ~= "string" then
			return newText, newCursor
		end

		local lenDiff = #newText - #prevText
		local unit = (opts.insertSpaces ~= false) and string.rep(" ", tonumber(opts.tabSize) or 4) or "\t"

		-- Case A: Single-character Backspace inside an empty auto-pair `(|)` -> deletes both!
		if lenDiff == -1 and opts.autoClosingBrackets ~= false then
			local delPos = util.clamp((tonumber(newCursor) or 1), 1, #prevText)
			local deletedChar = prevText:sub(delPos, delPos)
			local expectedCloser = AUTO_PAIRS[deletedChar]
			if expectedCloser and prevText:sub(delPos + 1, delPos + 1) == expectedCloser then
				local verify = prevText:sub(1, delPos - 1) .. prevText:sub(delPos + 1)
				if verify == newText then
					local stripped = newText:sub(1, delPos - 1) .. newText:sub(delPos + 1)
					return stripped, delPos
				end
			end
			return newText, newCursor
		end

		if lenDiff ~= 1 then
			return newText, newCursor
		end

		local insPos = util.clamp((tonumber(newCursor) or 1) - 1, 1, #newText)
		local typed = newText:sub(insPos, insPos)
		local verifyPrev = newText:sub(1, insPos - 1) .. newText:sub(insPos + 1)
		if verifyPrev ~= prevText then
			return newText, newCursor
		end

		local charAfter = newText:sub(insPos + 1, insPos + 1)
		local charBefore = insPos > 1 and newText:sub(insPos - 1, insPos - 1) or ""

		-- Case B: Tab key typed inside TextBox -> convert literal `\t` to spaces if insertSpaces
		if typed == "\t" and opts.insertSpaces ~= false then
			local expanded = newText:sub(1, insPos - 1) .. unit .. newText:sub(insPos + 1)
			return expanded, insPos + #unit
		end

		-- Case C: Smart Enter auto-indent (+ `{|}` two-line block expansion)
		if typed == "\n" and opts.autoIndent ~= false then
			local beforeNewline = newText:sub(1, insPos - 1)
			local lastNl = beforeNewline:match(".*()\n")
			local currentLine = lastNl and beforeNewline:sub(lastNl + 1) or beforeNewline
			local baseIndent = currentLine:match("^([ \t]*)") or ""
			local addExtra = shouldIncreaseIndent(currentLine, opts.langId or "luau")

			if charBefore == "{" and charAfter == "}"
				or charBefore == "(" and charAfter == ")"
				or charBefore == "[" and charAfter == "]" then
				local innerIndent = baseIndent .. unit
				local expanded = newText:sub(1, insPos)
					.. innerIndent
					.. "\n"
					.. baseIndent
					.. newText:sub(insPos + 1)
				return expanded, insPos + 1 + #innerIndent
			end

			local nextIndent = addExtra and (baseIndent .. unit) or baseIndent
			if nextIndent ~= "" then
				local indented = newText:sub(1, insPos) .. nextIndent .. newText:sub(insPos + 1)
				return indented, insPos + 1 + #nextIndent
			end
			return newText, newCursor
		end

		-- Case D: Auto-closing brackets & quotes + smart overtype
		if opts.autoClosingBrackets ~= false then
			-- Smart overtype over an already-present closing delimiter
			if CLOSERS[typed] and charAfter == typed then
				-- Only overtype quotes if not preceded by backslash
				if charBefore ~= "\\" then
					return prevText, insPos + 1
				end
			end

			local closer = AUTO_PAIRS[typed]
			if closer then
				local nextIsWord = charAfter ~= "" and charAfter:match("[%w_]") ~= nil
				local isQuote = (typed == '"' or typed == "'" or typed == BACKTICK)
				local prevIsWordOrQuote = isQuote and (charBefore:match("[%w_\"'`\\]") ~= nil)
				if not nextIsWord and not prevIsWordOrQuote then
					local paired = newText:sub(1, insPos) .. closer .. newText:sub(insPos + 1)
					return paired, insPos + 1
				end
			end
		end

		return newText, newCursor
	end

	return M
end
end)()

