__VSRBLX_MODULES["runtime/roblox_explorer"] = (function()
-- Live Roblox DataModel inspector: browse services, generate valid Luau Instance paths,
-- inspect Instance properties safely, and read/decompile scripts into VS-RBLX.
return function(env)
	local caps = env.require("runtime/caps")
	local util = env.require("runtime/util")

	local M = {}

	local ROOTS = {
		"Workspace",
		"ReplicatedStorage",
		"Players",
		"StarterPlayer",
		"StarterGui",
		"Lighting",
	}

	local function isValidIdent(str)
		if type(str) ~= "string" or str == "" then return false end
		return str:match("^[%a_][%w_]*$") ~= nil
	end

	function M.formatChildAccess(childName)
		local n = tostring(childName or "")
		if isValidIdent(n) then
			return "." .. n
		end
		local escaped = n:gsub("\\", "\\\\"):gsub('"', '\\"')
		return '["' .. escaped .. '"]'
	end

	-- Produces a clean, copy-paste-ready Luau expression pointing to `inst`
	function M.luauPathOf(inst)
		if not inst then return "nil" end
		if inst == env.game then return "game" end
		if inst == env.workspace then return "workspace" end

		local chain = {}
		local cur = inst
		local guard = 0
		while cur and cur ~= env.game and guard < 40 do
			guard = guard + 1
			chain[#chain + 1] = cur
			local ok, p = pcall(function() return cur.Parent end)
			if not ok then break end
			cur = p
		end

		if #chain == 0 then return "nil" end

		local top = chain[#chain]
		local topClass = ""
		local topName = ""
		pcall(function()
			topClass = tostring(top.ClassName or "")
			topName = tostring(top.Name or "")
		end)

		local expr
		if top == env.workspace or topClass == "Workspace" or topName == "Workspace" then
			expr = "workspace"
		elseif topClass ~= "" then
			expr = string.format('game:GetService(%q)', topClass)
		else
			expr = "game" .. M.formatChildAccess(topName)
		end

		-- Shortcut LocalPlayer if path starts under Players.<LocalPlayerName>
		local startIdx = #chain - 1
		if (topClass == "Players" or topName == "Players") and startIdx >= 1 and env.plr and chain[startIdx] == env.plr then
			expr = 'game:GetService("Players").LocalPlayer'
			startIdx = startIdx - 1
		end

		for i = startIdx, 1, -1 do
			local node = chain[i]
			local nm = ""
			pcall(function() nm = tostring(node.Name or "") end)
			expr = expr .. M.formatChildAccess(nm)
		end

		return expr
	end

	-- Resolves dot/slash paths (`Workspace.Map.Spawn`) AND Luau paths (`workspace.ArenaMap["Lava Platform"]`,
	-- `game:GetService("ReplicatedStorage").SharedConfig`) back into live Instances!
	function M.resolvePath(pathSpec)
		local raw = util.trim(tostring(pathSpec or ""))
		if raw == "" or raw == "game" then return env.game end
		if raw:lower() == "workspace" then return env.workspace end

		-- Strip leading `game:GetService("X")` prefix if present
		local svcName, tailAfterSvc = raw:match('^game:GetService%(%s*["\']([^"\']+)["\']%s*%)(.*)$')
		local cur = nil
		local rest = raw
		if svcName then
			cur = env.services[svcName]
			if not cur and env.game then
				pcall(function() cur = env.game:FindFirstChild(svcName) end)
			end
			if not cur then return nil, "Service not found: " .. tostring(svcName) end
			rest = tailAfterSvc or ""
		end

		-- Tokenize `.Name`, `/Name`, `["Name"]`, `['Name']`, or bare leading `Name`
		local parts = {}
		local pos = 1
		local n = #rest
		while pos <= n do
			local ch = rest:sub(pos, pos)
			if ch == "." or ch == "/" or ch == " " then
				pos = pos + 1
			elseif rest:sub(pos, pos + 1) == '["' then
				local closePos = rest:find('"]', pos + 2, true)
				if not closePos then break end
				local inner = rest:sub(pos + 2, closePos - 1):gsub('\\"', '"'):gsub("\\\\", "\\")
				parts[#parts + 1] = inner
				pos = closePos + 2
			elseif rest:sub(pos, pos + 1) == "['" then
				local closePos = rest:find("']", pos + 2, true)
				if not closePos then break end
				local inner = rest:sub(pos + 2, closePos - 1):gsub("\\'", "'"):gsub("\\\\", "\\")
				parts[#parts + 1] = inner
				pos = closePos + 2
			else
				local nextSep = rest:find("[%.%/%[]", pos)
				local seg = nextSep and rest:sub(pos, nextSep - 1) or rest:sub(pos)
				seg = util.trim(seg)
				if seg ~= "" then parts[#parts + 1] = seg end
				pos = nextSep or (n + 1)
			end
		end

		if not cur then
			if #parts == 0 then return nil, "Invalid path: " .. raw end
			local first = parts[1]
			if first:lower() == "game" then
				cur = env.game
				table.remove(parts, 1)
				first = parts[1]
			end
			if not first then return cur end
			if not cur then
				if first:lower() == "workspace" then
					cur = env.workspace
				else
					cur = env.services[first]
					if not cur and env.game then
						pcall(function() cur = env.game:FindFirstChild(first) end)
					end
				end
				table.remove(parts, 1)
			end
		end

		for _, seg in ipairs(parts) do
			if not cur then return nil, "Instance not found along: " .. raw end
			if seg == "LocalPlayer" and cur == env.players then
				cur = env.plr
			else
				local nxt = nil
				pcall(function() nxt = cur:FindFirstChild(seg) end)
				cur = nxt
			end
		end
		if not cur then return nil, "Instance not found: " .. raw end
		return cur
	end

	local PROBE_PROPS = {
		"Name",
		"ClassName",
		"Position",
		"Size",
		"Anchored",
		"CanCollide",
		"Transparency",
		"Visible",
		"Active",
		"Text",
		"Value",
		"Enabled",
	}

	function M.inspectProperties(inst)
		if not inst then return nil, "Instance not found" end
		local props = {}
		for _, propName in ipairs(PROBE_PROPS) do
			local ok, val = pcall(function() return inst[propName] end)
			if ok and val ~= nil then
				props[#props + 1] = {
					name = propName,
					value = tostring(val),
					kind = type(val),
				}
			end
		end
		local childCount = 0
		pcall(function() childCount = #inst:GetChildren() end)
		props[#props + 1] = { name = "Children", value = tostring(childCount), kind = "number" }
		props[#props + 1] = { name = "LuauPath", value = M.luauPathOf(inst), kind = "string" }
		return props
	end

	function M.rootServices()
		local out = {}
		for _, name in ipairs(ROOTS) do
			local svc = env.services[name]
			if svc then
				out[#out + 1] = {
					name = name,
					className = svc.ClassName or name,
					instance = svc,
				}
			end
		end
		return out
	end

	function M.childrenOf(inst, limit)
		if not inst then return {} end
		local ok, children = pcall(function() return inst:GetChildren() end)
		if not ok or type(children) ~= "table" then return {} end
		local maxItems = limit or 120
		local out = {}
		for i = 1, math.min(#children, maxItems) do
			local ch = children[i]
			local isScript = false
			pcall(function()
				isScript = ch:IsA("LuaSourceContainer")
			end)
			local hasKids = false
			pcall(function()
				hasKids = #ch:GetChildren() > 0
			end)
			out[#out + 1] = {
				name = tostring(ch.Name or ch.ClassName),
				className = tostring(ch.ClassName or "Instance"),
				instance = ch,
				isScript = isScript,
				hasChildren = hasKids,
			}
		end
		table.sort(out, function(a, b)
			if a.isScript ~= b.isScript then return a.isScript end
			return a.name:lower() < b.name:lower()
		end)
		return out
	end

	function M.readScriptSource(inst)
		if not inst then return nil, "no instance" end
		local okSrc, rawSrc = pcall(function() return inst.Source end)
		if okSrc and type(rawSrc) == "string" and rawSrc ~= "" then
			return rawSrc, "Source"
		end
		if caps.fn.decompile then
			local okDec, decompiled = pcall(caps.fn.decompile, inst)
			if okDec and type(decompiled) == "string" and decompiled ~= "" then
				return decompiled, "decompile"
			end
		end
		return string.format(
			"-- Instance: %s (%s)\n-- Path: %s\n-- Source is not readable without executor `decompile()` support.\n",
			tostring(inst.Name),
			tostring(inst.ClassName),
			M.luauPathOf(inst)
		), "stub"
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/runner
-- ==========================================================================
__VSRBLX_MODULES["runtime/runner"] = (function()
-- Sandboxed Luau execution engine via executor `loadstring`, with captured
-- `print`/`warn` streams, runtime error tracebacks, and task cancellation.
return function(env)
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")

	local M = {
		running = {},
		changed = signal.new("runner.changed"),
	}
	local nextRunId = 0

	local function stringifyArgs(...)
		local out = {}
		for i = 1, select("#", ...) do
			out[i] = tostring(select(i, ...))
		end
		return table.concat(out, "    ")
	end

	function M.execute(source, label)
		if not caps.fn.loadstring then
			local msg = "Host does not expose `loadstring` for dynamic Luau execution."
			log.error("runner", msg)
			return false, msg
		end

		local chunkName = tostring(label or "script.luau")
		local fn, compileErr = caps.fn.loadstring(tostring(source or ""), chunkName)
		if not fn then
			local errMsg = "Syntax error in " .. chunkName .. ": " .. tostring(compileErr)
			log.error("runner", errMsg)
			return false, errMsg
		end

		nextRunId = nextRunId + 1
		local runId = nextRunId
		local startedMs = clock.ms()
		local linesOut = {}

		if type(setfenv) == "function" then
			local baseEnv = caps.fn.getgenv and caps.fn.getgenv() or _G
			local proxy = setmetatable({
				print = function(...)
					local line = stringifyArgs(...)
					linesOut[#linesOut + 1] = line
					log.output("runner", line)
				end,
				warn = function(...)
					local line = "[warn] " .. stringifyArgs(...)
					linesOut[#linesOut + 1] = line
					log.warn("runner", line)
				end,
			}, {
				__index = baseEnv,
				__newindex = baseEnv,
			})
			pcall(setfenv, fn, proxy)
		end

		local record = {
			id = runId,
			label = chunkName,
			startedMs = startedMs,
			thread = nil,
			active = true,
		}
		M.running[runId] = record
		M.changed:fire()
		log.info("runner", string.format("Running %s (task #%d)...", chunkName, runId))

		local execOk, execResult = false, nil
		record.thread = task.spawn(function()
			local ok, res = pcall(fn)
			execOk, execResult = ok, res
			record.active = false
			M.running[runId] = nil
			local elapsed = clock.ms() - startedMs
			if ok then
				if res ~= nil then
					linesOut[#linesOut + 1] = "=> " .. tostring(res)
					log.output("runner", "=> " .. tostring(res))
				end
				log.info("runner", string.format("Finished %s in %d ms.", chunkName, elapsed))
			else
				log.error("runner", string.format("Runtime error in %s (%d ms): %s", chunkName, elapsed, tostring(res)))
			end
			M.changed:fire()
		end)

		return execOk, execResult, linesOut
	end

	function M.stopAll()
		local stopped = 0
		for id, rec in pairs(M.running) do
			if rec.thread then
				pcall(task.cancel, rec.thread)
			end
			rec.active = false
			M.running[id] = nil
			stopped = stopped + 1
		end
		if stopped > 0 then
			log.warn("runner", string.format("Stopped %d running script task(s).", stopped))
			M.changed:fire()
		end
		return stopped
	end

	function M.activeCount()
		local n = 0
		for _ in pairs(M.running) do n = n + 1 end
		return n
	end

	function M.evalExpression(expr)
		if not caps.fn.loadstring then
			return false, "loadstring unavailable"
		end
		local fn, err = caps.fn.loadstring("return " .. tostring(expr or ""), "watch")
		if not fn then
			fn, err = caps.fn.loadstring(tostring(expr or ""), "watch")
		end
		if not fn then return false, tostring(err) end
		if type(setfenv) == "function" then
			local baseEnv = caps.fn.getgenv and caps.fn.getgenv() or _G
			pcall(setfenv, fn, baseEnv)
		end
		local ok, val = pcall(fn)
		return ok, val
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/session_journal
-- ==========================================================================
__VSRBLX_MODULES["runtime/session_journal"] = (function()
-- Crash-Proof Session & Unsaved Draft Auto-Recovery Journal (`src/runtime/session_journal.lua`).
-- Periodically snapshots open tabs, cursor/scroll positions, split view, and unsaved dirty/untitled
-- buffers to local disk (`VSRBLX/session_journal.json` via `writefile`) so disconnects, teleports,
-- or game reloads never lose in-progress code.
return function(env)
	local fsx = env.require("runtime/fsx")
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")

	local JOURNAL_PATH = "session_journal.json"
	local MAX_DRAFT_BYTES = 180000

	local M = {
		enabled = true,
		restoring = false,
		recoveredDrafts = 0,
		lastSavedAt = nil,
	}

	function M.buildSnapshot()
		local tabsOut = {}
		for _, doc in ipairs(codeStore.tabs) do
			if not doc.isDiff and not util.startsWith(doc.id, "virtual:") then
				local entry = {
					id = doc.id,
					path = doc.path,
					title = doc.title,
					langId = doc.langId,
					untitled = doc.untitled == true,
					pinned = doc.pinned == true,
					dirty = doc.dirty == true,
					cursor = doc.view and doc.view.cursor or 1,
					scrollX = doc.view and doc.view.scrollX or 0,
					scrollY = doc.view and doc.view.scrollY or 0,
				}
				if (doc.dirty or doc.untitled) and type(doc.content) == "string" and #doc.content <= MAX_DRAFT_BYTES then
					entry.draftContent = doc.content
				end
				tabsOut[#tabsOut + 1] = entry
			end
		end

		return {
			version = 1,
			workspace = workspaceFs.activeName,
			savedAt = clock.timestamp(),
			activeId = codeStore.activeId,
			secondaryId = codeStore.secondaryId,
			splitOpen = codeStore.splitOpen == true,
			focusedPane = codeStore.focusedPane,
			tabs = tabsOut,
		}
	end

	function M.saveNow()
		if not M.enabled or M.restoring then return false end
		local snap = M.buildSnapshot()
		local encoded = util.jsonEncode(snap)
		if not encoded then return false end
		local ok = fsx.write(JOURNAL_PATH, encoded)
		if ok then
			M.lastSavedAt = snap.savedAt
		end
		return ok
	end

	local debouncedSave = clock.debounce(0.55, function()
		M.saveNow()
	end)

	function M.restore()
		local raw = fsx.read(JOURNAL_PATH)
		if type(raw) ~= "string" or raw == "" then
			return false, 0
		end
		local snap = util.jsonDecode(raw)
		if type(snap) ~= "table" or type(snap.tabs) ~= "table" or #snap.tabs == 0 then
			return false, 0
		end
		if snap.workspace and snap.workspace ~= workspaceFs.activeName then
			return false, 0
		end

		M.restoring = true
		local openedCount = 0
		local recoveredDrafts = 0
		local idRemap = {}

		for _, t in ipairs(snap.tabs) do
			if type(t) == "table" then
				local doc = nil
				if t.untitled then
					doc = codeStore.newUntitled(t.draftContent or "", t.langId or "luau")
					if doc and type(t.title) == "string" and t.title ~= "" then
						doc.title = t.title
					end
					if doc and t.draftContent and t.draftContent ~= "" then
						doc.dirty = t.dirty ~= false
						recoveredDrafts = recoveredDrafts + 1
					end
				elseif type(t.path) == "string" and t.path ~= "" and workspaceFs.exists(t.path) then
					doc = codeStore.openFile(t.path)
					if doc and t.dirty and type(t.draftContent) == "string" and t.draftContent ~= doc.content then
						doc.content = t.draftContent:gsub("\r\n", "\n")
						doc.dirty = true
						recoveredDrafts = recoveredDrafts + 1
					end
				end

				if doc then
					openedCount = openedCount + 1
					if t.id then idRemap[t.id] = doc.id end
					doc.pinned = t.pinned == true
					if t.langId then doc.langId = t.langId end
					doc.view.scrollX = tonumber(t.scrollX) or 0
					doc.view.scrollY = tonumber(t.scrollY) or 0
					codeStore.setCursor(doc.id, tonumber(t.cursor) or 1, -1)
				end
			end
		end

		if snap.splitOpen and snap.secondaryId and idRemap[snap.secondaryId] then
			codeStore.splitOpen = true
			codeStore.secondaryId = idRemap[snap.secondaryId]
		end
		if snap.activeId and idRemap[snap.activeId] then
			codeStore.activeId = idRemap[snap.activeId]
		end
		if snap.focusedPane == "secondary" and codeStore.splitOpen then
			codeStore.focusedPane = "secondary"
		end

		M.restoring = false
		M.recoveredDrafts = recoveredDrafts
		if openedCount > 0 then
			codeStore.changed:fire({ reason = "journalRestore" })
			if recoveredDrafts > 0 then
				log.info("session", string.format("Recovered %d unsaved draft(s) from session journal.", recoveredDrafts))
			end
		end
		return openedCount > 0, recoveredDrafts
	end

	function M.clear()
		fsx.delete(JOURNAL_PATH)
	end

	codeStore.changed:connect(function()
		if not M.restoring then
			debouncedSave.call()
		end
	end)
	codeStore.cursorChanged:connect(function()
		if not M.restoring then
			debouncedSave.call()
		end
	end)

	return M
end
end)()

