		local DRAWER_TABS = {
			{ id = "explorer", label = "Files" },
			{ id = "search", label = "Search" },
			{ id = "scm", label = "Git" },
			{ id = "debug", label = "Run" },
			{ id = "extensions", label = "Ext" },
			{ id = "settings", label = "⚙" },
