				bg = (dSpec.id == activeViewlet) and theme.color.accent or theme.color.inputBg,
				hoverBg = theme.color.hover,
				color = (dSpec.id == activeViewlet) and Color3.fromRGB(255, 255, 255) or theme.color.sideBarText,
				bold = true,
