				local order = { "vscode", "sublime", "touch" }
				local cur = tostring(config.get("keybindings.preset", "vscode"))
				local nextIdx = 1
				for i, p in ipairs(order) do
					if p == cur then nextIdx = (i % #order) + 1; break end
