		local function ensureGuideWidget(idx)
			if not guidePool[idx] then
				guidePool[idx] = P.frame(guidesLayer, {
					name = "IndentGuide_" .. tostring(idx),
					size = UDim2.fromOffset(1, 20),
					bg = theme.color.border,
					transparency = 0.45,
