					text = "",
					radius = 2,
					border = Color3.fromRGB(255, 255, 255),
					visible = false,
					zIndex = 22,
				})
				btn.BackgroundTransparency = 0
				swatchPool[idx] = { btn = btn, spec = nil, line = 1, yPx = 0 }
				btn.Activated:Connect(function()
					local entry = swatchPool[idx]
					if not entry or not entry.spec or not currentDoc or currentDoc.readOnly then return end
					local targetDocId = currentDoc.id
					local targetLine = entry.line
					local pickerSpec = {
						r = entry.spec.r,
						g = entry.spec.g,
						b = entry.spec.b,
						first = entry.spec.first,
						last = entry.spec.last,
						format = entry.spec.format,
						alphaTail = entry.spec.alphaTail,
					}
					pickerSpec.onApply = function(newLiteral, _r, _g, _b, prevLast)
						local liveDoc = codeStore.get(targetDocId)
						if not liveDoc then return end
						local updated = colorUtils.replaceColorOnLine(
							liveDoc.content,
							targetLine,
							pickerSpec.first,
							prevLast or pickerSpec.last,
							newLiteral
						)
						codeStore.updateContent(targetDocId, updated)
					end
					local relY = math.max(26, entry.yPx - scroll.CanvasPosition.Y)
					colorPicker.open(pickerSpec, gutterW + 16, relY)
				end)
			end
			return swatchPool[idx]
		end

		local function indentSpacesOf(lineStr, tabSz)
			local count = 0
			for i = 1, #lineStr do
				local c = lineStr:sub(i, i)
				if c == " " then
					count = count + 1
				elseif c == "\t" then
					count = count + tabSz
				else
					break
				end
			end
			return count
		end

		local function drawVisibleLines()
			if not currentDoc or not lexCache then return end
			local lh = theme.sizes.editorLineHeight
			local fontSz = theme.sizes.editorFont
			local tabSz = tonumber(config.get("editor.tabSize", 4)) or 4
			local useRainbow = config.get("editor.bracketPairColorization", true) ~= false
			local showGuides = config.get("editor.indentGuides", true) ~= false
			local showSticky = config.get("editor.stickyScroll", true) ~= false
			local showErrorLens = config.get("editor.inlineErrorLens", true) ~= false

			box.Font = theme.font.mono
			box.TextSize = fontSz
			box.LineHeight = lh / math.max(1, fontSz)
			box.TextWrapped = config.get("editor.wordWrap", false) == true

			local totalLines = #lexCache.lines
			local maxChars = 40
			for i = 1, totalLines do
				if #lexCache.lines[i] > maxChars then maxChars = #lexCache.lines[i] end
			end
			local charPx = math.max(6, math.floor(fontSz * 0.6 + 0.5))
			local contentW = math.max(scroll.AbsoluteSize.X, gutterW + maxChars * charPx + 120)
			local contentH = math.max(scroll.AbsoluteSize.Y, totalLines * lh + 64)

			scroll.CanvasSize = UDim2.fromOffset(contentW, contentH)
			box.Size = UDim2.fromOffset(contentW - gutterW - 12, contentH - 12)
			gutter.Size = UDim2.fromOffset(gutterW, contentH)
			swatchLayer.Size = UDim2.fromOffset(gutterW, contentH)
			guidesLayer.Size = UDim2.fromOffset(contentW - gutterW - 12, contentH - 12)
			presentationLayer.Size = UDim2.fromOffset(contentW - gutterW - 12, contentH - 12)

			local scrollY = scroll.CanvasPosition.Y
			local topScrolledLine = math.floor(scrollY / lh) + 1
			local viewH = math.max(240, scroll.AbsoluteSize.Y)
			local firstVisible = math.max(1, topScrolledLine - 2)
			local lastVisible = math.min(totalLines, firstVisible + math.ceil(viewH / lh) + 6)

			-- Sticky Scroll Calculation
			local activeScopeSym = nil
			if showSticky and topScrolledLine > 1 and #docSymbols > 0 then
				for _, sym in ipairs(docSymbols) do
					if sym.line < topScrolledLine then
						local regionEnd = foldRegions[sym.line] or (sym.line + 40)
						if topScrolledLine <= regionEnd then
							activeScopeSym = sym
						end
					else
						break
					end
				end
			end
			if activeScopeSym and lexCache.lines[activeScopeSym.line] then
				stickyTargetLine = activeScopeSym.line
				stickyLineNum.Text = tostring(activeScopeSym.line)
				stickyCodeLbl.Text = codeLexer.rich(
					util.trim(lexCache.lines[activeScopeSym.line]),
					lexCache.spans[activeScopeSym.line],
					theme.syntax,
					{ rainbow = useRainbow }
				)
				stickyBar.Visible = true
			else
				stickyBar.Visible = false
			end

			local diagMap = {}
			for _, d in ipairs(diagnostics.byDoc[currentDoc.id] or {}) do
				if not diagMap[d.line] or d.severity == "error" then
					diagMap[d.line] = d
				end
			end

			local curLine = currentDoc.view.line or 1
			local curLineIndentLevels = math.floor(indentSpacesOf(lexCache.lines[curLine] or "", tabSz) / tabSz)

			activeLineHighlight.Visible = config.get("editor.renderActiveLine", true) ~= false
			activeLineHighlight.Position = UDim2.fromOffset(0, 6 + (curLine - 1) * lh)
			activeLineHighlight.Size = UDim2.fromOffset(contentW, lh)
			activeLineHighlight.BackgroundColor3 = theme.color.activeLine

			local hasSelection = isFocused and box.SelectionStart > 0 and box.CursorPosition > 0 and box.SelectionStart ~= box.CursorPosition
			box.TextTransparency = hasSelection and 0 or 1
			box.TextColor3 = theme.color.editorText

			local slot = 0
			local guideCount = 0
			local swatchCount = 0
			local lastNonBlankLevels = 0

			for ln = firstVisible, lastVisible do
				slot = slot + 1
				local lineStr = lexCache.lines[ln] or ""
				local codeLbl, numLbl, dot, squiggle, errLens, gitBar = ensureRowWidgets(slot)
				codeLbl.Visible = not hasSelection
				codeLbl.Position = UDim2.fromOffset(0, (ln - 1) * lh)
				codeLbl.Size = UDim2.fromOffset(contentW - gutterW - 16, lh)
				codeLbl.TextSize = fontSz
				codeLbl.TextColor3 = theme.color.editorText
				codeLbl.Text = codeLexer.rich(lineStr, lexCache.spans[ln], theme.syntax, { rainbow = useRainbow })

				numLbl.Visible = true
				numLbl.Position = UDim2.fromOffset(4, 6 + (ln - 1) * lh)
				numLbl.Size = UDim2.fromOffset(gutterW - 20, lh)
				numLbl.TextSize = math.max(11, fontSz - 1)
				numLbl.Text = tostring(ln)
				numLbl.TextColor3 = (ln == curLine) and theme.color.lineNumberActive or theme.color.lineNumber

				-- Live Git Gutter Diff Bar (green = add, blue = modify, red = delete)
				local gKind = gitLineMarkers[ln]
				if gKind then
					gitBar.Visible = true
					if gKind == "add" then
						gitBar.BackgroundColor3 = theme.color.good
						gitBar.Position = UDim2.fromOffset(gutterW - 4, 6 + (ln - 1) * lh + 1)
						gitBar.Size = UDim2.fromOffset(3, lh - 2)
					elseif gKind == "modify" then
						gitBar.BackgroundColor3 = theme.color.accent
						gitBar.Position = UDim2.fromOffset(gutterW - 4, 6 + (ln - 1) * lh + 1)
						gitBar.Size = UDim2.fromOffset(3, lh - 2)
					else
						gitBar.BackgroundColor3 = theme.color.bad
						gitBar.Position = UDim2.fromOffset(gutterW - 6, 6 + (ln - 1) * lh + lh - 4)
						gitBar.Size = UDim2.fromOffset(5, 4)
					end
				else
					gitBar.Visible = false
				end

				-- Vertical Indent Guides
				if showGuides then
					local levels = 0
					if lineStr:find("%S") then
						levels = math.floor(indentSpacesOf(lineStr, tabSz) / tabSz)
						lastNonBlankLevels = levels
					else
						levels = lastNonBlankLevels
					end
					for lv = 1, math.min(levels, 8) do
						guideCount = guideCount + 1
						local gBar = ensureGuideWidget(guideCount)
						local gx = (lv - 1) * tabSz * charPx
						local isActiveGuide = (lv == curLineIndentLevels)
						gBar.Position = UDim2.fromOffset(gx, (ln - 1) * lh)
						gBar.Size = UDim2.fromOffset(1, lh)
						gBar.BackgroundColor3 = isActiveGuide and theme.color.muted or theme.color.border
						gBar.BackgroundTransparency = isActiveGuide and 0.25 or 0.58
						gBar.Visible = true
					end
				end

				-- Inline Color Swatch Detection
				local colorsFound = colorUtils.findColorsInLine(lineStr)
				if #colorsFound > 0 then
					swatchCount = swatchCount + 1
					local sw = ensureSwatchWidget(swatchCount)
					local firstColor = colorsFound[1]
					local yPos = 6 + (ln - 1) * lh + math.floor((lh - 11) / 2)
					sw.spec = firstColor
					sw.line = ln
					sw.yPx = yPos
					sw.btn.BackgroundColor3 = firstColor.color3
					sw.btn.Position = UDim2.fromOffset(gutterW - 14, yPos)
					sw.btn.Visible = true
				end

				-- Diagnostics Gutter Dot + Inline Squiggle Underline + Error Lens
				local diagItem = diagMap[ln]
				if diagItem then
					local isErr = (diagItem.severity == "error")
					local sevCol = isErr and theme.color.bad or theme.color.warn
					dot.Visible = true
					dot.Position = UDim2.fromOffset(3, 6 + (ln - 1) * lh + math.floor((lh - 5) / 2))
					dot.BackgroundColor3 = sevCol

					if showErrorLens and not hasSelection then
						local leadLen = #(lineStr:match("^(%s*)") or "")
						local trimmedLen = math.max(3, #util.trim(lineStr))
						local underX = leadLen * charPx
						local underW = math.min(360, trimmedLen * charPx)
						squiggle.Position = UDim2.fromOffset(underX, (ln - 1) * lh + lh - 3)
						squiggle.Size = UDim2.fromOffset(underW, 2)
						squiggle.BackgroundColor3 = sevCol
						squiggle.BackgroundTransparency = isErr and 0.08 or 0.22
						squiggle.Visible = true

						errLens.Position = UDim2.fromOffset((#lineStr + 3) * charPx, (ln - 1) * lh)
						errLens.Text = (isErr and "⊗ " or "⚠ ") .. tostring(diagItem.message or "")
						errLens.TextColor3 = sevCol
						errLens.TextTransparency = 0.25
						errLens.Visible = true
					else
						squiggle.Visible = false
						errLens.Visible = false
					end
				else
					dot.Visible = false
					squiggle.Visible = false
					errLens.Visible = false
				end
			end

			for k = slot + 1, #linePool do
				linePool[k].Visible = false
				numPool[k].Visible = false
				diagDotPool[k].Visible = false
				squigglePool[k].Visible = false
				errorLensPool[k].Visible = false
				if gitBarPool[k] then gitBarPool[k].Visible = false end
			end
			for k = guideCount + 1, #guidePool do
				guidePool[k].Visible = false
			end
			for k = swatchCount + 1, #swatchPool do
				swatchPool[k].btn.Visible = false
			end

			-- Update Caret position
			if isFocused and not hasSelection and currentDoc and not currentDoc.readOnly then
				local col = math.max(1, currentDoc.view.col or 1)
				local lineStr = lexCache.lines[curLine] or ""
				local subBefore = lineStr:sub(1, col - 1):gsub("\t", string.rep(" ", tabSz))
				local effGutter = gutter.Visible and gutterW or 8
				local xPx = effGutter + 8 + #subBefore * charPx
				local yPx = 6 + (curLine - 1) * lh
				caretBar.Position = UDim2.fromOffset(xPx, yPx)
				caretBar.Size = UDim2.fromOffset(2, lh)
				caretBar.Visible = true
			else
				caretBar.Visible = false
			end

			minimap.updateViewport(scrollY, viewH, contentH)
		end

		local function applyEditResult(nextText, nextCursor, nextSel)
			if not currentDoc or currentDoc.readOnly then return false end
			syncingText = true
			box.Text = nextText
			if nextSel and nextSel > 0 then
				box.SelectionStart = nextSel
			else
				box.SelectionStart = -1
			end
			box.CursorPosition = nextCursor or 1
			syncingText = false
			codeStore.updateContent(currentDoc.id, nextText)
			codeStore.setCursor(currentDoc.id, nextCursor or 1, nextSel or -1)
			lexCache = codeLexer.scan(currentDoc.content, currentDoc.langId, lexCache)
			updateSymbolsAndRegions()
			minimap.updateSource(lexCache)
			debouncedDiag.call()
			drawVisibleLines()
			return true
		end

		local KIND_BADGES = {
			snippet = { icon = "⇥", col = "func" },
			method = { icon = "ƒ", col = "func" },
			["function"] = { icon = "ƒ", col = "func" },
			constructor = { icon = "▣", col = "type" },
			class = { icon = "▣", col = "type" },
			property = { icon = "◈", col = "number" },
			event = { icon = "⚡", col = "keyword" },
			instance = { icon = "⬡", col = "type" },
			enum = { icon = "∈", col = "number" },
			executor = { icon = "⚙", col = "keyword" },
			module = { icon = "📦", col = "string" },
			variable = { icon = "𝑥", col = "ident" },
			keyword = { icon = "🔑", col = "keyword" },
			builtin = { icon = "λ", col = "func" },
			type = { icon = "𝑇", col = "type" },
			symbol = { icon = "◦", col = "comment" },
		}

		local function acceptSuggestion(item)
			if not currentDoc or not item then return end
			suggestCard.Visible = false
			local src = box.Text
			local before = src:sub(1, suggestSpanStart - 1)
			local after = src:sub(suggestSpanEnd + 1)
			local expanded, caretOffset = intellisense.expandInsert(item.insert)
			local nextText = before .. expanded .. after
			applyEditResult(nextText, #before + caretOffset + 1, -1)
		end

		local function refreshSignatureHelp()
			if not isFocused or not currentDoc or currentDoc.readOnly
				or config.get("editor.intellisense", true) == false then
				sigHelpCard.Visible = false
				return
			end
			local sig = intellisense.signatureHelp(box.Text, box.CursorPosition, currentDoc.langId, currentDoc.path)
			if not sig then
				sigHelpCard.Visible = false
				return
			end
			local escParts = {}
			for i, p in ipairs(sig.params or {}) do
				local ep = util.escapeRichText(p)
				if i == sig.activeParam or (i == #(sig.params or {}) and p:find("^%.%.%.")) then
					escParts[#escParts + 1] = string.format('<font color="#%s"><b>%s</b></font>', theme.color.accent:ToHex(), ep)
				else
					escParts[#escParts + 1] = ep
				end
			end
			sigHelpLbl.Text = string.format(
				"%s(%s) -> %s",
				util.escapeRichText(sig.name),
				table.concat(escParts, ", "),
				util.escapeRichText(sig.ret or "()")
			)
			sigHelpDoc.Text = sig.doc or ""
			local lh = theme.sizes.editorLineHeight
			local curLine = currentDoc.view.line or 1
			local aboveY = math.max(4, 6 + (curLine - 1) * lh - scroll.CanvasPosition.Y - 46)
			sigHelpCard.Position = UDim2.fromOffset(gutterW + 20, aboveY)
			sigHelpCard.Visible = true
		end

		local function renderSuggestionsUI()
			if #currentSuggestions == 0 then
				suggestCard.Visible = false
				return
			end
			selectedSuggestIdx = util.clamp(selectedSuggestIdx, 1, #currentSuggestions)
			suggestCard:ClearAllChildren()
			P.pad(suggestCard, 4, 5, 4, 5)
			P.list(suggestCard, Enum.FillDirection.Vertical, 1)

			local selItem = currentSuggestions[selectedSuggestIdx]
			local hasFooter = selItem and ((selItem.signature and selItem.signature ~= "") or (selItem.doc and selItem.doc ~= ""))
			local footerH = hasFooter and 38 or 0
			suggestCard.Size = UDim2.fromOffset(348, #currentSuggestions * 23 + 10 + footerH)

			local lh = theme.sizes.editorLineHeight
			local curLine = currentDoc.view.line or 1
			local relY = util.clamp(10 + curLine * lh - scroll.CanvasPosition.Y, 28, math.max(30, codeSurface.AbsoluteSize.Y - 210))
			suggestCard.Position = UDim2.fromOffset(gutterW + 24, relY)
			suggestCard.Visible = true

			for idx, sug in ipairs(currentSuggestions) do
				local badge = KIND_BADGES[sug.kind] or KIND_BADGES.symbol
				local row = P.button(suggestCard, {
					name = "Suggest_" .. tostring(idx),
					size = UDim2.new(1, 0, 0, 22),
					bg = idx == selectedSuggestIdx and theme.color.listActive or nil,
					hoverBg = theme.color.listActive,
					text = "",
					radius = 3,
					order = idx,
					zIndex = 46,
					onClick = function() acceptSuggestion(sug) end,
				})
				P.label(row, {
					size = UDim2.fromOffset(18, 22),
					pos = UDim2.fromOffset(4, 0),
					text = badge.icon,
					mono = true,
					bold = true,
					textSize = 11,
					alignX = Enum.TextXAlignment.Center,
					color = theme.syntax[badge.col] or theme.color.accent,
					zIndex = 47,
				})
				P.label(row, {
					size = UDim2.new(1, -120, 1, 0),
					pos = UDim2.fromOffset(24, 0),
					text = sug.label,
					mono = true,
					textSize = 12,
					color = theme.color.tabActiveText,
					truncate = true,
					zIndex = 47,
				})
				P.label(row, {
					size = UDim2.fromOffset(92, 22),
					pos = UDim2.new(1, -96, 0, 0),
					text = sug.detail,
					textSize = 10,
					color = theme.color.muted,
					alignX = Enum.TextXAlignment.Right,
					truncate = true,
					zIndex = 47,
				})
			end

			if hasFooter then
				local docBox = P.frame(suggestCard, {
					name = "SuggestDocFooter",
					size = UDim2.new(1, 0, 0, 36),
					bg = theme.color.sideBar,
					radius = 3,
					order = 99,
					zIndex = 46,
				})
				P.pad(docBox, 3, 6, 3, 6)
				P.label(docBox, {
					name = "SuggestDocSig",
					size = UDim2.new(1, 0, 0, 14),
					mono = true,
					textSize = 10,
					color = theme.color.accent,
					text = (selItem.signature ~= "" and selItem.signature) or selItem.label,
					truncate = true,
					zIndex = 47,
				})
				P.label(docBox, {
					name = "SuggestDocText",
					size = UDim2.new(1, 0, 0, 16),
					pos = UDim2.fromOffset(0, 15),
					textSize = 10,
					color = theme.color.muted,
					text = selItem.doc or "",
					truncate = true,
					zIndex = 47,
				})
			end
		end

		local function refreshIntelliSense(forceOpen)
			if (not forceOpen and not isFocused) or not currentDoc or currentDoc.readOnly
				or config.get("editor.intellisense", true) == false then
				suggestCard.Visible = false
				return
			end
			local curOff = box.CursorPosition > 0 and box.CursorPosition or (currentDoc.view.cursor or 1)
			local items, _, sIdx, eIdx = intellisense.suggest(box.Text, curOff, currentDoc.langId, 7, currentDoc.path)
			currentSuggestions = items
			selectedSuggestIdx = 1
			suggestSpanStart, suggestSpanEnd = sIdx, eIdx
			renderSuggestionsUI()
			refreshSignatureHelp()
		end

		local function showHoverAtCursor()
			if not currentDoc then return nil end
			local curOff = box.CursorPosition > 0 and box.CursorPosition or (currentDoc.view.cursor or 1)
			local info = intellisense.hover(currentDoc.content, curOff, currentDoc.langId, currentDoc.path)
			if not info then
				hoverCard.Visible = false
				return nil
			end
			hoverTitleLbl.Text = string.format("%s  ·  %s", info.title or "", info.kind or "symbol")
			hoverSigLbl.Text = info.signature or ""
			hoverDocLbl.Text = info.doc or ""
			if info.line then
				hoverDefTarget = { file = info.file, line = info.line }
				hoverGotoBtn.Visible = true
			else
				hoverDefTarget = nil
				hoverGotoBtn.Visible = false
			end
			local lh = theme.sizes.editorLineHeight
			local curLine = currentDoc.view.line or 1
			local relY = util.clamp(8 + curLine * lh - scroll.CanvasPosition.Y, 24, math.max(26, codeSurface.AbsoluteSize.Y - 120))
			hoverCard.Position = UDim2.fromOffset(gutterW + 24, relY)
			hoverCard.Visible = true
			return info
		end

		local function gotoDefinitionAtCursor()
			if not currentDoc then return nil end
			local curOff = box.CursorPosition > 0 and box.CursorPosition or (currentDoc.view.cursor or 1)
			local def = intellisense.findDefinition(currentDoc.content, curOff, currentDoc.langId, currentDoc.path)
			if not def then return nil end
			if def.file and def.file ~= "" and def.file ~= currentDoc.path then
				local targetDoc = codeStore.openFile(def.file)
				if targetDoc then
					codeStore.jumpToLine(targetDoc.id, def.line or 1, 1)
				end
			else
				codeStore.jumpToLine(currentDoc.id, def.line or 1, 1)
			end
			return def
		end

		local function mountDoc(doc)
			local switchedDoc = (doc ~= currentDoc)
			currentDoc = doc
			suggestCard.Visible = false
			sigHelpCard.Visible = false
			if switchedDoc then
				hoverCard.Visible = false
				colorPicker.close()
			end
			if not doc then
				codeSurface.Visible = false
				diffViewer.root.Visible = false
				welcome.root.Visible = true
				welcome.refresh()
				return
			end
			if doc.isDiff then
				welcome.root.Visible = false
				codeSurface.Visible = false
				diffViewer.root.Visible = true
				diffViewer.render(doc)
				return
			end

			welcome.root.Visible = false
			diffViewer.root.Visible = false
			codeSurface.Visible = true

			box.TextEditable = not doc.readOnly
			if box.Text ~= doc.content then
				syncingText = true
				box.Text = doc.content
				box.CursorPosition = doc.view.cursor or 1
				syncingText = false
			end
			lexCache = codeLexer.scan(doc.content, doc.langId, lexCache)
			updateSymbolsAndRegions()
			minimap.updateSource(lexCache)
			debouncedDiag.call()
			updateLayoutWidths()
			drawVisibleLines()
			if doc.view.scrollY then
				scroll.CanvasPosition = Vector2.new(doc.view.scrollX or 0, doc.view.scrollY or 0)
			end
		end

		box.Focused:Connect(function()
			isFocused = true
			codeStore.focusedPane = pane
			drawVisibleLines()
		end)

		box.FocusLost:Connect(function()
			isFocused = false
			task.delay(0.15, function()
				if not isFocused then
					suggestCard.Visible = false
					sigHelpCard.Visible = false
				end
			end)
			drawVisibleLines()
		end)

		box:GetPropertyChangedSignal("Text"):Connect(function()
			if syncingText or not currentDoc or currentDoc.readOnly then return end
			local raw = box.Text
			local prev = currentDoc.content
			local smartText, smartCursor = editorActions.applySmartTyping(prev, raw, box.CursorPosition, {
				langId = currentDoc.langId,
				tabSize = config.get("editor.tabSize", 4),
				insertSpaces = config.get("editor.insertSpaces", true),
				autoClosingBrackets = config.get("editor.autoClosingBrackets", true),
				autoIndent = config.get("editor.autoIndent", true),
			})
			if smartText ~= raw then
				syncingText = true
				box.Text = smartText
				box.CursorPosition = smartCursor
				syncingText = false
			end
			codeStore.updateContent(currentDoc.id, smartText)
			lexCache = codeLexer.scan(currentDoc.content, currentDoc.langId, lexCache)
			updateSymbolsAndRegions()
			minimap.updateSource(lexCache)
			codeStore.setCursor(currentDoc.id, box.CursorPosition, box.SelectionStart)
			debouncedDiag.call()
			drawVisibleLines()
			refreshIntelliSense()
		end)

		box:GetPropertyChangedSignal("CursorPosition"):Connect(function()
			if syncingText or not currentDoc then return end
			codeStore.setCursor(currentDoc.id, box.CursorPosition, box.SelectionStart)
			drawVisibleLines()
			refreshSignatureHelp()
		end)

		box:GetPropertyChangedSignal("SelectionStart"):Connect(function()
			if syncingText or not currentDoc then return end
			-- Capture newly selected text ≥ 3 chars into clipboard ring when copied/selected on Ctrl+C
			drawVisibleLines()
		end)

		scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			if currentDoc then
				currentDoc.view.scrollX = scroll.CanvasPosition.X
				currentDoc.view.scrollY = scroll.CanvasPosition.Y
			end
			drawVisibleLines()
		end)

		-- Find & Replace handlers
		local function runFind()
			if not currentDoc then return end
			findMatches = codeSearch.findInText(currentDoc.content, findInput.Text, {})
			if #findMatches == 0 then
				findIndex = 0
				matchCounter.Text = "0/0"
			else
				findIndex = ((findIndex) % #findMatches) + 1
				matchCounter.Text = string.format("%d/%d", findIndex, #findMatches)
				local hit = findMatches[findIndex]
				codeStore.jumpToLine(currentDoc.id, hit.line, hit.col)
			end
		end

		findInput:GetPropertyChangedSignal("Text"):Connect(function()
			findIndex = 0
			runFind()
		end)
		findNextBtn.Activated:Connect(runFind)

		replaceOneBtn.Activated:Connect(function()
			if not currentDoc or findInput.Text == "" then return end
			local updated, count = codeSearch.replaceInText(currentDoc.content, findInput.Text, replaceInput.Text, {
				singleIndex = math.max(1, findIndex),
			})
			if count > 0 then
				codeStore.updateContent(currentDoc.id, updated)
				mountDoc(currentDoc)
				runFind()
			end
		end)

		replaceAllBtn.Activated:Connect(function()
			if not currentDoc or findInput.Text == "" then return end
			local updated, count = codeSearch.replaceInText(currentDoc.content, findInput.Text, replaceInput.Text, {})
			if count > 0 then
				codeStore.updateContent(currentDoc.id, updated)
				mountDoc(currentDoc)
				runFind()
			end
		end)

		-- Programmatic & Shortcut-Driven Monaco Actions
		local function runAction(actionName, arg)
			if not currentDoc then return false end
			local cur = box.CursorPosition > 0 and box.CursorPosition or (currentDoc.view.cursor or 1)
			local sel = box.SelectionStart

			if actionName == "selectWord" then
				local s, e, word = editorActions.wordAtCursor(currentDoc.content, cur)
				box.SelectionStart = s
				box.CursorPosition = e
				codeStore.setCursor(currentDoc.id, e, s)
				if word ~= "" then clipboard.push(word) end
				drawVisibleLines()
				return true, word
			elseif actionName == "selectLine" then
				local s, e = editorActions.lineBoundsAtCursor(currentDoc.content, cur)
				box.SelectionStart = s
				box.CursorPosition = e
				codeStore.setCursor(currentDoc.id, e, s)
				drawVisibleLines()
				return true
			elseif actionName == "copySelectionOrLine" then
				if sel and sel > 0 and sel ~= cur then
					local a, b = math.min(sel, cur), math.max(sel, cur) - 1
					clipboard.copy(currentDoc.content:sub(a, b))
				else
					local s, e = editorActions.lineBoundsAtCursor(currentDoc.content, cur)
					clipboard.copy(currentDoc.content:sub(s, e - 1))
				end
				return true
			end

			if currentDoc.readOnly then return false end

			if actionName == "toggleComment" then
				local nextText, nextCur = editorActions.toggleComment(currentDoc.content, cur, sel, currentDoc.langId)
				return applyEditResult(nextText, nextCur, -1)
			elseif actionName == "indent" or actionName == "outdent" then
				local nextText, nextCur, nextSel = editorActions.indentBlock(
					currentDoc.content,
					cur,
					sel,
					config.get("editor.tabSize", 4),
					config.get("editor.insertSpaces", true),
					actionName == "outdent"
				)
				return applyEditResult(nextText, nextCur, nextSel)
			elseif actionName == "moveLineUp" or actionName == "moveLineDown" then
				local dir = actionName == "moveLineUp" and -1 or 1
				local nextText, nextCur = editorActions.moveLines(currentDoc.content, cur, sel, dir)
				return applyEditResult(nextText, nextCur, -1)
			elseif actionName == "duplicateLineDown" or actionName == "duplicateLineUp" then
				local dir = actionName == "duplicateLineUp" and -1 or 1
				local nextText, nextCur = editorActions.duplicateLines(currentDoc.content, cur, sel, dir)
				return applyEditResult(nextText, nextCur, -1)
			elseif actionName == "deleteLine" then
				local s, e = editorActions.lineBoundsAtCursor(currentDoc.content, cur)
				clipboard.push(currentDoc.content:sub(s, e - 1))
				local nextText, nextCur = editorActions.deleteLines(currentDoc.content, cur, sel)
				return applyEditResult(nextText, nextCur, -1)
			elseif actionName == "insertText" then
				local insertStr = tostring(arg or "")
				if insertStr == "" then return false end
				local minPos = cur
				local maxPos = cur
				if sel and sel > 0 and sel ~= cur then
					minPos = math.min(sel, cur)
					maxPos = math.max(sel, cur)
				end
				local src = currentDoc.content
				local nextText = src:sub(1, minPos - 1) .. insertStr .. src:sub(maxPos)
				return applyEditResult(nextText, minPos + #insertStr, -1)
			end
			return false
		end

		codeStore.changed:connect(function()
			mountDoc(codeStore.active(pane))
		end)
		diagnostics.changed:connect(function(docId)
			if currentDoc and currentDoc.id == docId then
				drawVisibleLines()
			end
		end)
		gitState.changed:connect(function()
			updateSymbolsAndRegions()
			drawVisibleLines()
		end)
		config.changed:connect(function()
			updateSymbolsAndRegions()
			updateLayoutWidths()
			drawVisibleLines()
		end)
		theme.changed:connect(function()
			gutter.BackgroundColor3 = theme.color.editorGutter
			gutterBorder.BackgroundColor3 = theme.color.border
			stickyBar.BackgroundColor3 = theme.color.sideBarHeader
			stickyBottomBorder.BackgroundColor3 = theme.color.border
			stickyLineNum.TextColor3 = theme.color.muted
			findCard.BackgroundColor3 = theme.color.sideBar
			suggestCard.BackgroundColor3 = theme.color.dropdownBg
			sigHelpCard.BackgroundColor3 = theme.color.dropdownBg
			hoverCard.BackgroundColor3 = theme.color.dropdownBg
			drawVisibleLines()
		end)

		mountDoc(codeStore.active(pane))

		return {
			root = container,
			box = box,
			colorPicker = colorPicker,
			runAction = runAction,
			openFind = function(showReplace)
				findCard.Visible = true
				findCard.Size = UDim2.fromOffset(336, showReplace and 68 or 36)
				replaceInput.Parent.Visible = showReplace == true
				replaceOneBtn.Visible = showReplace == true
				replaceAllBtn.Visible = showReplace == true
				task.defer(function() pcall(function() findInput:CaptureFocus() end) end)
			end,
			triggerSuggest = function()
				refreshIntelliSense(true)
				return currentSuggestions
			end,
			moveSuggestSelection = function(delta)
				if not suggestCard.Visible or #currentSuggestions == 0 then return false end
				local nextIdx = ((selectedSuggestIdx - 1 + (delta or 1)) % #currentSuggestions) + 1
				selectedSuggestIdx = nextIdx
				renderSuggestionsUI()
				return true
			end,
			acceptTopSuggestion = function()
				if suggestCard.Visible and currentSuggestions[selectedSuggestIdx] then
					acceptSuggestion(currentSuggestions[selectedSuggestIdx])
					return true
				end
				return false
			end,
			showHover = showHoverAtCursor,
			gotoDefinition = gotoDefinitionAtCursor,
			refresh = function()
				mountDoc(codeStore.active(pane))
			end,
			setTransparency = function(bgTrans)
				gutter.BackgroundTransparency = bgTrans
				stickyBar.BackgroundTransparency = math.min(0.45, bgTrans * 0.65)
				activeLineHighlight.BackgroundTransparency = math.min(0.92, bgTrans + 0.25)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/explorer
-- ==========================================================================
__VSRBLX_MODULES["ui/code/explorer"] = (function()
-- Collapsible hierarchical File Tree widget with Seti file/folder badges, inline VS Code
-- create/rename input with live validation, and right-click disk actions.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local util = env.require("runtime/util")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")
	local clipboard = env.require("runtime/clipboard")

	local M = {}

	local function validateInlineName(rawName, parentDir, isDir, oldPath)
		local trimmed = util.trim(tostring(rawName or ""))
		if trimmed == "" then
			return false, "A file or folder name must be provided.", ""
		end
		if trimmed == "." or trimmed == ".." then
			return false, "The name '" .. trimmed .. "' is not valid as a file or folder name.", ""
		end
		if trimmed:find("[\\:%*%?\"<>|]") then
			return false, "Name contains invalid characters (\\ : * ? \" < > |).", ""
		end
		if util.startsWith(trimmed, "/") or trimmed:sub(-1) == "/" then
			return false, "Name cannot start or end with a slash.", ""
		end
		local fullRel = parentDir ~= "" and util.joinPath(parentDir, trimmed) or util.normalisePath(trimmed)
		if oldPath and fullRel == oldPath then
			return true, nil, fullRel
		end
		if workspaceFs.exists(fullRel) or workspaceFs.isDir(fullRel) then
			return false, "A file or folder '" .. util.basename(fullRel) .. "' already exists at this location.", fullRel
		end
		return true, nil, fullRel
	end

	function M.new(parent)
		local expanded = { [""] = true, ["src"] = true, ["web"] = true, ["scripts"] = true }
		local inlineState = nil
		local activeInlineBox = nil

		local holder = P.frame(parent, {
			name = "FileTreeContainer",
			size = UDim2.new(1, 0, 0, 200),
			zIndex = 22,
		})
		holder.AutomaticSize = Enum.AutomaticSize.Y
		P.list(holder, Enum.FillDirection.Vertical, 1)

		local rebuild

		local function cancelInline()
			if not inlineState then return end
			inlineState = nil
			activeInlineBox = nil
			rebuild()
		end

		local function commitInline(overrideValue)
			if not inlineState then return false, "no inline edit active" end
			local st = inlineState
			local textVal = overrideValue ~= nil and tostring(overrideValue)
				or (activeInlineBox and activeInlineBox.Text)
				or st.value
				or ""

			-- Unchanged rename -> cleanly cancel without error
			if st.mode == "rename" and util.trim(textVal) == util.basename(st.targetPath) then
				cancelInline()
				return true, st.targetPath
			end

			local valid, errMsg, resolvedPath = validateInlineName(
				textVal,
				st.dir,
				st.mode == "newFolder" or st.isDir,
				st.targetPath
			)
			if not valid then
				st.value = textVal
				st.error = errMsg
				rebuild()
				return false, errMsg
			end

			inlineState = nil
			activeInlineBox = nil

			if st.mode == "newFolder" then
				local ok, err = workspaceFs.createFolder(resolvedPath)
				if ok then
					expanded[resolvedPath] = true
					overlay.toast("Created folder: " .. resolvedPath, "good", 2.2)
					rebuild()
					return true, resolvedPath
				end
				overlay.toast("Error: " .. tostring(err), "bad", 4)
				rebuild()
				return false, err
			elseif st.mode == "newFile" then
				local ok, err = workspaceFs.writeFile(resolvedPath, "")
				if ok then
					codeStore.openFile(resolvedPath, { reloadFromDisk = true })
					overlay.toast("Created file: " .. resolvedPath, "good", 2.2)
					rebuild()
					return true, resolvedPath
				end
				overlay.toast("Error: " .. tostring(err), "bad", 4)
				rebuild()
				return false, err
			elseif st.mode == "rename" then
				local ok, res = workspaceFs.renamePath(st.targetPath, resolvedPath)
				if ok then
					codeStore.renameOpenFile(st.targetPath, res)
					overlay.toast("Renamed to " .. tostring(res), "good", 2.2)
					rebuild()
					return true, res
				end
				overlay.toast("Rename failed: " .. tostring(res), "bad", 4)
				rebuild()
				return false, res
			end
			return false, "unknown inline mode"
		end

		local function startInlineCreate(baseDir, isFolder)
			local dir = util.normalisePath(baseDir or "")
			if dir ~= "" then
				-- Expand ancestor directories so the inline input is immediately visible
				local accum = ""
				for _, seg in ipairs(util.split(dir, "/")) do
					if seg ~= "" then
						accum = accum == "" and seg or (accum .. "/" .. seg)
						expanded[accum] = true
					end
				end
			end
			inlineState = {
				mode = isFolder and "newFolder" or "newFile",
				dir = dir,
				isDir = isFolder == true,
				value = "",
				error = nil,
			}
			rebuild()
		end

		local function startInlineRename(targetPath)
			local clean = util.normalisePath(targetPath or "")
			if clean == "" then return false end
			local dir = util.dirname(clean)
			local isFolder = workspaceFs.isDir(clean)
			inlineState = {
				mode = "rename",
				targetPath = clean,
				dir = dir,
				isDir = isFolder,
				value = util.basename(clean),
				error = nil,
			}
			rebuild()
			return true
		end

		local function renderInlineEditor(depth, orderCounter)
			local st = inlineState
			local indentPx = 8 + depth * 12
			local wrap = P.frame(holder, {
				name = "ExplorerInlineEditor",
				size = UDim2.new(1, 0, 0, st.error and 44 or 24),
				order = orderCounter,
				zIndex = 26,
			})

			local row = P.frame(wrap, {
				name = "InlineInputRow",
				size = UDim2.new(1, -4, 0, 23),
				pos = UDim2.fromOffset(2, 0),
				bg = theme.color.listActive,
				radius = 2,
				zIndex = 26,
			})

			local iconSlot = P.frame(row, {
				name = "InlinePreviewBadge",
				size = UDim2.fromOffset(20, 16),
				pos = UDim2.fromOffset(indentPx + 4, 4),
				zIndex = 27,
			})

			local function updatePreviewBadge(txt)
				iconSlot:ClearAllChildren()
				local probe = util.trim(txt or "") ~= "" and txt or (st.isDir and "folder" or "file.luau")
				icons.fileBadge(iconSlot, probe, st.isDir, 28, false)
			end
			updatePreviewBadge(st.value)

			local boxX = indentPx + 26
			local inputContainer = P.frame(row, {
				name = "InlineFieldFrame",
				size = UDim2.new(1, -(boxX + 42), 0, 19),
				pos = UDim2.fromOffset(boxX, 2),
				bg = theme.color.inputBg,
				radius = 2,
				zIndex = 27,
			})
			local borderStroke = P.stroke(inputContainer, st.error and theme.color.bad or theme.color.inputFocus, 1)

			local tb = Instance.new("TextBox", inputContainer)
			tb.Name = "InlineExplorerInput"
			tb.BackgroundTransparency = 1
			tb.BorderSizePixel = 0
			tb.Size = UDim2.new(1, -8, 1, 0)
			tb.Position = UDim2.fromOffset(4, 0)
			tb.Font = theme.font.mono
			tb.TextSize = 12
			tb.TextColor3 = theme.color.tabActiveText
			tb.PlaceholderColor3 = theme.color.muted
			tb.PlaceholderText = st.isDir and "folder_name" or "script.luau"
			tb.Text = st.value or ""
			tb.ClearTextOnFocus = false
			tb.TextXAlignment = Enum.TextXAlignment.Left
			tb.ZIndex = 28
			activeInlineBox = tb

			local errorBanner = P.frame(wrap, {
				name = "InlineErrorBanner",
				size = UDim2.new(1, -(boxX + 6), 0, 20),
				pos = UDim2.fromOffset(boxX + 2, 23),
				bg = Color3.fromRGB(90, 29, 29),
				border = theme.color.bad,
				radius = 2,
				visible = st.error ~= nil,
				zIndex = 30,
			})
			local errorLbl = P.label(errorBanner, {
				name = "InlineErrorText",
				size = UDim2.new(1, -8, 1, 0),
				pos = UDim2.fromOffset(4, 0),
				text = st.error or "",
				textSize = 10,
				color = Color3.fromRGB(255, 210, 210),
				truncate = true,
				zIndex = 31,
			})

			P.button(row, {
				name = "InlineConfirmBtn",
				size = UDim2.fromOffset(18, 19),
				pos = UDim2.new(1, -38, 0, 2),
				bg = theme.color.accent,
				hoverBg = theme.color.accentHover,
				color = Color3.fromRGB(255, 255, 255),
				bold = true,
				text = "✓",
				textSize = 11,
				radius = 2,
				zIndex = 28,
				onClick = function() commitInline(tb.Text) end,
			})
			P.button(row, {
				name = "InlineCancelBtn",
				size = UDim2.fromOffset(18, 19),
				pos = UDim2.new(1, -19, 0, 2),
				hoverBg = theme.color.hover,
				color = theme.color.muted,
				text = "✕",
				textSize = 10,
				radius = 2,
				zIndex = 28,
				onClick = function() cancelInline() end,
			})

			tb:GetPropertyChangedSignal("Text"):Connect(function()
				st.value = tb.Text
				updatePreviewBadge(tb.Text)
				if util.trim(tb.Text) == "" and st.mode ~= "rename" then
					st.error = nil
					borderStroke.Color = theme.color.inputFocus
					errorBanner.Visible = false
					wrap.Size = UDim2.new(1, 0, 0, 24)
					return
				end
				local ok, errMsg = validateInlineName(tb.Text, st.dir, st.isDir, st.targetPath)
				st.error = ok and nil or errMsg
				borderStroke.Color = ok and theme.color.inputFocus or theme.color.bad
				errorLbl.Text = errMsg or ""
				errorBanner.Visible = not ok
				wrap.Size = UDim2.new(1, 0, 0, ok and 24 or 44)
			end)

			tb.FocusLost:Connect(function(enterPressed)
				if not inlineState then return end
				if enterPressed then
					commitInline(tb.Text)
				elseif util.trim(tb.Text) == "" then
					cancelInline()
				end
			end)

			task.defer(function()
				pcall(function() tb:CaptureFocus() end)
			end)
		end

		rebuild = function()
			activeInlineBox = nil
			holder:ClearAllChildren()
			P.list(holder, Enum.FillDirection.Vertical, 1)
			local activeDoc = codeStore.active()
			local activePath = activeDoc and activeDoc.path or nil
			local orderCounter = 0

			local function renderDir(dirPath, depth)
				if depth > 10 then return end

				if inlineState and (inlineState.mode == "newFile" or inlineState.mode == "newFolder") and inlineState.dir == dirPath then
					orderCounter = orderCounter + 1
					renderInlineEditor(depth, orderCounter)
				end

				local entries = workspaceFs.listDir(dirPath)
				for _, entry in ipairs(entries) do
					if inlineState and inlineState.mode == "rename" and inlineState.targetPath == entry.path then
						orderCounter = orderCounter + 1
						renderInlineEditor(depth, orderCounter)
					else
						orderCounter = orderCounter + 1
						local isSelected = (not entry.isDir) and (entry.path == activePath)
						local isOpenFolder = entry.isDir and expanded[entry.path] == true
						local row = P.button(holder, {
							name = "Tree_" .. entry.name,
							size = UDim2.new(1, 0, 0, 22),
							bg = isSelected and theme.color.listActive or nil,
							hoverBg = theme.color.hover,
							text = "",
							order = orderCounter,
							zIndex = 23,
							activeState = function() return isSelected end,
							onClick = function()
								if entry.isDir then
									expanded[entry.path] = not expanded[entry.path]
									rebuild()
								else
									codeStore.openFile(entry.path)
								end
							end,
						})

						local indentPx = 8 + depth * 12
						if entry.isDir then
							P.label(row, {
								size = UDim2.fromOffset(12, 22),
								pos = UDim2.fromOffset(indentPx, 0),
								text = isOpenFolder and "▾" or "▸",
								textSize = 11,
								color = theme.color.muted,
								zIndex = 24,
							})
						end

						local badge = icons.fileBadge(row, entry.path, entry.isDir, 24, isOpenFolder)
						badge.Position = UDim2.fromOffset(indentPx + (entry.isDir and 13 or 4), 4)

						local nameX = indentPx + (entry.isDir and 33 or 27)
						P.label(row, {
							size = UDim2.new(1, -(nameX + 8), 1, 0),
							pos = UDim2.fromOffset(nameX, 0),
							text = entry.name,
							textSize = 12,
							color = isSelected and theme.color.tabActiveText or theme.color.sideBarText,
							truncate = true,
							zIndex = 24,
						})

						row.MouseButton2Click:Connect(function()
							local p = row.AbsolutePosition
							local targetDir = entry.isDir and entry.path or util.dirname(entry.path)
							local menu = {
								{ label = "New File...", onClick = function() startInlineCreate(targetDir, false) end },
								{ label = "New Folder...", onClick = function() startInlineCreate(targetDir, true) end },
								{ separator = true },
							}
							if not entry.isDir then
								menu[#menu + 1] = {
									label = "Open to the Side",
									onClick = function() codeStore.openFile(entry.path, { pane = "secondary" }) end,
								}
							end
							menu[#menu + 1] = {
								label = "Copy Relative Path",
								onClick = function()
									clipboard.copy(entry.path)
									overlay.toast("Copied path: " .. entry.path, "info", 1.8)
								end,
							}
							menu[#menu + 1] = { label = "Rename", shortcut = "F2", onClick = function() startInlineRename(entry.path) end }
							menu[#menu + 1] = {
								label = "Delete from Disk",
								onClick = function()
									overlay.confirm({
										title = "Delete '" .. entry.name .. "' from disk?",
										message = "This will remove '" .. entry.path .. "' from the active workspace.",
										primaryText = "Delete",
										cancelText = "Cancel",
										onPrimary = function()
											workspaceFs.deletePath(entry.path)
											local openDoc = codeStore.findByPath(entry.path)
											if openDoc then codeStore.close(openDoc.id, { force = true }) end
											overlay.toast("Deleted " .. entry.path, "warn", 2.5)
										end,
									})
								end,
							}
							overlay.dropdown(p.X + 24, p.Y + 18, menu, 190)
						end)
					end

					if entry.isDir and expanded[entry.path] then
						renderDir(entry.path, depth + 1)
					end
				end
			end

			renderDir("", 0)
		end

		workspaceFs.changed:connect(rebuild)
		codeStore.changed:connect(rebuild)
		theme.changed:connect(rebuild)

		rebuild()
		return {
			root = holder,
			refresh = rebuild,
			promptNewFile = function(dir) startInlineCreate(dir or "", false) end,
			promptNewFolder = function(dir) startInlineCreate(dir or "", true) end,
			startRename = startInlineRename,
			getInlineState = function() return inlineState end,
			commitInline = commitInline,
			cancelInline = cancelInline,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/minimap
-- ==========================================================================
__VSRBLX_MODULES["ui/code/minimap"] = (function()
-- VS Code Right-Side Code Minimap with miniature colorized bars and clickable viewport slider.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local util = env.require("runtime/util")

	local M = {}

	function M.new(parent, onJumpRatio)
		local width = 72
		local root = P.frame(parent, {
			name = "Minimap",
			size = UDim2.new(0, width, 1, 0),
			pos = UDim2.new(1, -width, 0, 0),
			bg = theme.color.editor,
			clip = true,
			active = true,
			zIndex = 16,
		})
		local leftRule = P.frame(root, {
			size = UDim2.new(0, 1, 1, 0),
			bg = theme.color.border,
			transparency = 0.5,
			zIndex = 17,
		})

		local canvas = P.frame(root, {
			name = "MiniLines",
			size = UDim2.new(1, -8, 1, -8),
			pos = UDim2.fromOffset(5, 4),
			zIndex = 17,
		})

		local slider = P.frame(root, {
			name = "ViewportSlider",
			size = UDim2.new(1, 0, 0, 44),
			pos = UDim2.fromOffset(0, 0),
			bg = theme.color.selection,
			transparency = 0.65,
			zIndex = 18,
		})

		local bars = {}
		local MAX_BARS = 85

		local function ensureBar(i)
			if not bars[i] then
				bars[i] = P.frame(canvas, {
					size = UDim2.fromOffset(20, 2),
					pos = UDim2.fromOffset(0, (i - 1) * 3),
					bg = theme.color.muted,
					transparency = 0.35,
					zIndex = 17,
				})
			end
			return bars[i]
		end

		local function updateSource(lexScan)
			if not lexScan or not lexScan.lines then return end
			local total = #lexScan.lines
			local step = math.max(1, math.ceil(total / MAX_BARS))
			local idx = 0
			for lineNo = 1, total, step do
				idx = idx + 1
				if idx > MAX_BARS then break end
				local line = lexScan.lines[lineNo] or ""
				local bar = ensureBar(idx)
				local trimmed = util.trim(line)
				if trimmed == "" then
					bar.Visible = false
				else
					bar.Visible = true
					local indent = #(line:match("^(%s*)") or "")
					local w = util.clamp(math.floor(#trimmed * 0.75), 4, width - 14)
					bar.Position = UDim2.fromOffset(util.clamp(indent * 2, 0, 24), (idx - 1) * 3)
					bar.Size = UDim2.fromOffset(w, 2)
					local spans = lexScan.spans[lineNo]
					local firstKind = spans and spans[1] and spans[1].kind or "text"
					local colHex = theme.syntax[firstKind]
					bar.BackgroundColor3 = colHex and Color3.fromHex(colHex) or theme.color.muted
				end
			end
			for k = idx + 1, #bars do
				bars[k].Visible = false
			end
		end

		local function updateViewport(scrollY, viewHeight, contentHeight)
			local h = math.max(1, root.AbsoluteSize.Y)
			local totalH = math.max(contentHeight, viewHeight, 1)
			local fracH = util.clamp(viewHeight / totalH, 0.08, 1)
			local fracY = util.clamp(scrollY / math.max(1, totalH - viewHeight), 0, 1)
			local sliderH = math.floor(h * fracH)
			local sliderY = math.floor((h - sliderH) * fracY)
			slider.Size = UDim2.new(1, 0, 0, sliderH)
			slider.Position = UDim2.fromOffset(0, sliderY)
		end

		root.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				local relY = input.Position.Y - root.AbsolutePosition.Y
				local ratio = util.clamp(relY / math.max(1, root.AbsoluteSize.Y), 0, 1)
				if onJumpRatio then onJumpRatio(ratio) end
			end
		end)

		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.editor
			leftRule.BackgroundColor3 = theme.color.border
			slider.BackgroundColor3 = theme.color.selection
		end)

		return {
			root = root,
			width = width,
			updateSource = updateSource,
			updateViewport = updateViewport,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/preview_pane
-- ==========================================================================
__VSRBLX_MODULES["ui/code/preview_pane"] = (function()
-- VS Code Live Split Preview Pane (`src/ui/code/preview_pane.lua`):
-- Renders real-time visual previews for previewable languages ONLY:
--   • HTML (+ live workspace `style.css` cascade)
--   • CSS (palette swatches + live selector style cards)
--   • Markdown (GFM headings, RichText, syntax-colored code blocks, tables, tasks)
--   • JSON & YAML/TOML (interactive collapsible tree inspector)
--   • SQL (CREATE / INSERT / SELECT data table grid)
--   • Python / JavaScript / TypeScript (quick-eval output + variable state inspector)
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local languages = env.require("runtime/languages")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")
	local codeLexer = env.require("runtime/code_lexer")
	local previewEngine = env.require("runtime/preview_engine")

	local M = {}

	function M.new(parent, callbacks)
		callbacks = callbacks or {}
		local targetDoc = nil
		local collapsedNodes = {}

		local root = P.frame(parent, {
			name = "LivePreviewPane",
			size = UDim2.new(0.5, 0, 1, 0),
			pos = UDim2.new(0.5, 0, 0, 0),
			bg = theme.color.editor,
			visible = false,
			clip = true,
			zIndex = 14,
		})
		local leftBorder = P.frame(root, {
			size = UDim2.new(0, 1, 1, 0),
			bg = theme.color.border,
			zIndex = 30,
		})

		local header = P.frame(root, {
			name = "PreviewHeader",
			size = UDim2.new(1, 0, 0, theme.sizes.tabBar),
			bg = theme.color.tabBar,
			zIndex = 20,
		})
		local headerRule = P.frame(header, {
			size = UDim2.new(1, 0, 0, 1),
			pos = UDim2.new(0, 0, 1, -1),
			bg = theme.color.border,
			zIndex = 21,
		})

		local titleLbl = P.label(header, {
			name = "PreviewTitleLabel",
			size = UDim2.new(1, -146, 1, 0),
			pos = UDim2.fromOffset(12, 0),
			text = "◫ LIVE PREVIEW",
			bold = true,
			textSize = 11,
			color = theme.color.tabActiveText,
			truncate = true,
			zIndex = 22,
		})

		local btnRow = P.frame(header, {
			size = UDim2.fromOffset(136, theme.sizes.tabBar - 2),
			pos = UDim2.new(1, -140, 0, 1),
			zIndex = 22,
		})
		P.list(btnRow, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)

		local renderDoc

		P.button(btnRow, {
			name = "RefreshPreviewBtn",
			size = UDim2.fromOffset(62, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "↻ Sync",
			textSize = 11,
			radius = 4,
			order = 1,
			zIndex = 23,
			onClick = function()
				if targetDoc then renderDoc(targetDoc) end
			end,
		})

		P.button(btnRow, {
			name = "ClosePreviewBtn",
			size = UDim2.fromOffset(28, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.bad,
			text = "✕",
			textSize = 11,
			radius = 4,
			order = 2,
			zIndex = 23,
			onClick = function()
				if callbacks.onClose then callbacks.onClose() end
			end,
		})

		local scroll = P.scroll(root, {
			name = "PreviewScrollSurface",
			size = UDim2.new(1, -1, 1, -theme.sizes.tabBar),
			pos = UDim2.fromOffset(1, theme.sizes.tabBar),
			bg = theme.color.editor,
			zIndex = 16,
		})
		P.pad(scroll, 12, 14, 16, 14)
		P.list(scroll, Enum.FillDirection.Vertical, 8)

		local function resolveWorkspaceFile(relHref, baseDocPath)
			local cleanHref = util.normalisePath(tostring(relHref or ""):gsub("^%./", ""))
			local candidates = { cleanHref }
			if baseDocPath and baseDocPath ~= "" then
				local baseDir = util.dirname(baseDocPath)
				if baseDir ~= "" then
					table.insert(candidates, 1, util.joinPath(baseDir, cleanHref))
				end
			end
			-- Check open buffers first so unsaved live edits in `style.css` reflect immediately!
			for _, cand in ipairs(candidates) do
				local openTab = codeStore.findByPath(cand)
				if openTab then return openTab.content end
			end
			for _, tab in ipairs(codeStore.tabs) do
				if util.basename(tab.path) == util.basename(cleanHref) and tab.langId == "css" then
					return tab.content
				end
			end
			for _, cand in ipairs(candidates) do
				local diskBody = workspaceFs.readFile(cand)
				if type(diskBody) == "string" then return diskBody end
			end
			return nil
		end

		local function renderHtml(doc)
			local parsed = previewEngine.parseHtml(doc.content, function(href)
				return resolveWorkspaceFile(href, doc.path)
			end)
			local sheetInfo = #parsed.linkedSheets > 0 and (" + " .. table.concat(parsed.linkedSheets, ", ")) or ""
			titleLbl.Text = string.format("◫ PREVIEW: %s%s", doc.title, sheetInfo)

			local canvasBg = (parsed.bodyStyle and parsed.bodyStyle.bg) or Color3.fromRGB(248, 250, 252)
			local defaultTxtCol = (parsed.bodyStyle and parsed.bodyStyle.color) or Color3.fromRGB(24, 28, 36)

			local browserCard = P.frame(scroll, {
				name = "HtmlPreviewSurface",
				size = UDim2.new(1, 0, 0, 0),
				bg = canvasBg,
				radius = 6,
				border = theme.color.border,
				order = 1,
				zIndex = 17,
			})
			browserCard.AutomaticSize = Enum.AutomaticSize.Y
			P.pad(browserCard, 12, 14, 14, 14)
			P.list(browserCard, Enum.FillDirection.Vertical, 8)

			-- Simulated browser address bar
			local urlBar = P.frame(browserCard, {
				size = UDim2.new(1, 0, 0, 24),
				bg = Color3.fromRGB(30, 34, 42),
				radius = 4,
				order = 0,
				zIndex = 18,
			})
			P.label(urlBar, {
				size = UDim2.new(1, -16, 1, 0),
				pos = UDim2.fromOffset(8, 0),
				mono = true,
				textSize = 11,
				color = Color3.fromRGB(190, 205, 230),
				text = string.format("🌐 %s  —  local://%s%s", parsed.title, doc.path ~= "" and doc.path or doc.title, sheetInfo),
				truncate = true,
				zIndex = 19,
			})

			for idx, node in ipairs(parsed.nodes) do
				local st = node.style or {}
				local txtCol = st.color or defaultTxtCol
				local alignX = Enum.TextXAlignment.Left
				if st.align == "center" then alignX = Enum.TextXAlignment.Center
				elseif st.align == "right" then alignX = Enum.TextXAlignment.Right end

				if node.tag == "hr" then
					P.frame(browserCard, {
						size = UDim2.new(1, 0, 0, 1),
						bg = Color3.fromRGB(203, 213, 225),
						order = idx,
						zIndex = 18,
					})
				elseif node.tag == "h1" or node.tag == "h2" or node.tag == "h3" or node.tag == "h4" then
					local sizes = { h1 = 22, h2 = 18, h3 = 15, h4 = 13 }
					local lbl = P.label(browserCard, {
						name = "HtmlHeading_" .. tostring(idx),
						size = UDim2.new(1, 0, 0, (st.fontSize or sizes[node.tag]) + 8),
						text = node.text,
						bold = true,
						textSize = st.fontSize or sizes[node.tag],
						color = txtCol,
						alignX = alignX,
						wrap = true,
						order = idx,
						zIndex = 18,
					})
					if st.bg then
						lbl.BackgroundTransparency = 0
						lbl.BackgroundColor3 = st.bg
					end
				elseif node.tag == "button" then
					local btnBg = st.bg or Color3.fromRGB(37, 99, 235)
					local btnCol = st.color or Color3.fromRGB(255, 255, 255)
					local b = P.button(browserCard, {
						name = "HtmlButton_" .. tostring(idx),
						size = UDim2.fromOffset(math.max(96, #node.text * 8 + 28), 32),
						bg = btnBg,
						hoverBg = btnBg:Lerp(Color3.fromRGB(255, 255, 255), 0.14),
						color = btnCol,
						bold = true,
						text = node.text ~= "" and node.text or "Button",
						textSize = st.fontSize or 13,
						radius = st.radius or 6,
						order = idx,
						zIndex = 18,
						onClick = function()
							overlay.toast("HTML <button> clicked: " .. tostring(node.text), "info", 1.8)
						end,
					})
					b.BackgroundTransparency = 0
				elseif node.tag == "input" then
					P.input(browserCard, {
						name = "HtmlInput_" .. tostring(idx),
						size = UDim2.new(0.75, 0, 0, 30),
						bg = st.bg or Color3.fromRGB(255, 255, 255),
						color = st.color or Color3.fromRGB(20, 24, 32),
						placeholder = node.text,
						order = idx,
						zIndex = 18,
					})
				elseif node.tag == "card" or node.tag == "banner" then
					local card = P.frame(browserCard, {
						name = "HtmlCard_" .. tostring(idx),
						size = UDim2.new(1, 0, 0, 0),
						bg = st.bg or canvasBg:Lerp(Color3.fromRGB(128, 128, 128), 0.12),
						radius = st.radius or 6,
						border = st.borderColor,
						order = idx,
						zIndex = 18,
					})
					card.AutomaticSize = Enum.AutomaticSize.Y
					local padPx = util.clamp(st.padding or 10, 4, 28)
					P.pad(card, padPx, padPx, padPx, padPx)
					P.label(card, {
						size = UDim2.new(1, 0, 0, 0),
						text = node.text ~= "" and node.text or ("<" .. tostring(node.label) .. ">"),
						bold = st.bold,
						textSize = st.fontSize or 13,
						color = txtCol,
						alignX = alignX,
						wrap = true,
						zIndex = 19,
					}).AutomaticSize = Enum.AutomaticSize.Y
				else
					local prefix = node.tag == "li" and "• " or ""
					local lbl = P.label(browserCard, {
						size = UDim2.new(1, 0, 0, 0),
						text = prefix .. tostring(node.text or ""),
						mono = (node.tag == "code" or node.tag == "pre"),
						bold = st.bold,
						textSize = st.fontSize or 13,
						color = node.tag == "a" and Color3.fromRGB(37, 99, 235) or txtCol,
						alignX = alignX,
						wrap = true,
						order = idx,
						zIndex = 18,
					})
					lbl.AutomaticSize = Enum.AutomaticSize.Y
				end
			end
		end

		local function renderCss(doc)
			local parsed = previewEngine.parseCss(doc.content)
			titleLbl.Text = string.format("◫ CSS DESIGN PREVIEW: %s (%d rules)", doc.title, #parsed.rules)

			-- If workspace has an HTML file, offer 1-click jump to preview HTML+CSS together!
			for _, fPath in ipairs(workspaceFs.allFiles()) do
				if util.endsWith(fPath:lower(), ".html") then
					local jumpHtmlBtn = P.button(scroll, {
						name = "PreviewLinkedHtmlBtn",
						size = UDim2.new(1, 0, 0, 28),
						bg = theme.color.accent,
						hoverBg = theme.color.accentHover,
						color = Color3.fromRGB(255, 255, 255),
						bold = true,
						text = "🌐 Preview Applied to " .. fPath,
						textSize = 11,
						radius = 4,
						order = 0,
						zIndex = 18,
						onClick = function()
							local hDoc = codeStore.openFile(fPath)
							if hDoc then renderDoc(hDoc) end
						end,
					})
					jumpHtmlBtn.BackgroundTransparency = 0
					break
				end
			end

			if #parsed.swatches > 0 then
				local palCard = P.frame(scroll, {
					name = "CssSwatchGrid",
					size = UDim2.new(1, 0, 0, 56),
					bg = theme.color.sideBar,
					radius = 5,
					border = theme.color.border,
					order = 1,
					zIndex = 17,
				})
				P.pad(palCard, 6, 8, 6, 8)
				P.label(palCard, {
					size = UDim2.new(1, 0, 0, 14),
					text = "COLOR PALETTE (" .. tostring(#parsed.swatches) .. ")",
					bold = true,
					textSize = 10,
					color = theme.color.muted,
					zIndex = 18,
				})
				local swRow = P.frame(palCard, {
					size = UDim2.new(1, 0, 0, 26),
					pos = UDim2.fromOffset(0, 18),
					zIndex = 18,
				})
				P.list(swRow, Enum.FillDirection.Horizontal, 6, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
				for idx, sw in ipairs(parsed.swatches) do
					if idx <= 8 then
						local chip = P.frame(swRow, {
							size = UDim2.fromOffset(74, 22),
							bg = sw.color3,
							radius = 4,
							border = theme.color.border,
							order = idx,
							zIndex = 19,
						})
						P.label(chip, {
							size = UDim2.fromScale(1, 1),
							text = sw.hex,
							mono = true,
							bold = true,
							textSize = 10,
							color = Color3.fromRGB(255, 255, 255),
							alignX = Enum.TextXAlignment.Center,
							zIndex = 20,
						})
					end
				end
			end

			for idx, rule in ipairs(parsed.rules) do
				local bgCol = previewEngine.parseCssColor(rule.props["background-color"] or rule.props["background"]) or theme.color.inputBg
				local fgCol = previewEngine.parseCssColor(rule.props["color"]) or theme.color.editorText
				local card = P.frame(scroll, {
					name = "CssRuleCard_" .. tostring(idx),
					size = UDim2.new(1, 0, 0, 54),
					bg = bgCol,
					radius = 6,
					border = theme.color.border,
					order = idx + 2,
					zIndex = 17,
				})
				P.pad(card, 6, 10, 6, 10)
				P.label(card, {
					size = UDim2.new(1, 0, 0, 18),
					mono = true,
					bold = true,
					textSize = 12,
					color = fgCol,
					text = rule.selector,
					zIndex = 18,
				})
				local summary = {}
				for k, v in pairs(rule.props) do
					summary[#summary + 1] = k .. ": " .. v
				end
				table.sort(summary)
				P.label(card, {
					size = UDim2.new(1, 0, 0, 20),
					pos = UDim2.fromOffset(0, 20),
					mono = true,
					textSize = 10,
					color = fgCol,
					text = table.concat(summary, "; "),
					truncate = true,
					zIndex = 18,
				})
			end
		end

		local function renderMarkdown(doc)
			titleLbl.Text = "◫ MARKDOWN PREVIEW: " .. doc.title
			local blocks = previewEngine.parseMarkdown(doc.content)
			for idx, b in ipairs(blocks) do
				if b.kind == "heading" then
					local sizes = { 22, 18, 15, 13 }
					local wrap = P.frame(scroll, {
						name = "MdHeading_" .. tostring(idx),
						size = UDim2.new(1, 0, 0, sizes[b.level] + 12),
						order = idx,
						zIndex = 17,
					})
					P.label(wrap, {
						size = UDim2.new(1, 0, 1, -4),
						rich = true,
						bold = true,
						textSize = sizes[b.level],
						color = theme.color.tabActiveText,
						text = previewEngine.inlineMarkdownRich(b.text),
						truncate = true,
						zIndex = 18,
					})
					if b.level <= 2 then
						P.frame(wrap, {
							size = UDim2.new(1, 0, 0, 1),
							pos = UDim2.new(0, 0, 1, -1),
							bg = theme.color.border,
							zIndex = 18,
						})
					end
				elseif b.kind == "hr" then
					P.frame(scroll, {
						size = UDim2.new(1, 0, 0, 1),
						bg = theme.color.border,
						order = idx,
						zIndex = 17,
					})
				elseif b.kind == "code" then
					local scan = codeLexer.scan(b.text, b.lang)
					local richLines = {}
					for li = 1, #scan.lines do
						richLines[li] = codeLexer.rich(scan.lines[li], scan.spans[li], theme.syntax)
					end
					local codeBox = P.frame(scroll, {
						name = "MdCodeFence_" .. tostring(idx),
						size = UDim2.new(1, 0, 0, math.max(32, #scan.lines * 17 + 16)),
						bg = theme.color.sideBar,
						radius = 5,
						border = theme.color.border,
						order = idx,
						zIndex = 17,
					})
					P.pad(codeBox, 8, 10, 8, 10)
					P.label(codeBox, {
						size = UDim2.fromScale(1, 1),
						mono = true,
						rich = true,
						textSize = 12,
						color = theme.color.editorText,
						alignY = Enum.TextYAlignment.Top,
						wrap = true,
						text = table.concat(richLines, "\n"),
						zIndex = 18,
					})
				elseif b.kind == "quote" then
					local qFrame = P.frame(scroll, {
						size = UDim2.new(1, 0, 0, 26),
						bg = theme.color.inputBg,
						radius = 3,
						order = idx,
						zIndex = 17,
					})
					P.frame(qFrame, {
						size = UDim2.new(0, 3, 1, 0),
						bg = theme.color.accent,
						zIndex = 18,
					})
					P.label(qFrame, {
						size = UDim2.new(1, -16, 1, 0),
						pos = UDim2.fromOffset(12, 0),
						rich = true,
						textSize = 12,
						color = theme.color.muted,
						text = previewEngine.inlineMarkdownRich(b.text),
						wrap = true,
						zIndex = 18,
					})
				elseif b.kind == "task" or b.kind == "bullet" or b.kind == "numbered" then
					local prefix = "•  "
					if b.kind == "task" then
						prefix = b.checked and "☑  " or "☐  "
					elseif b.kind == "numbered" then
						prefix = tostring(b.num) .. ".  "
					end
					local lbl = P.label(scroll, {
						size = UDim2.new(1, 0, 0, 20),
						rich = true,
						textSize = 13,
						color = (b.kind == "task" and b.checked) and theme.color.good or theme.color.editorText,
						text = prefix .. previewEngine.inlineMarkdownRich(b.text),
						wrap = true,
						order = idx,
						zIndex = 17,
					})
					lbl.AutomaticSize = Enum.AutomaticSize.Y
				elseif b.kind == "table" then
					local tblCard = P.frame(scroll, {
						name = "MdTable_" .. tostring(idx),
						size = UDim2.new(1, 0, 0, #b.rows * 24 + 4),
						bg = theme.color.sideBar,
						radius = 4,
						border = theme.color.border,
						order = idx,
						zIndex = 17,
					})
					P.list(tblCard, Enum.FillDirection.Vertical, 0)
					for ri, cells in ipairs(b.rows) do
						local rFrame = P.frame(tblCard, {
							size = UDim2.new(1, 0, 0, 24),
							bg = ri == 1 and theme.color.sideBarHeader or (ri % 2 == 0 and theme.color.editor or theme.color.sideBar),
							order = ri,
							zIndex = 18,
						})
						local colW = 1 / math.max(1, #cells)
						for ci, cellTxt in ipairs(cells) do
							P.label(rFrame, {
								size = UDim2.new(colW, -8, 1, 0),
								pos = UDim2.new(colW * (ci - 1), 6, 0, 0),
								bold = (ri == 1),
								textSize = 11,
								color = ri == 1 and theme.color.tabActiveText or theme.color.editorText,
								text = cellTxt,
								truncate = true,
								zIndex = 19,
							})
						end
					end
				else
					local pLbl = P.label(scroll, {
						size = UDim2.new(1, 0, 0, 0),
						rich = true,
						textSize = 13,
						color = theme.color.editorText,
						text = previewEngine.inlineMarkdownRich(b.text),
						wrap = true,
						order = idx,
						zIndex = 17,
					})
					pLbl.AutomaticSize = Enum.AutomaticSize.Y
				end
			end
		end

		local function renderStructuredTree(doc)
			local parsed = previewEngine.parseStructuredData(doc.content, doc.langId)
			titleLbl.Text = string.format("◫ %s TREE INSPECTOR: %s", (parsed.format or doc.langId):upper(), doc.title)
			if not parsed.ok then
				local errCard = P.frame(scroll, {
					name = "PreviewSyntaxErrorCard",
					size = UDim2.new(1, 0, 0, 52),
					bg = theme.color.diffRemoveBg,
					radius = 5,
					border = theme.color.bad,
					order = 1,
					zIndex = 17,
				})
				P.pad(errCard, 8, 10, 8, 10)
				P.label(errCard, {
					size = UDim2.fromScale(1, 1),
					mono = true,
					textSize = 12,
					color = theme.color.bad,
					wrap = true,
					text = "⊗ Parse Error: " .. tostring(parsed.error),
					zIndex = 18,
				})
				return
			end

			local ord = 0
			local function walkValue(keyLabel, val, pathKey, depth)
				if ord > 180 or depth > 8 then return end
				ord = ord + 1
				if type(val) == "table" then
					local keys = util.keys(val)
					local isCollapsed = collapsedNodes[pathKey] == true
					local row = P.button(scroll, {
						name = "TreeNode_" .. pathKey,
						size = UDim2.new(1, 0, 0, 21),
						hoverBg = theme.color.hover,
						alignX = Enum.TextXAlignment.Left,
						mono = true,
						bold = true,
						textSize = 12,
						color = theme.color.accent,
						text = string.format(
							"%s%s %s  (%d items)",
							string.rep("   ", depth),
							isCollapsed and "▸" or "▾",
							keyLabel,
							#keys
						),
						order = ord,
						zIndex = 18,
						onClick = function()
							collapsedNodes[pathKey] = not collapsedNodes[pathKey]
							renderDoc(doc)
						end,
					})
					row.TextTruncate = Enum.TextTruncate.AtEnd
					if not isCollapsed then
						for _, k in ipairs(keys) do
							walkValue(tostring(k), val[k], pathKey .. "." .. tostring(k), depth + 1)
						end
					end
				else
					local valStr = type(val) == "string" and string.format("%q", val) or tostring(val)
					local vHex = "#ce9178"
					if type(val) == "number" then vHex = "#b5cea8"
					elseif type(val) == "boolean" then vHex = "#569cd6" end
					P.label(scroll, {
						size = UDim2.new(1, 0, 0, 19),
						mono = true,
						rich = true,
						textSize = 12,
						color = theme.color.editorText,
						text = string.format(
							'%s<font color="#9cdcfe">%s</font>: <font color="%s">%s</font>',
							string.rep("   ", depth + 1),
							util.escapeRichText(keyLabel),
							vHex,
							util.escapeRichText(valStr)
						),
						truncate = true,
						order = ord,
						zIndex = 18,
					})
				end
			end

			walkValue("root", parsed.data, "root", 0)
		end

		local function renderSql(doc)
			local res = previewEngine.runSqlPreview(doc.content)
			titleLbl.Text = string.format("◫ SQL TABLE PREVIEW: %s (%d result set(s))", doc.title, #res.results)

			if #res.results == 0 then
				P.label(scroll, {
					size = UDim2.new(1, 0, 0, 26),
					text = "Write CREATE TABLE, INSERT INTO, or SELECT statements to preview tabular results live.",
					color = theme.color.muted,
					textSize = 12,
					wrap = true,
					order = 1,
					zIndex = 17,
				})
				return
			end

			for idx, set in ipairs(res.results) do
				local cardH = 30 + (1 + math.max(1, #set.rows)) * 22
				local card = P.frame(scroll, {
					name = "SqlResultGrid_" .. tostring(idx),
					size = UDim2.new(1, 0, 0, cardH),
					bg = theme.color.sideBar,
					radius = 5,
					border = theme.color.border,
					order = idx,
					zIndex = 17,
				})
				P.label(card, {
					size = UDim2.new(1, -16, 0, 24),
					pos = UDim2.fromOffset(8, 2),
					bold = true,
					textSize = 11,
					color = theme.color.accent,
					text = string.format("%s  (%d rows)", set.title, #set.rows),
					truncate = true,
					zIndex = 18,
				})

				local grid = P.frame(card, {
					size = UDim2.new(1, -8, 1, -28),
					pos = UDim2.fromOffset(4, 26),
					zIndex = 18,
				})
				P.list(grid, Enum.FillDirection.Vertical, 0)

				local cols = #set.columns > 0 and set.columns or { "(empty)" }
				local colW = 1 / #cols

				local hdrRow = P.frame(grid, {
					size = UDim2.new(1, 0, 0, 22),
					bg = theme.color.sideBarHeader,
					order = 1,
					zIndex = 19,
				})
				for ci, cName in ipairs(cols) do
					P.label(hdrRow, {
						size = UDim2.new(colW, -6, 1, 0),
						pos = UDim2.new(colW * (ci - 1), 6, 0, 0),
						mono = true,
						bold = true,
						textSize = 11,
						color = theme.color.tabActiveText,
						text = tostring(cName),
						truncate = true,
						zIndex = 20,
					})
				end

				for ri, rData in ipairs(set.rows) do
					local rFrame = P.frame(grid, {
						size = UDim2.new(1, 0, 0, 22),
						bg = ri % 2 == 0 and theme.color.editor or theme.color.sideBar,
						order = ri + 1,
						zIndex = 19,
					})
					for ci, cName in ipairs(cols) do
						P.label(rFrame, {
							size = UDim2.new(colW, -6, 1, 0),
							pos = UDim2.new(colW * (ci - 1), 6, 0, 0),
							mono = true,
							textSize = 11,
							color = theme.color.editorText,
							text = tostring(rData[cName] ~= nil and rData[cName] or "NULL"),
							truncate = true,
							zIndex = 20,
						})
					end
				end
			end
		end

		local function renderScriptQuickEval(doc)
			local res = previewEngine.runScriptPreview(doc.content, doc.langId)
			titleLbl.Text = string.format("◫ %s QUICK-EVAL PREVIEW: %s", res.lang:upper(), doc.title)

			local outCard = P.frame(scroll, {
				name = "ScriptEvalOutputCard",
				size = UDim2.new(1, 0, 0, math.max(54, #res.output * 19 + 34)),
				bg = theme.color.sideBar,
				radius = 5,
				border = theme.color.border,
				order = 1,
				zIndex = 17,
			})
			P.pad(outCard, 6, 10, 8, 10)
			P.label(outCard, {
				size = UDim2.new(1, 0, 0, 18),
				bold = true,
				textSize = 10,
				color = theme.color.good,
				text = "▶ STDOUT PREVIEW (" .. tostring(#res.output) .. " line(s))",
				zIndex = 18,
			})
			local outText = #res.output > 0
				and table.concat(res.output, "\n")
				or "(Add print(...) or console.log(...) calls to preview live output)"
			P.label(outCard, {
				size = UDim2.new(1, 0, 1, -20),
				pos = UDim2.fromOffset(0, 20),
				mono = true,
				textSize = 12,
				color = #res.output > 0 and theme.color.editorText or theme.color.muted,
				alignY = Enum.TextYAlignment.Top,
				wrap = true,
				text = outText,
				zIndex = 18,
			})

			if #res.variables > 0 then
				local varCard = P.frame(scroll, {
					name = "ScriptEvalVarsCard",
					size = UDim2.new(1, 0, 0, #res.variables * 20 + 30),
					bg = theme.color.sideBar,
					radius = 5,
					border = theme.color.border,
					order = 2,
					zIndex = 17,
				})
				P.pad(varCard, 6, 10, 6, 10)
				P.label(varCard, {
					size = UDim2.new(1, 0, 0, 18),
					bold = true,
					textSize = 10,
					color = theme.color.accent,
					text = "EVALUATED VARIABLES",
					zIndex = 18,
				})
				for vi, kv in ipairs(res.variables) do
					P.label(varCard, {
						size = UDim2.new(1, 0, 0, 19),
						pos = UDim2.fromOffset(0, 18 + (vi - 1) * 19),
						mono = true,
						textSize = 12,
						color = theme.color.editorText,
						text = string.format("%s = %s", kv.name, kv.value),
						truncate = true,
						zIndex = 18,
					})
				end
			end
		end

		renderDoc = function(doc)
			if not doc or not languages.isPreviewable(doc) then
				return false
			end
			targetDoc = doc
			scroll:ClearAllChildren()
			P.pad(scroll, 12, 14, 16, 14)
			P.list(scroll, Enum.FillDirection.Vertical, 8)

			local lid = doc.langId
			if lid == "html" then
				renderHtml(doc)
			elseif lid == "css" then
				renderCss(doc)
			elseif lid == "markdown" then
				renderMarkdown(doc)
			elseif lid == "json" or lid == "yaml" then
				renderStructuredTree(doc)
			elseif lid == "sql" then
				renderSql(doc)
			elseif lid == "python" or lid == "javascript" or lid == "typescript" then
				renderScriptQuickEval(doc)
			end
			return true
		end

		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.editor
			leftBorder.BackgroundColor3 = theme.color.border
			header.BackgroundColor3 = theme.color.tabBar
			headerRule.BackgroundColor3 = theme.color.border
			scroll.BackgroundColor3 = theme.color.editor
			if root.Visible and targetDoc then
				renderDoc(targetDoc)
			end
		end)

		return {
			root = root,
			render = renderDoc,
			currentDoc = function() return targetDoc end,
			setTransparency = function(bgTrans)
				root.BackgroundTransparency = bgTrans
				header.BackgroundTransparency = bgTrans
				scroll.BackgroundTransparency = bgTrans
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/splitter
-- ==========================================================================
__VSRBLX_MODULES["ui/code/splitter"] = (function()
-- Interactive draggable vertical/horizontal splitters between VS Code Sidebar,
-- Editor Groups, and the Bottom Terminal Panel.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local dispose = env.require("runtime/dispose")

	local M = {}

	function M.vertical(parent, zIndex, onDelta)
		local sash = P.frame(parent, {
			name = "VerticalSash",
			size = UDim2.new(0, 4, 1, 0),
			bg = theme.color.accent,
			transparency = 1,
			active = true,
			zIndex = zIndex or 35,
		})
		local dragging = false
		local startX = 0

		sash.MouseEnter:Connect(function() sash.BackgroundTransparency = 0.25 end)
		sash.MouseLeave:Connect(function() if not dragging then sash.BackgroundTransparency = 1 end end)

		sash.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				startX = input.Position.X
				sash.BackgroundTransparency = 0
			end
		end)

		if env.uis then
			dispose.connection(env.uis.InputChanged:Connect(function(input)
				if not dragging then return end
				if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
					local dx = input.Position.X - startX
					startX = input.Position.X
					if onDelta then onDelta(dx) end
				end
			end))
			dispose.connection(env.uis.InputEnded:Connect(function(input)
				if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
					dragging = false
					sash.BackgroundTransparency = 1
				end
			end))
		end

		return sash
	end

	function M.horizontal(parent, zIndex, onDelta)
		local sash = P.frame(parent, {
			name = "HorizontalSash",
			size = UDim2.new(1, 0, 0, 4),
			bg = theme.color.accent,
			transparency = 1,
			active = true,
			zIndex = zIndex or 35,
		})
		local dragging = false
		local startY = 0

		sash.MouseEnter:Connect(function() sash.BackgroundTransparency = 0.25 end)
		sash.MouseLeave:Connect(function() if not dragging then sash.BackgroundTransparency = 1 end end)

		sash.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				startY = input.Position.Y
				sash.BackgroundTransparency = 0
			end
		end)

		if env.uis then
			dispose.connection(env.uis.InputChanged:Connect(function(input)
				if not dragging then return end
				if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
					local dy = input.Position.Y - startY
					startY = input.Position.Y
					if onDelta then onDelta(dy) end
				end
			end))
			dispose.connection(env.uis.InputEnded:Connect(function(input)
				if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
					dragging = false
					sash.BackgroundTransparency = 1
				end
			end))
		end

		return sash
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/tabs
-- ==========================================================================
__VSRBLX_MODULES["ui/code/tabs"] = (function()
-- VS Code Multi-Tab Editor Bar (`src/ui/code/tabs.lua`):
-- Seti file badges, dirty dots (`●`) with hover `✕`, pin state, unsaved close prompt,
-- Language-Gated `◫ Preview` (`Open Preview to the Side` — shown ONLY on previewable
-- languages, omitted on non-preview languages), Run (`▶`), Save, Split, and `40px` Touch Mode.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local languages = env.require("runtime/languages")
	local codeStore = env.require("runtime/code_store")
	local commands = env.require("runtime/command_catalog")
	local clipboard = env.require("runtime/clipboard")

	local M = {}

	function M.new(parent, paneName)
		local pane = paneName or "primary"
		local h = theme.sizes.tabBar
		local mobileMode = false

		local root = P.frame(parent, {
			name = "TabBar_" .. pane,
			size = UDim2.new(1, 0, 0, h),
			bg = theme.color.tabBar,
			zIndex = 20,
		})
		local bottomBorder = P.frame(root, {
			size = UDim2.new(1, 0, 0, 1),
			pos = UDim2.new(0, 0, 1, -1),
			bg = theme.color.border,
			zIndex = 21,
		})

		local tabsScroll = P.scroll(root, {
			name = "TabsScroll",
			size = UDim2.new(1, -244, 1, -1),
			direction = Enum.ScrollingDirection.X,
			autoCanvas = Enum.AutomaticSize.X,
			barThickness = 3,
			zIndex = 21,
		})
		P.list(tabsScroll, Enum.FillDirection.Horizontal, 1)

		local actionsBar = P.frame(root, {
			name = "EditorActions",
			size = UDim2.fromOffset(240, h - 1),
			pos = UDim2.new(1, -242, 0, 0),
			zIndex = 22,
		})
		P.list(actionsBar, Enum.FillDirection.Horizontal, 2, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)

		-- Multi-Tab Overflow Controls (`‹`, `›`, `+`, and `▾ N` Open Tabs Switcher!)
		local scrollLeftBtn = P.button(actionsBar, {
			name = "ScrollTabsLeftBtn",
			size = UDim2.fromOffset(20, 24),
			text = "‹",
			bold = true,
			textSize = 14,
			color = theme.color.muted,
			radius = 4,
			order = -4,
			zIndex = 23,
			onClick = function()
				local cx = tabsScroll.CanvasPosition.X
				tabsScroll.CanvasPosition = Vector2.new(math.max(0, cx - 150), 0)
			end,
		})

		local scrollRightBtn = P.button(actionsBar, {
			name = "ScrollTabsRightBtn",
			size = UDim2.fromOffset(20, 24),
			text = "›",
			bold = true,
			textSize = 14,
			color = theme.color.muted,
			radius = 4,
			order = -3,
			zIndex = 23,
			onClick = function()
				local cx = tabsScroll.CanvasPosition.X
				tabsScroll.CanvasPosition = Vector2.new(cx + 150, 0)
			end,
		})

		local newTabBtn = P.button(actionsBar, {
			name = "NewTabBtn",
			size = UDim2.fromOffset(22, 24),
			text = "+",
			bold = true,
			textSize = 13,
			color = theme.color.tabActiveText,
			radius = 4,
			order = -2,
			zIndex = 23,
			onClick = function()
				commands.run("file.newUntitled")
			end,
		})

		local allTabsBtn = P.button(actionsBar, {
			name = "AllOpenTabsBtn",
			size = UDim2.fromOffset(36, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "▾ 1",
			mono = true,
			bold = true,
			textSize = 10,
			color = theme.color.tabActiveText,
			radius = 4,
			order = -1,
			zIndex = 23,
			onClick = function()
				local items = {
					{ label = "＋ New Untitled Tab", shortcut = "Ctrl+N", onClick = function() commands.run("file.newUntitled") end },
					{ separator = true },
				}
				local curActive = codeStore.active(pane)
				local curId = curActive and curActive.id or nil
				for idx, d in ipairs(codeStore.tabs) do
					local prefix = (d.id == curId) and "● " or "   "
					local dirtySuffix = d.dirty and " *" or ""
					items[#items + 1] = {
						label = string.format("%s%d. %s%s", prefix, idx, d.title, dirtySuffix),
						shortcut = d.langId or "",
						onClick = function()
							codeStore.activate(d.id, pane)
						end,
					}
				end
				items[#items + 1] = { separator = true }
				items[#items + 1] = { label = "Close Saved Tabs", onClick = function() codeStore.closeSaved() end }
				items[#items + 1] = { label = "Close All Clean Tabs", onClick = function() codeStore.closeAll() end }
				local p = actionsBar.AbsolutePosition
				overlay.dropdown(p.X, p.Y + h, items, 240)
			end,
		})
		allTabsBtn.BackgroundTransparency = 0.25

		-- Language-gated Live Split Preview button (strictly hidden on non-previewable languages!)
		local previewBtn = P.button(actionsBar, {
			name = "OpenPreviewBtn_" .. pane,
			size = UDim2.fromOffset(66, 26),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = "◫ Preview",
			textSize = 11,
			radius = 4,
			visible = false,
			order = 1,
			zIndex = 23,
			onClick = function()
				commands.run("preview.openToSide")
			end,
		})
		previewBtn.BackgroundTransparency = 0

		local runBtn = P.button(actionsBar, {
			name = "RunTabBtn",
			size = UDim2.fromOffset(28, 26),
			text = "▶",
			bold = true,
			color = theme.color.good,
			radius = 4,
			order = 2,
			zIndex = 23,
			onClick = function() commands.run("run.active") end,
		})

		local saveBtn = P.button(actionsBar, {
			name = "SaveTabBtn",
			size = UDim2.fromOffset(34, 26),
			text = "Save",
			textSize = 11,
			color = theme.color.sideBarText,
			radius = 4,
			order = 3,
			zIndex = 23,
			onClick = function() commands.run("file.save") end,
		})

		local splitBtn = P.button(actionsBar, {
			name = "SplitPaneBtn",
			size = UDim2.fromOffset(26, 26),
			text = "⫿",
			textSize = 14,
			color = theme.color.sideBarText,
			radius = 4,
			order = 4,
			zIndex = 23,
			onClick = function() codeStore.toggleSplit() end,
		})

		local currentBarW = 800

		local function rebuild()
			root.Size = UDim2.new(1, 0, 0, h)
			local compact = currentBarW < 520
			local totalTabs = #codeStore.tabs
			allTabsBtn.Text = "▾ " .. tostring(totalTabs)

			-- Show `‹ ›` scroll arrows when 3+ tabs are open and width allows
			local showArrows = (totalTabs >= 3) and (not compact)
			scrollLeftBtn.Visible = showArrows
			scrollRightBtn.Visible = showArrows
			saveBtn.Visible = not compact
			splitBtn.Visible = not compact
			previewBtn.Size = UDim2.fromOffset(compact and 30 or 64, 26)
			previewBtn.Text = compact and "◫" or "◫ Preview"

			local actW = compact and 136 or (showArrows and 254 or 210)
			actionsBar.Size = UDim2.fromOffset(actW, h - 1)
			actionsBar.Position = UDim2.new(1, -(actW + 2), 0, 0)
			tabsScroll.Size = UDim2.new(1, -(actW + 6), 1, -1)

			local activeDoc = codeStore.active(pane)
			local activeId = activeDoc and activeDoc.id or nil
			local canPrev = (pane == "primary") and (activeDoc ~= nil) and languages.isPreviewable(activeDoc)
			previewBtn.Visible = canPrev
			local actionW = canPrev and 180 or 108
			tabsScroll.Size = UDim2.new(1, -actionW, 1, -1)

			local btnH = mobileMode and 32 or 26
			previewBtn.Size = UDim2.fromOffset(68, btnH)
			runBtn.Size = UDim2.fromOffset(mobileMode and 34 or 30, btnH)
			saveBtn.Size = UDim2.fromOffset(mobileMode and 40 or 36, btnH)
			splitBtn.Size = UDim2.fromOffset(mobileMode and 32 or 28, btnH)

			tabsScroll:ClearAllChildren()
			P.list(tabsScroll, Enum.FillDirection.Horizontal, 1)

			for idx, doc in ipairs(codeStore.tabs) do
				local isCurrent = (doc.id == activeId)
				local minTabW = mobileMode and 132 or 116
				local tabW = math.max(minTabW, math.min(216, #doc.title * 7 + (doc.pinned and 72 or 62)))
				local tabBtn = P.button(tabsScroll, {
					name = "Tab_" .. doc.title,
					size = UDim2.fromOffset(tabW, h - 1),
					bg = isCurrent and theme.color.tabActive or theme.color.tabInactive,
					hoverBg = isCurrent and theme.color.tabActive or theme.color.hover,
					text = "",
					order = idx,
					zIndex = 22,
					activeState = function() return isCurrent end,
					onClick = function()
						codeStore.activate(doc.id, pane)
					end,
				})
				tabBtn.BackgroundTransparency = root.BackgroundTransparency

				if isCurrent then
					P.frame(tabBtn, {
						name = "ActiveTopAccent",
						size = UDim2.new(1, 0, 0, mobileMode and 3 or 2),
						bg = theme.color.tabActiveTop,
						zIndex = 24,
					})
				end

				P.frame(tabBtn, {
					size = UDim2.new(0, 1, 1, 0),
					pos = UDim2.new(1, -1, 0, 0),
					bg = theme.color.border,
					zIndex = 23,
				})

				local badge = icons.fileBadge(tabBtn, doc.path ~= "" and doc.path or doc.langId, false, 23)
				badge.Position = UDim2.fromOffset(8, math.floor((h - 14) / 2))

				local titleX = 31
				if doc.pinned then
					local pinIc = icons.codicon(tabBtn, "pin", 13, theme.color.accent, 23)
					pinIc.Position = UDim2.fromOffset(29, math.floor((h - 13) / 2))
					titleX = 44
				end

				local closeSize = mobileMode and 26 or 20
				P.label(tabBtn, {
					size = UDim2.new(1, -(titleX + closeSize + 8), 1, 0),
					pos = UDim2.fromOffset(titleX, 0),
					text = doc.title,
					textSize = mobileMode and 13 or 12,
					color = isCurrent and theme.color.tabActiveText or theme.color.tabInactiveText,
					truncate = true,
					zIndex = 23,
				})

				local restingGlyph = doc.dirty and "●" or (doc.pinned and "•" or "✕")
				local closeOrDot = P.button(tabBtn, {
					name = "CloseTabBtn",
					size = UDim2.fromOffset(closeSize, closeSize),
					pos = UDim2.new(1, -(closeSize + 4), 0.5, -math.floor(closeSize * 0.5)),
					text = restingGlyph,
					textSize = doc.dirty and 12 or 11,
					color = doc.dirty and theme.color.tabActiveText or theme.color.muted,
					radius = 4,
					zIndex = 24,
					onClick = function()
						if doc.pinned then
							codeStore.togglePin(doc.id)
						else
							codeStore.requestClose(doc.id)
						end
					end,
				})
				closeOrDot.Active = true
				if doc.dirty and not doc.pinned then
					closeOrDot.MouseEnter:Connect(function()
						closeOrDot.Text = "✕"
						closeOrDot.TextSize = 11
					end)
					closeOrDot.MouseLeave:Connect(function()
						closeOrDot.Text = "●"
						closeOrDot.TextSize = 12
					end)
				end

				tabBtn.MouseButton2Click:Connect(function()
					local p = tabBtn.AbsolutePosition
					local menu = {
						{ label = doc.pinned and "Unpin Tab" or "Pin Tab", onClick = function() codeStore.togglePin(doc.id) end },
						{ label = "Save to Local Disk", shortcut = "Ctrl+S", onClick = function() codeStore.save(doc.id) end },
					}
					if languages.isPreviewable(doc) then
						menu[#menu + 1] = {
							label = "◫ Open Preview to the Side",
							onClick = function()
								codeStore.activate(doc.id, "primary")
								commands.run("preview.openToSide")
							end,
						}
					end
					if doc.path and doc.path ~= "" then
						menu[#menu + 1] = {
							label = "Copy Relative Path",
							onClick = function()
								clipboard.copy(doc.path)
								overlay.toast("Copied: " .. doc.path, "info", 1.8)
							end,
						}
						if not doc.untitled then
							menu[#menu + 1] = {
								label = "Split Editor Right",
								onClick = function() codeStore.openFile(doc.path, { pane = "secondary" }) end,
							}
						end
					end
					menu[#menu + 1] = { separator = true }
					menu[#menu + 1] = { label = "Close", shortcut = "Ctrl+W", onClick = function() codeStore.requestClose(doc.id) end }
					menu[#menu + 1] = { label = "Close Others", onClick = function() codeStore.closeOthers(doc.id) end }
					menu[#menu + 1] = { label = "Close to the Right", onClick = function() codeStore.closeToRight(doc.id) end }
					menu[#menu + 1] = { label = "Close Saved", onClick = function() codeStore.closeSaved() end }
					menu[#menu + 1] = { label = "Close All Clean Tabs", onClick = function() codeStore.closeAll() end }
					overlay.dropdown(p.X, p.Y + h, menu, 210)
				end)
			end
		end

		codeStore.changed:connect(rebuild)
		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.tabBar
			bottomBorder.BackgroundColor3 = theme.color.border
			previewBtn.BackgroundColor3 = theme.color.accent
			splitBtn.TextColor3 = theme.color.sideBarText
			rebuild()
		end)

		rebuild()
		return {
			root = root,
			previewButton = previewBtn,
			allTabsButton = allTabsBtn,
			refresh = rebuild,
			reflow = function(barW)
				currentBarW = tonumber(barW) or currentBarW
				rebuild()
			end,
			height = function() return h end,
			setMobileMode = function(flag)
				mobileMode = flag == true
				h = mobileMode and 42 or theme.sizes.tabBar
				rebuild()
			end,
			setTransparency = function(bgTrans)
				root.BackgroundTransparency = bgTrans
				rebuild()
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/terminal
-- ==========================================================================
__VSRBLX_MODULES["ui/code/terminal"] = (function()
-- VS Code Bottom Integrated Panel:
-- PROBLEMS, TODOS, OUTPUT (with Live Roblox LogService channel filters & clickable stack-jump),
-- Multi-Session TERMINAL (`+` new shell, `✕` close, `Up`/`Down` history, `Tab` autocomplete),
-- and HTTP / GIT traffic inspector.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local config = env.require("runtime/config")
	local dispose = env.require("runtime/dispose")
	local log = env.require("runtime/log")
	local robloxConsole = env.require("runtime/roblox_console")
	local diagnostics = env.require("runtime/diagnostics")
	local todoScanner = env.require("runtime/todo_scanner")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")
	local http = env.require("net/http")
	local terminalCmds = env.require("tools/terminal_cmds")

	local M = {}

	local TABS = {
		{ id = "problems", label = "PROBLEMS" },
		{ id = "todos", label = "TODOS" },
		{ id = "output", label = "OUTPUT" },
		{ id = "terminal", label = "TERMINAL" },
		{ id = "http", label = "HTTP / GIT" },
	}

	function M.new(parent, onClosePanel)
		local root = P.frame(parent, {
			name = "BottomPanel",
			size = UDim2.fromScale(1, 1),
			bg = theme.color.panelBg,
			clip = true,
			zIndex = 20,
		})
		local topRule = P.frame(root, {
			size = UDim2.new(1, 0, 0, 1),
			bg = theme.color.border,
			zIndex = 21,
		})

		local header = P.frame(root, {
			name = "PanelHeader",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.fromOffset(0, 1),
			bg = theme.color.panelHeader,
			zIndex = 21,
		})

		local tabRow = P.scroll(header, {
			name = "PanelHeaderTabs",
			size = UDim2.new(1, -112, 1, 0),
			pos = UDim2.fromOffset(6, 0),
			direction = Enum.ScrollingDirection.X,
			autoCanvas = Enum.AutomaticSize.X,
			barThickness = 2,
			zIndex = 22,
		})
		P.list(tabRow, Enum.FillDirection.Horizontal, 8, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local tabButtons = {}
		local activeTab = config.get("workbench.activePanelTab", "terminal")

		local bodyArea = P.frame(root, {
			name = "PanelBody",
			size = UDim2.new(1, 0, 1, -29),
			pos = UDim2.fromOffset(0, 29),
			zIndex = 21,
		})
		bodyArea.BackgroundTransparency = 1

		local rightBtns = P.frame(header, {
			size = UDim2.fromOffset(102, 28),
			pos = UDim2.new(1, -106, 0, 0),
			zIndex = 22,
		})
		P.list(rightBtns, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)

		local newTermBtn = P.button(rightBtns, {
			name = "NewTerminalSessionBtn",
			size = UDim2.fromOffset(24, 22),
			text = "+",
			bold = true,
			textSize = 13,
			color = theme.color.tabActiveText,
			radius = 3,
			order = 1,
			zIndex = 23,
			onClick = function()
				terminalCmds.newSession()
			end,
		})

		P.button(rightBtns, {
			name = "ClearPanelBtn",
			size = UDim2.fromOffset(38, 22),
			text = "Clear",
			textSize = 11,
			color = theme.color.muted,
			radius = 3,
			order = 2,
			zIndex = 23,
			onClick = function()
				if activeTab == "terminal" then terminalCmds.clear()
				elseif activeTab == "output" then log.clear()
				elseif activeTab == "http" then http.clearHistory() end
			end,
		})
		P.button(rightBtns, {
			name = "HidePanelBtn",
			size = UDim2.fromOffset(24, 22),
			text = "✕",
			textSize = 11,
			color = theme.color.muted,
			radius = 3,
			order = 3,
			zIndex = 23,
			onClick = function()
				if onClosePanel then onClosePanel() end
			end,
		})

		-- 1. PROBLEMS view
		local problemsScroll = P.scroll(bodyArea, { name = "ProblemsView", visible = false, zIndex = 22 })
		P.pad(problemsScroll, 6, 8, 6, 8)
		P.list(problemsScroll, Enum.FillDirection.Vertical, 2)

		-- 2. TODOS view
		local todosPane = P.frame(bodyArea, { name = "TodosView", size = UDim2.fromScale(1, 1), visible = false, zIndex = 22 })
		local todoFilterRow = P.frame(todosPane, {
			name = "TodoFilterBar",
			size = UDim2.new(1, 0, 0, 24),
			pos = UDim2.fromOffset(8, 3),
			zIndex = 23,
		})
		P.list(todoFilterRow, Enum.FillDirection.Horizontal, 6, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local todosScroll = P.scroll(todosPane, {
			name = "TodosScroll",
			size = UDim2.new(1, 0, 1, -28),
			pos = UDim2.fromOffset(0, 28),
			zIndex = 23,
		})
		P.pad(todosScroll, 4, 8, 6, 8)
		P.list(todosScroll, Enum.FillDirection.Vertical, 2)

		local activeTodoFilter = "all"
		local renderTodos

		local FILTER_CHIPS = {
			{ id = "all", label = "All" },
			{ id = "fixme", label = "FIXME / BUG" },
			{ id = "todo", label = "TODO / HACK" },
			{ id = "note", label = "NOTE" },
		}
		local filterBtns = {}
		for idx, chip in ipairs(FILTER_CHIPS) do
			local fb = P.button(todoFilterRow, {
				name = "TodoFilter_" .. chip.id,
				size = UDim2.fromOffset(#chip.label * 6 + 20, 20),
				bg = chip.id == activeTodoFilter and theme.color.listActive or theme.color.inputBg,
				hoverBg = theme.color.hover,
				text = chip.label,
				textSize = 10,
				bold = true,
				color = theme.color.sideBarText,
				radius = 10,
				order = idx,
				zIndex = 24,
				activeState = function() return chip.id == activeTodoFilter end,
				onClick = function()
					activeTodoFilter = chip.id
					for fid, b in pairs(filterBtns) do
						b.BackgroundColor3 = (fid == activeTodoFilter) and theme.color.listActive or theme.color.inputBg
						b.BackgroundTransparency = 0
					end
					if renderTodos then renderTodos() end
				end,
			})
			fb.BackgroundTransparency = 0
			filterBtns[chip.id] = fb
		end

		-- 3. OUTPUT view (with Channel Filter Pills + Clickable Stack-Trace Jump!)
		local outputPane = P.frame(bodyArea, { name = "OutputView", size = UDim2.fromScale(1, 1), visible = false, zIndex = 22 })
		local outFilterRow = P.frame(outputPane, {
			name = "OutputFilterBar",
			size = UDim2.new(1, 0, 0, 24),
			pos = UDim2.fromOffset(8, 3),
			zIndex = 23,
		})
		P.list(outFilterRow, Enum.FillDirection.Horizontal, 6, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local outputScroll = P.scroll(outputPane, {
			name = "OutputScroll",
			size = UDim2.new(1, 0, 1, -28),
			pos = UDim2.fromOffset(0, 28),
			zIndex = 23,
		})
		P.pad(outputScroll, 4, 8, 6, 8)
		P.list(outputScroll, Enum.FillDirection.Vertical, 1)

		local activeOutChannel = "all"
		local renderOutput
		local OUT_CHANNELS = {
			{ id = "all", label = "All" },
			{ id = "roblox", label = "Roblox LogService" },
			{ id = "execution", label = "Execution" },
			{ id = "github", label = "GitHub / FS" },
		}
		local outChannelBtns = {}
		for idx, chSpec in ipairs(OUT_CHANNELS) do
			local cb = P.button(outFilterRow, {
				name = "OutFilter_" .. chSpec.id,
				size = UDim2.fromOffset(#chSpec.label * 6 + 18, 20),
				bg = chSpec.id == activeOutChannel and theme.color.listActive or theme.color.inputBg,
				hoverBg = theme.color.hover,
				text = chSpec.label,
				textSize = 10,
				bold = true,
				color = theme.color.sideBarText,
				radius = 10,
				order = idx,
				zIndex = 24,
				activeState = function() return chSpec.id == activeOutChannel end,
				onClick = function()
					activeOutChannel = chSpec.id
					for cid, b in pairs(outChannelBtns) do
						b.BackgroundColor3 = (cid == activeOutChannel) and theme.color.listActive or theme.color.inputBg
						b.BackgroundTransparency = 0
					end
					if renderOutput then renderOutput() end
				end,
			})
			cb.BackgroundTransparency = 0
			outChannelBtns[chSpec.id] = cb
		end

		-- 4. Multi-Tab TERMINAL view
		local termPane = P.frame(bodyArea, { name = "TerminalView", size = UDim2.fromScale(1, 1), visible = false, zIndex = 22 })
		local sessionBar = P.frame(termPane, {
			name = "TerminalSessionBar",
			size = UDim2.new(1, 0, 0, 22),
			bg = theme.color.sideBarHeader,
			zIndex = 23,
		})
		P.pad(sessionBar, 0, 6, 0, 6)
		P.list(sessionBar, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local termScroll = P.scroll(termPane, {
			name = "TerminalScroll",
			size = UDim2.new(1, 0, 1, -52),
			pos = UDim2.fromOffset(0, 22),
			zIndex = 23,
		})
		P.pad(termScroll, 6, 10, 4, 10)
		P.list(termScroll, Enum.FillDirection.Vertical, 2)

		local promptRow = P.frame(termPane, {
			name = "TerminalInputBar",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.new(0, 0, 1, -28),
			bg = theme.color.sideBar,
			zIndex = 23,
		})
		local promptGlyph = P.label(promptRow, {
			size = UDim2.fromOffset(108, 28),
			pos = UDim2.fromOffset(8, 0),
			text = "default:~ ❯",
			mono = true,
			bold = true,
			textSize = 11,
			color = theme.color.accent,
			truncate = true,
			zIndex = 24,
		})
		local _, termInput = P.input(promptRow, {
			name = "TerminalCommandInput",
			size = UDim2.new(1, -168, 0, 24),
			pos = UDim2.fromOffset(118, 2),
			mono = true,
			placeholder = "Type command (help, ls -l, tree, git diff, rblx services, bundle...)",
			zIndex = 24,
		})
		local tabCompBtn = P.button(promptRow, {
			name = "TerminalAutocompleteBtn",
			size = UDim2.fromOffset(42, 22),
			pos = UDim2.new(1, -46, 0, 3),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "Tab ⇥",
			mono = true,
			textSize = 10,
			radius = 3,
			zIndex = 24,
			onClick = function()
				local completed, matches = terminalCmds.autocomplete(termInput.Text)
				termInput.Text = completed
				pcall(function() termInput.CursorPosition = #completed + 1 end)
				if #matches > 1 then
					terminalCmds.print("Completions: " .. table.concat(matches, "   "))
				end
			end,
		})

		local termFocused = false
		termInput.Focused:Connect(function() termFocused = true end)
		termInput.FocusLost:Connect(function(enterPressed)
			termFocused = false
			if enterPressed and termInput.Text ~= "" then
				local cmd = termInput.Text
				termInput.Text = ""
				terminalCmds.execute(cmd)
				task.defer(function() pcall(function() termInput:CaptureFocus() end) end)
			end
		end)

		if env.uis then
			dispose.connection(env.uis.InputBegan:Connect(function(input)
				if not termFocused then return end
				local kc = input.KeyCode
				if kc == Enum.KeyCode.Up then
					local prev = terminalCmds.historyPrev()
					if prev ~= nil then
						termInput.Text = prev
						pcall(function() termInput.CursorPosition = #prev + 1 end)
					end
				elseif kc == Enum.KeyCode.Down then
					local nxt = terminalCmds.historyNext()
					if nxt ~= nil then
						termInput.Text = nxt
						pcall(function() termInput.CursorPosition = #nxt + 1 end)
					end
				elseif kc == Enum.KeyCode.Tab then
					task.defer(function()
						local clean = termInput.Text:gsub("\t", "")
						local completed, matches = terminalCmds.autocomplete(clean)
						termInput.Text = completed
						pcall(function() termInput.CursorPosition = #completed + 1 end)
						if #matches > 1 then
							terminalCmds.print("Completions: " .. table.concat(matches, "   "))
						end
					end)
				end
			end))
		end

		-- 5. HTTP / GIT view
		local httpScroll = P.scroll(bodyArea, { name = "HttpView", visible = false, zIndex = 22 })
		P.pad(httpScroll, 6, 8, 6, 8)
		P.list(httpScroll, Enum.FillDirection.Vertical, 2)

		local function updateTabButtonWidth(btn, txt)
			if not btn then return end
			btn.Text = txt
			btn.Size = UDim2.fromOffset(#txt * 7 + 16, 26)
		end

		local function renderProblems()
			problemsScroll:ClearAllChildren()
			P.pad(problemsScroll, 6, 8, 6, 8)
			P.list(problemsScroll, Enum.FillDirection.Vertical, 2)
			local list, errs, warns = diagnostics.all()
			updateTabButtonWidth(tabButtons.problems, string.format("PROBLEMS (%d)", errs + warns))
			if #list == 0 then
				P.label(problemsScroll, {
					size = UDim2.new(1, 0, 0, 22),
					text = "No problems have been detected in the workspace.",
					color = theme.color.muted,
					textSize = 12,
					zIndex = 23,
				})
				return
			end
			for idx, item in ipairs(list) do
				local row = P.button(problemsScroll, {
					size = UDim2.new(1, 0, 0, 22),
					hoverBg = theme.color.hover,
					alignX = Enum.TextXAlignment.Left,
					mono = true,
					textSize = 12,
					color = item.severity == "error" and theme.color.bad or theme.color.warn,
					text = string.format(
						"  %s  %s:%d — %s",
						item.severity == "error" and "⊗" or "⚠",
						tostring(item.path or "buffer"),
						item.line or 1,
						item.message
					),
					order = idx,
					zIndex = 23,
					onClick = function()
						if item.path and item.path ~= "" then
							codeStore.openFile(item.path, { line = item.line or 1 })
						elseif item.docId then
							codeStore.activate(item.docId)
							codeStore.jumpToLine(item.docId, item.line or 1, 1)
						end
					end,
				})
				row.TextTruncate = Enum.TextTruncate.AtEnd
			end
		end

		renderTodos = function()
			local items, counts = todoScanner.scanAll()
			updateTabButtonWidth(tabButtons.todos, string.format("TODOS (%d)", counts.total or 0))
			if activeTab ~= "todos" then return end

			todosScroll:ClearAllChildren()
			P.pad(todosScroll, 4, 8, 6, 8)
			P.list(todosScroll, Enum.FillDirection.Vertical, 2)

			local shown = 0
			for idx, item in ipairs(items) do
				if activeTodoFilter == "all" or item.group == activeTodoFilter then
					shown = shown + 1
					local badgeCol = theme.color.warn
					if item.group == "fixme" then
						badgeCol = theme.color.bad
					elseif item.group == "note" then
						badgeCol = Color3.fromRGB(79, 193, 255)
					end

					local row = P.button(todosScroll, {
						name = "TodoItem_" .. tostring(shown),
						size = UDim2.new(1, 0, 0, 22),
						hoverBg = theme.color.hover,
						text = "",
						order = idx,
						zIndex = 24,
						onClick = function()
							if item.docId and codeStore.get(item.docId) then
								codeStore.activate(item.docId)
								codeStore.jumpToLine(item.docId, item.line or 1, item.col or 1)
							elseif item.path and item.path ~= "" then
								codeStore.openFile(item.path, { line = item.line or 1, col = item.col or 1 })
							end
						end,
					})
					local pill = P.frame(row, {
						size = UDim2.fromOffset(48, 16),
						pos = UDim2.fromOffset(4, 3),
						bg = badgeCol,
						transparency = 0.78,
						border = badgeCol,
						radius = 3,
						zIndex = 25,
					})
					P.label(pill, {
						size = UDim2.fromScale(1, 1),
						text = item.tag,
						mono = true,
						bold = true,
						textSize = 10,
						color = badgeCol,
						alignX = Enum.TextXAlignment.Center,
						zIndex = 26,
					})
					P.label(row, {
						size = UDim2.new(1, -62, 1, 0),
						pos = UDim2.fromOffset(60, 0),
						mono = true,
						textSize = 12,
						color = theme.color.editorText,
						text = string.format("%s:%d — %s", tostring(item.path or "buffer"), item.line or 1, item.message),
						truncate = true,
						zIndex = 25,
					})
				end
			end

			if shown == 0 then
				P.label(todosScroll, {
					size = UDim2.new(1, 0, 0, 22),
					text = "No TODO / FIXME / NOTE comments found for this filter.",
					color = theme.color.muted,
					textSize = 12,
					zIndex = 24,
				})
			end
		end

		renderOutput = function()
			outputScroll:ClearAllChildren()
			P.pad(outputScroll, 4, 8, 6, 8)
			P.list(outputScroll, Enum.FillDirection.Vertical, 1)

			local allItems = log.list("all")
			local filtered = {}
			for _, entry in ipairs(allItems) do
				if activeOutChannel == "all"
					or entry.channel == activeOutChannel
					or (activeOutChannel == "github" and (entry.channel == "fs" or entry.channel == "git")) then
					filtered[#filtered + 1] = entry
				end
			end

			local startIdx = math.max(1, #filtered - 85)
			local order = 0
			for i = startIdx, #filtered do
				order = order + 1
				local entry = filtered[i]
				local col = theme.color.editorText
				if entry.level == "error" then col = theme.color.bad
				elseif entry.level == "warn" then col = theme.color.warn
				elseif entry.channel == "github" or entry.channel == "roblox" then col = theme.color.good end

				local loc = robloxConsole.parseStackLocation(entry.message)
				local jumpHint = loc and "  ↗" or ""
				local row = P.button(outputScroll, {
					name = "OutputRow_" .. tostring(order),
					size = UDim2.new(1, 0, 0, 19),
					hoverBg = loc and theme.color.hover or nil,
					alignX = Enum.TextXAlignment.Left,
					mono = true,
					textSize = 12,
					color = col,
					text = string.format("[%s][%s] %s%s", entry.time, entry.channel, entry.message, jumpHint),
					order = order,
					zIndex = 24,
					onClick = function()
						if loc then
							robloxConsole.jumpToLogEntry(entry)
						end
					end,
				})
				row.TextTruncate = Enum.TextTruncate.AtEnd
			end
			outputScroll.CanvasPosition = Vector2.new(0, 99999)
		end

		local function renderTerminal()
			-- Update session tabs
			sessionBar:ClearAllChildren()
			P.pad(sessionBar, 0, 6, 0, 6)
			P.list(sessionBar, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

			for idx, sess in ipairs(terminalCmds.sessions) do
				local isCur = (sess.id == terminalCmds.activeSessionId)
				local chip = P.frame(sessionBar, {
					name = "TermSession_" .. sess.id,
					size = UDim2.fromOffset(#sess.title * 7 + 34, 18),
					bg = isCur and theme.color.accent or theme.color.inputBg,
					radius = 3,
					order = idx,
					zIndex = 24,
				})
				P.button(chip, {
					size = UDim2.new(1, -18, 1, 0),
					pos = UDim2.fromOffset(4, 0),
					alignX = Enum.TextXAlignment.Left,
					mono = true,
					bold = isCur,
					textSize = 10,
					color = isCur and Color3.fromRGB(255, 255, 255) or theme.color.sideBarText,
					text = "❯ " .. sess.title,
					zIndex = 25,
					onClick = function()
						terminalCmds.switchSession(sess.id)
					end,
				})
				P.button(chip, {
					name = "CloseTermSession_" .. sess.id,
					size = UDim2.fromOffset(16, 16),
					pos = UDim2.new(1, -17, 0, 1),
					text = "✕",
					textSize = 9,
					color = isCur and Color3.fromRGB(255, 255, 255) or theme.color.muted,
					radius = 2,
					zIndex = 25,
					onClick = function()
						terminalCmds.closeSession(sess.id)
					end,
				})
			end

			local curSess = terminalCmds.activeSession()
			local cwdShort = (curSess and curSess.cwd ~= "") and ("~/" .. curSess.cwd) or "~"
			promptGlyph.Text = string.format("%s:%s ❯", workspaceFs.activeName, cwdShort)

			termScroll:ClearAllChildren()
			P.pad(termScroll, 6, 10, 4, 10)
			P.list(termScroll, Enum.FillDirection.Vertical, 2)
			local startIdx = math.max(1, #terminalCmds.lines - 95)
			local order = 0
			for i = startIdx, #terminalCmds.lines do
				order = order + 1
				local line = terminalCmds.lines[i]
				local isPrompt = line:find("^vsrblx:") ~= nil
				P.label(termScroll, {
					size = UDim2.new(1, 0, 0, 18),
					mono = true,
					textSize = 12,
					color = isPrompt and theme.color.accent or theme.color.editorText,
					text = line,
					wrap = true,
					order = order,
					zIndex = 24,
				})
			end
			termScroll.CanvasPosition = Vector2.new(0, 99999)
		end

		local function renderHttp()
			httpScroll:ClearAllChildren()
			P.pad(httpScroll, 6, 8, 6, 8)
			P.list(httpScroll, Enum.FillDirection.Vertical, 2)
			if #http.history == 0 then
				P.label(httpScroll, {
					size = UDim2.new(1, 0, 0, 22),
					text = "No Executor HTTP requests sent yet. Clone or sync a GitHub repo to inspect traffic.",
					color = theme.color.muted,
					textSize = 12,
					zIndex = 23,
				})
				return
			end
			local order = 0
			for i = #http.history, math.max(1, #http.history - 50), -1 do
				order = order + 1
				local h = http.history[i]
				P.label(httpScroll, {
					size = UDim2.new(1, 0, 0, 19),
					mono = true,
					textSize = 12,
					color = h.ok and theme.color.good or theme.color.bad,
					text = string.format("[%s] %-6s %3d (%4d ms, %6s B)  %s", h.time, h.method, h.status, h.ms, tostring(h.bytes), h.url),
					truncate = true,
					order = order,
					zIndex = 23,
				})
			end
		end

		local function selectTab(id)
			activeTab = id
			config.set("workbench.activePanelTab", id, { quiet = true })
			problemsScroll.Visible = (id == "problems")
			todosPane.Visible = (id == "todos")
			outputPane.Visible = (id == "output")
			termPane.Visible = (id == "terminal")
			httpScroll.Visible = (id == "http")
			newTermBtn.Visible = (id == "terminal")
			for tid, btn in pairs(tabButtons) do
				btn.TextColor3 = (tid == id) and theme.color.tabActiveText or theme.color.muted
			end
			if id == "problems" then renderProblems()
			elseif id == "todos" then renderTodos()
			elseif id == "output" then renderOutput()
			elseif id == "terminal" then renderTerminal()
			elseif id == "http" then renderHttp() end
		end

		for idx, spec in ipairs(TABS) do
			local btn = P.button(tabRow, {
				name = "PanelTab_" .. spec.id,
				size = UDim2.fromOffset(#spec.label * 7 + 18, 26),
				text = spec.label,
				bold = true,
				textSize = 11,
				color = theme.color.muted,
				order = idx,
				zIndex = 23,
				onClick = function() selectTab(spec.id) end,
			})
			tabButtons[spec.id] = btn
		end

		diagnostics.changed:connect(renderProblems)
		todoScanner.changed:connect(renderTodos)
		log.added:connect(function() if activeTab == "output" then renderOutput() end end)
		log.cleared:connect(renderOutput)
		terminalCmds.changed:connect(renderTerminal)
		workspaceFs.changed:connect(function() if activeTab == "terminal" then renderTerminal() end end)
		http.changed:connect(function() if activeTab == "http" then renderHttp() end end)
		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.panelBg
			topRule.BackgroundColor3 = theme.color.border
			header.BackgroundColor3 = theme.color.panelHeader
			sessionBar.BackgroundColor3 = theme.color.sideBarHeader
			promptRow.BackgroundColor3 = theme.color.sideBar
			promptGlyph.TextColor3 = theme.color.accent
			tabCompBtn.BackgroundColor3 = theme.color.inputBg
			for fid, b in pairs(filterBtns) do
				b.BackgroundColor3 = (fid == activeTodoFilter) and theme.color.listActive or theme.color.inputBg
				b.TextColor3 = theme.color.sideBarText
			end
			for cid, b in pairs(outChannelBtns) do
				b.BackgroundColor3 = (cid == activeOutChannel) and theme.color.listActive or theme.color.inputBg
				b.TextColor3 = theme.color.sideBarText
			end
			selectTab(activeTab)
		end)

		renderProblems()
		renderTodos()
		selectTab(activeTab)

		return {
			root = root,
			header = header,
			promptRow = promptRow,
			selectTab = selectTab,
			setOutputChannel = function(ch)
				activeOutChannel = ch or "all"
				if activeTab == "output" then renderOutput() end
			end,
			setTransparency = function(bgTrans)
				root.BackgroundTransparency = bgTrans
				header.BackgroundTransparency = bgTrans
				sessionBar.BackgroundTransparency = bgTrans
				promptRow.BackgroundTransparency = bgTrans
			end,
			focusTerminal = function()
				selectTab("terminal")
				task.defer(function() pcall(function() termInput:CaptureFocus() end) end)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/welcome
-- ==========================================================================
__VSRBLX_MODULES["ui/code/welcome"] = (function()
-- VS Code Welcome Tab shown when no editor tabs are open.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local brand = env.require("ui/brand")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local config = env.require("runtime/config")
	local commands = env.require("runtime/command_catalog")
	local fsSync = env.require("tools/fs_sync")

	local M = {}

	function M.new(parent)
		local root = P.scroll(parent, {
			name = "WelcomeScreen",
			size = UDim2.fromScale(1, 1),
			bg = theme.color.editor,
			visible = false,
			zIndex = 14,
		})
		P.pad(root, 32, 36, 32, 36)

		local headerRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 56),
			zIndex = 15,
		})
		local logo = brand.draw(headerRow, 42, 16)
		logo.Position = UDim2.fromOffset(0, 6)

		local titleLbl = P.label(headerRow, {
			size = UDim2.new(1, -58, 0, 28),
			pos = UDim2.fromOffset(56, 2),
			text = "Visual Studio Code · Roblox Edition",
			bold = true,
			textSize = 22,
			color = theme.color.tabActiveText,
			zIndex = 16,
		})
		local subLbl = P.label(headerRow, {
			size = UDim2.new(1, -58, 0, 20),
			pos = UDim2.fromOffset(56, 32),
			text = string.format(
				"100%% Luau  |  Host: %s  |  Disk: %s  |  HTTP: %s",
				caps.executor,
				fsx.isBackedByDisk() and "writefile / readfile" or "Virtual Disk",
				caps.requestName or caps.http
			),
			textSize = 12,
			color = theme.color.muted,
			zIndex = 16,
		})

		local grid = P.frame(root, {
			size = UDim2.new(1, 0, 0, 260),
			pos = UDim2.fromOffset(0, 82),
			zIndex = 15,
		})

		local leftCol = P.frame(grid, {
			size = UDim2.new(0.48, 0, 1, 0),
			zIndex = 15,
		})
		P.list(leftCol, Enum.FillDirection.Vertical, 8)

		P.label(leftCol, {
			size = UDim2.new(1, 0, 0, 20),
			text = "Start",
			bold = true,
			textSize = 14,
			color = theme.color.tabActiveText,
			order = 1,
			zIndex = 16,
		})

		local START_ACTIONS = {
			{ label = "+  New Disk File...", cmd = "file.newDiskFile" },
			{ label = "📂  Switch Local Disk Workspace...", cmd = "workspace.switch" },
			{ label = "💾  Mount Raw Executor Folder...", cmd = "workspace.mountRaw" },
			{ label = "⎇  Clone GitHub Repository...", cmd = "github.clone" },
			{ label = "🔑  Set GitHub Personal Access Token...", cmd = "github.auth" },
			{ label = "🎨  Switch Color Theme...", cmd = "workbench.commandPalette" },
		}

		for idx, act in ipairs(START_ACTIONS) do
			P.button(leftCol, {
				size = UDim2.new(1, 0, 0, 26),
				alignX = Enum.TextXAlignment.Left,
				text = "  " .. act.label,
				color = theme.color.accent,
				radius = 4,
				order = idx + 1,
				zIndex = 16,
				onClick = function() commands.run(act.cmd) end,
			})
		end

		local rightCol = P.frame(grid, {
			size = UDim2.new(0.48, 0, 1, 0),
			pos = UDim2.new(0.52, 0, 0, 0),
			zIndex = 15,
		})
		P.list(rightCol, Enum.FillDirection.Vertical, 6)

		P.label(rightCol, {
			size = UDim2.new(1, 0, 0, 20),
			text = "Recent Disk Workspaces",
			bold = true,
			textSize = 14,
			color = theme.color.tabActiveText,
			order = 1,
			zIndex = 16,
		})

		local recentBox = P.frame(rightCol, {
			size = UDim2.new(1, 0, 0, 180),
			order = 2,
			zIndex = 16,
		})
		P.list(recentBox, Enum.FillDirection.Vertical, 4)

		local function refreshRecent()
			recentBox:ClearAllChildren()
			P.list(recentBox, Enum.FillDirection.Vertical, 4)
			local recent = config.get("files.recentWorkspaces", { "default" })
			if type(recent) == "table" then
				for i, name in ipairs(recent) do
					local wsName = tostring(name)
					P.button(recentBox, {
						size = UDim2.new(1, 0, 0, 24),
						alignX = Enum.TextXAlignment.Left,
						text = "  VSRBLX/workspaces/" .. wsName,
						mono = true,
						textSize = 12,
						color = theme.color.sideBarText,
						radius = 4,
						order = i,
						zIndex = 17,
						onClick = function() fsSync.switchWorkspace(wsName) end,
					})
				end
			end
		end

		config.changed:connect(function(key)
			if key == "*" or key == "files.recentWorkspaces" then refreshRecent() end
		end)
		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.editor
			titleLbl.TextColor3 = theme.color.tabActiveText
			subLbl.TextColor3 = theme.color.muted
		end)

		refreshRecent()
		return {
			root = root,
			refresh = refreshRecent,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/command_palette
-- ==========================================================================
__VSRBLX_MODULES["ui/command_palette"] = (function()
-- VS Code Command Palette (`>`), Quick Open File Finder (`Ctrl+P`), Go to Line (`:`),
-- and Go to Symbol (`@`) modal overlay.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local icons = env.require("ui/icons")
	local util = env.require("runtime/util")
	local commands = env.require("runtime/command_catalog")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")
	local codeFolding = env.require("runtime/code_folding")

	local M = { openState = false }

	function M.new(parentWindow)
		local backdrop = P.button(parentWindow, {
			name = "CommandPaletteBackdrop",
			size = UDim2.fromScale(1, 1),
			text = "",
			visible = false,
			zIndex = 160,
			onClick = function()
				backdrop.Visible = false
				M.openState = false
			end,
		})
		backdrop.BackgroundTransparency = 1

		local card = P.frame(backdrop, {
			name = "CommandPaletteCard",
			size = UDim2.fromOffset(500, 320),
			pos = UDim2.new(0.5, 0, 0, 36),
			anchor = Vector2.new(0.5, 0),
			bg = theme.color.dropdownBg,
			radius = 6,
			border = theme.color.border,
			active = true,
			zIndex = 162,
		})
		P.pad(card, 8, 8, 8, 8)

		local inputWrap, box = P.input(card, {
			name = "PaletteInput",
			size = UDim2.new(1, 0, 0, 30),
			placeholder = "Search files by name, or type '>' for commands, ':' for line, '@' for symbols",
			zIndex = 163,
		})
		inputWrap.Active = true

		local listScroll = P.scroll(card, {
			name = "PaletteResults",
			size = UDim2.new(1, 0, 1, -38),
			pos = UDim2.fromOffset(0, 38),
			zIndex = 163,
		})
		P.list(listScroll, Enum.FillDirection.Vertical, 2)

		local currentResults = {}

		local function closePalette()
			backdrop.Visible = false
			M.openState = false
		end

		local function populate(rawText)
			listScroll:ClearAllChildren()
			P.list(listScroll, Enum.FillDirection.Vertical, 2)
			currentResults = {}
			local text = tostring(rawText or "")

			if util.startsWith(text, ">") then
				local found = commands.search(text:sub(2))
				for idx, cmd in ipairs(found) do
					if idx <= 40 then
						currentResults[#currentResults + 1] = function()
							closePalette()
							commands.run(cmd.id)
						end
						local row = P.button(listScroll, {
							name = "Cmd_" .. cmd.id,
							size = UDim2.new(1, 0, 0, 26),
							hoverBg = theme.color.listActive,
							text = "",
							radius = 3,
							order = idx,
							zIndex = 164,
							onClick = currentResults[#currentResults],
						})
						P.label(row, {
							size = UDim2.new(1, -100, 1, 0),
							pos = UDim2.fromOffset(8, 0),
							text = cmd.label,
							textSize = 12,
							color = theme.color.sideBarText,
							truncate = true,
							zIndex = 165,
						})
						if cmd.shortcut ~= "" then
							P.label(row, {
								size = UDim2.fromOffset(90, 26),
								pos = UDim2.new(1, -96, 0, 0),
								text = cmd.shortcut,
								textSize = 11,
								color = theme.color.muted,
								alignX = Enum.TextXAlignment.Right,
								zIndex = 165,
							})
						end
					end
				end
			elseif util.startsWith(text, ":") then
				local ln = tonumber(util.trim(text:sub(2))) or 1
				currentResults[1] = function()
					closePalette()
					local doc = codeStore.active()
					if doc then codeStore.jumpToLine(doc.id, ln, 1) end
				end
				P.button(listScroll, {
					size = UDim2.new(1, 0, 0, 28),
					hoverBg = theme.color.listActive,
					text = "  Go to Line " .. tostring(ln),
					alignX = Enum.TextXAlignment.Left,
					radius = 3,
					zIndex = 164,
					onClick = currentResults[1],
				})
			elseif util.startsWith(text, "@") then
				local doc = codeStore.active()
				local q = util.trim(text:sub(2)):lower()
				local syms = doc and codeFolding.symbols(doc.content, doc.langId) or {}
				local rank = 0
				for _, sym in ipairs(syms) do
					if q == "" or sym.name:lower():find(q, 1, true) then
						rank = rank + 1
						local targetLn = sym.line
						currentResults[rank] = function()
							closePalette()
							if doc then codeStore.jumpToLine(doc.id, targetLn, 1) end
						end
						local row = P.button(listScroll, {
							size = UDim2.new(1, 0, 0, 26),
							hoverBg = theme.color.listActive,
							text = "",
							radius = 3,
							order = rank,
							zIndex = 164,
							onClick = currentResults[rank],
						})
						P.label(row, {
							size = UDim2.new(1, -60, 1, 0),
							pos = UDim2.fromOffset(8, 0),
							text = string.format("[%s] %s", sym.kind, sym.name),
							mono = true,
							textSize = 12,
							color = theme.color.sideBarText,
							zIndex = 165,
						})
						P.label(row, {
							size = UDim2.fromOffset(50, 26),
							pos = UDim2.new(1, -56, 0, 0),
							text = "Ln " .. tostring(sym.line),
							textSize = 11,
							color = theme.color.muted,
							alignX = Enum.TextXAlignment.Right,
							zIndex = 165,
						})
					end
				end
			else
				local q = util.trim(text):lower()
				local files = workspaceFs.listAllFiles("")
				local rank = 0
				for _, f in ipairs(files) do
					if rank < 35 and (q == "" or f.path:lower():find(q, 1, true)) then
						rank = rank + 1
						local targetPath = f.path
						currentResults[rank] = function()
							closePalette()
							codeStore.openFile(targetPath)
						end
						local row = P.button(listScroll, {
							name = "FileHit_" .. tostring(rank),
							size = UDim2.new(1, 0, 0, 26),
							hoverBg = theme.color.listActive,
							text = "",
							radius = 3,
							order = rank,
							zIndex = 164,
							onClick = currentResults[rank],
						})
						local badge = icons.fileBadge(row, f.lang, false, 165)
						badge.Position = UDim2.fromOffset(6, 6)
						P.label(row, {
							size = UDim2.new(1, -42, 1, 0),
							pos = UDim2.fromOffset(36, 0),
							text = f.name .. "   —   " .. f.path,
							textSize = 12,
							color = theme.color.sideBarText,
							truncate = true,
							zIndex = 165,
						})
					end
				end
			end
		end

		box:GetPropertyChangedSignal("Text"):Connect(function()
			if backdrop.Visible then
				populate(box.Text)
			end
		end)

		box.FocusLost:Connect(function(enterPressed)
			if enterPressed and currentResults[1] then
				currentResults[1]()
			end
		end)

		local api = {}
		function api.open(prefix)
			M.openState = true
			backdrop.Visible = true
			card.BackgroundColor3 = theme.color.dropdownBg
			box.Text = prefix or ""
			populate(box.Text)
			task.defer(function()
				pcall(function()
					box:CaptureFocus()
					box.CursorPosition = #box.Text + 1
				end)
			end)
		end

		function api.close()
			closePalette()
		end

		return api
	end

	return M
end
end)()

-- ==========================================================================
-- ui/icons
-- ==========================================================================
__VSRBLX_MODULES["ui/icons"] = (function()
-- Pure Roblox Frame-drawn vector VS Code Codicons & Seti-style colored file/folder icons.
-- Requires zero external rbxassetid uploads so icons never break, blur, or get moderated.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local languages = env.require("runtime/languages")
	local util = env.require("runtime/util")

	local M = {}

	local function lineBar(parent, x, y, w, h, col, rot, z, rad)
		local b = P.frame(parent, {
			size = UDim2.fromOffset(w, h),
			pos = UDim2.fromOffset(x, y),
			bg = col,
			radius = rad,
			zIndex = z,
		})
		if rot then b.Rotation = rot end
		return b
	end

	local function outlineBox(parent, x, y, w, h, col, radius, z, strokeW)
		local f = P.frame(parent, {
			size = UDim2.fromOffset(w, h),
			pos = UDim2.fromOffset(x, y),
			radius = radius or 2,
			border = col,
			borderWidth = strokeW or 1.4,
			zIndex = z,
		})
		return f
	end

	function M.codicon(parent, name, size, color, zIndex)
		local s = size or 20
		local col = color or theme.color.activityIcon
		local z = zIndex or 5
		local root = P.frame(parent, {
			name = "Icon_" .. tostring(name),
			size = UDim2.fromOffset(s, s),
			zIndex = z,
		})

		if name == "explorer" then
			-- Two overlapping document pages with folded corner line
			outlineBox(root, 2, 5, s - 8, s - 7, col, 2, z + 1, 1.4)
			local front = P.frame(root, {
				size = UDim2.fromOffset(s - 8, s - 7),
				pos = UDim2.fromOffset(6, 2),
				bg = theme.color.activityBar,
				radius = 2,
				border = col,
				borderWidth = 1.4,
				zIndex = z + 2,
			})
			front.BackgroundTransparency = 0.25
			lineBar(front, 3, 4, math.max(4, s - 14), 1, col, 0, z + 3)
			lineBar(front, 3, 7, math.max(3, s - 16), 1, col, 0, z + 3)
		elseif name == "search" then
			local r = math.floor(s * 0.58)
			local circle = outlineBox(root, 2, 2, r, r, col, math.floor(r / 2) + 1, z + 1, 1.5)
			circle.Name = "Lens"
			lineBar(root, math.floor(s * 0.56), math.floor(s * 0.69), math.floor(s * 0.36), 2, col, 45, z + 1, 1)
		elseif name == "scm" then
			outlineBox(root, 3, 2, 5, 5, col, 3, z + 2, 1.4)
			outlineBox(root, 3, s - 7, 5, 5, col, 3, z + 2, 1.4)
			outlineBox(root, s - 8, 5, 5, 5, col, 3, z + 2, 1.4)
			lineBar(root, 5, 7, 2, s - 14, col, 0, z + 1)
			lineBar(root, 6, math.floor(s * 0.46), s - 13, 2, col, -20, z + 1)
		elseif name == "debug" then
			-- Play triangle + small debug bug circle on bottom-left
			outlineBox(root, 2, s - 8, 6, 6, col, 3, z + 2, 1.3)
			local playLbl = P.label(root, {
				size = UDim2.fromOffset(s - 2, s - 2),
				pos = UDim2.fromOffset(2, 0),
				text = "▷",
				bold = true,
				textSize = math.max(11, s - 5),
				color = col,
				alignX = Enum.TextXAlignment.Center,
				zIndex = z + 2,
			})
			playLbl.Name = "PlayGlyph"
		elseif name == "extensions" then
			local b = math.floor((s - 7) / 2)
			outlineBox(root, 2, 3, b, b, col, 1, z + 1, 1.4)
			outlineBox(root, 2, 4 + b, b, b, col, 1, z + 1, 1.4)
			outlineBox(root, 3 + b, 4 + b, b, b, col, 1, z + 1, 1.4)
			local detached = outlineBox(root, 5 + b, 1, b, b, col, 1, z + 2, 1.4)
			detached.Rotation = 12
		elseif name == "settings" then
			local r = s - 6
			outlineBox(root, 3, 3, r, r, col, math.floor(r / 2), z + 1, 1.4)
			outlineBox(root, math.floor(s / 2) - 2, math.floor(s / 2) - 2, 4, 4, col, 2, z + 2, 1.4)
			lineBar(root, math.floor(s / 2) - 1, 1, 2, 3, col, 0, z + 1)
			lineBar(root, math.floor(s / 2) - 1, s - 4, 2, 3, col, 0, z + 1)
			lineBar(root, 1, math.floor(s / 2) - 1, 3, 2, col, 0, z + 1)
			lineBar(root, s - 4, math.floor(s / 2) - 1, 3, 2, col, 0, z + 1)
		elseif name == "account" then
			outlineBox(root, math.floor(s / 2) - 4, 2, 8, 8, col, 4, z + 1, 1.4)
			outlineBox(root, 3, s - 8, s - 6, 6, col, 3, z + 1, 1.4)
		elseif name == "sidebar" then
			outlineBox(root, 2, 3, s - 4, s - 6, col, 2, z + 1, 1.3)
			lineBar(root, 6, 4, 2, s - 8, col, 0, z + 2)
		elseif name == "panel" then
			outlineBox(root, 2, 3, s - 4, s - 6, col, 2, z + 1, 1.3)
			lineBar(root, 3, s - 7, s - 6, 2, col, 0, z + 2)
		elseif name == "split" then
			outlineBox(root, 2, 3, s - 4, s - 6, col, 2, z + 1, 1.3)
			lineBar(root, math.floor(s / 2), 4, 1, s - 8, col, 0, z + 2)
		elseif name == "zen" then
			-- Four inward/outward focus corners
			lineBar(root, 2, 2, 4, 1, col, 0, z + 1)
			lineBar(root, 2, 2, 1, 4, col, 0, z + 1)
			lineBar(root, s - 6, 2, 4, 1, col, 0, z + 1)
			lineBar(root, s - 3, 2, 1, 4, col, 0, z + 1)
			lineBar(root, 2, s - 3, 4, 1, col, 0, z + 1)
			lineBar(root, 2, s - 6, 1, 4, col, 0, z + 1)
			lineBar(root, s - 6, s - 3, 4, 1, col, 0, z + 1)
			lineBar(root, s - 3, s - 6, 1, 4, col, 0, z + 1)
			outlineBox(root, 5, 5, s - 10, s - 10, col, 1, z + 2, 1.2)
		elseif name == "opacity" then
			-- Half-filled contrast circle (`◐`)
			local r = s - 4
			local c = outlineBox(root, 2, 2, r, r, col, math.floor(r / 2), z + 1, 1.3)
			c.ClipsDescendants = true
			lineBar(c, 0, 0, math.floor(r / 2), r, col, 0, z + 2)
		elseif name == "newFile" then
			outlineBox(root, 3, 2, s - 7, s - 4, col, 2, z + 1, 1.3)
			lineBar(root, s - 6, s - 7, 5, 1, col, 0, z + 2)
			lineBar(root, s - 4, s - 9, 1, 5, col, 0, z + 2)
		elseif name == "newFolder" then
			lineBar(root, 2, 3, 6, 2, col, 0, z + 1, 1)
			outlineBox(root, 2, 5, s - 5, s - 7, col, 2, z + 1, 1.3)
			lineBar(root, s - 6, s - 7, 5, 1, col, 0, z + 2)
			lineBar(root, s - 4, s - 9, 1, 5, col, 0, z + 2)
		elseif name == "refresh" then
			P.label(root, {
				size = UDim2.fromScale(1, 1),
				text = "↻",
				bold = true,
				textSize = math.max(12, s - 2),
				color = col,
				alignX = Enum.TextXAlignment.Center,
				zIndex = z + 1,
			})
		elseif name == "saveAll" then
			outlineBox(root, 2, 4, s - 6, s - 6, col, 2, z + 1, 1.3)
			outlineBox(root, 4, 2, s - 6, s - 6, col, 2, z + 2, 1.3)
			lineBar(root, 6, 4, s - 10, 3, col, 0, z + 3)
		elseif name == "todo" then
			outlineBox(root, 2, 2, s - 4, s - 4, col, 3, z + 1, 1.3)
			P.label(root, {
				size = UDim2.fromScale(1, 1),
				text = "✓",
				bold = true,
				textSize = math.max(10, s - 4),
				color = col,
				alignX = Enum.TextXAlignment.Center,
				zIndex = z + 2,
			})
		elseif name == "pin" then
			lineBar(root, math.floor(s / 2) - 3, 3, 6, 2, col, 0, z + 2, 1)
			outlineBox(root, math.floor(s / 2) - 2, 5, 4, 5, col, 1, z + 2, 1.2)
			lineBar(root, math.floor(s / 2) - 1, 10, 2, 5, col, 0, z + 1)
		elseif name == "minimize" then
			lineBar(root, 4, math.floor(s / 2), s - 8, 1, col, 0, z + 1)
		elseif name == "maximize" then
			outlineBox(root, 4, 4, s - 8, s - 8, col, 1, z + 1, 1.3)
		elseif name == "close" then
			lineBar(root, 3, math.floor(s / 2), s - 6, 2, col, 45, z + 1)
			lineBar(root, 3, math.floor(s / 2), s - 6, 2, col, -45, z + 1)
		end

		return root
	end

	-- Authentic VS Code Seti-style file & folder icon colors and emblems
	local SETI_FOLDER_COLORS = {
		src = Color3.fromRGB(78, 201, 176),
		ui = Color3.fromRGB(86, 156, 214),
		runtime = Color3.fromRGB(197, 134, 192),
		tools = Color3.fromRGB(220, 173, 96),
		test = Color3.fromRGB(115, 201, 145),
		docs = Color3.fromRGB(79, 193, 255),
		dist = Color3.fromRGB(206, 145, 120),
		web = Color3.fromRGB(241, 224, 90),
		scripts = Color3.fromRGB(0, 162, 255),
		[".github"] = Color3.fromRGB(156, 220, 254),
	}

	local SETI_FILE_SPECS = {
		luau = { glyph = "🌙", text = "LU", rgb = { 0, 162, 255 }, boxed = true },
		lua = { glyph = "LU", rgb = { 81, 160, 213 }, boxed = true },
		typescript = { glyph = "TS", rgb = { 49, 120, 198 }, solid = true },
		javascript = { glyph = "JS", rgb = { 241, 224, 90 }, solid = true, darkText = true },
		python = { glyph = "PY", rgb = { 53, 114, 165 }, boxed = true },
		json = { glyph = "{}", rgb = { 203, 203, 65 } },
		html = { glyph = "<>", rgb = { 227, 76, 38 } },
		css = { glyph = "#", rgb = { 66, 165, 245 } },
		markdown = { glyph = "M↓", rgb = { 81, 154, 186 }, boxed = true },
		rust = { glyph = "RS", rgb = { 222, 165, 132 }, boxed = true },
		go = { glyph = "GO", rgb = { 0, 173, 216 }, boxed = true },
		c = { glyph = "C", rgb = { 104, 159, 216 }, boxed = true },
		cpp = { glyph = "C+", rgb = { 243, 75, 125 }, boxed = true },
		csharp = { glyph = "C#", rgb = { 23, 134, 0 }, boxed = true },
		sql = { glyph = "DB", rgb = { 227, 140, 0 }, boxed = true },
		yaml = { glyph = "Y!", rgb = { 203, 23, 30 } },
		shell = { glyph = "$_", rgb = { 137, 224, 81 } },
		plaintext = { glyph = "≡", rgb = { 150, 150, 150 } },
	}

	local SPECIAL_FILENAMES = {
		["readme.md"] = { glyph = "ⓘ", rgb = { 79, 193, 255 } },
		["license"] = { glyph = "⚖", rgb = { 215, 186, 125 } },
		[".gitignore"] = { glyph = "⎇", rgb = { 241, 76, 76 } },
		["settings.json"] = { glyph = "⚙", rgb = { 156, 220, 254 } },
	}

	function M.fileBadge(parent, langOrPath, isDir, zIndex, isExpanded)
		local z = zIndex or 5
		if isDir then
			local folderName = type(langOrPath) == "string" and util.basename(langOrPath):lower() or ""
			local folderCol = SETI_FOLDER_COLORS[folderName] or Color3.fromRGB(220, 173, 96)
			local wrap = P.frame(parent, {
				name = "FolderBadge",
				size = UDim2.fromOffset(16, 13),
				zIndex = z,
			})
			-- Folder top tab
			P.frame(wrap, {
				size = UDim2.fromOffset(7, 3),
				pos = UDim2.fromOffset(0, 1),
				bg = folderCol,
				radius = 1,
				zIndex = z + 1,
			})
			-- Folder body
			local body = P.frame(wrap, {
				size = UDim2.fromOffset(15, 10),
				pos = UDim2.fromOffset(0, 3),
				bg = folderCol,
				transparency = isExpanded and 0.32 or 0.08,
				radius = 2,
				border = isExpanded and folderCol or nil,
				borderWidth = isExpanded and 1.2 or nil,
				zIndex = z + 1,
			})
			if isExpanded then
				P.frame(body, {
					size = UDim2.fromOffset(13, 5),
					pos = UDim2.fromOffset(1, 4),
					bg = folderCol,
					radius = 1,
					zIndex = z + 2,
				})
			end
			return wrap
		end

		local spec = nil
		if type(langOrPath) == "string" then
			local baseLower = util.basename(langOrPath):lower()
			if SPECIAL_FILENAMES[baseLower] then
				spec = SPECIAL_FILENAMES[baseLower]
			end
		end

		if not spec then
			local lang
			if type(langOrPath) == "table" then
				lang = langOrPath
			elseif type(langOrPath) == "string" and langOrPath:find("%.", 1, true) then
				lang = languages.detect(langOrPath)
			else
				lang = languages.get(langOrPath)
			end
			spec = SETI_FILE_SPECS[lang.id] or {
				glyph = (lang.badge or "F"):sub(1, 2),
				rgb = lang.badgeColor or { 150, 150, 150 },
				boxed = true,
			}
		end

		local rgb = spec.rgb or { 150, 150, 150 }
		local col = Color3.fromRGB(rgb[1], rgb[2], rgb[3])

		local holder = P.frame(parent, {
			name = "SetiBadge",
			size = UDim2.fromOffset(18, 14),
			bg = spec.solid and col or (spec.boxed and col or nil),
			transparency = spec.solid and 0.08 or (spec.boxed and 0.84 or 1),
			radius = 3,
			border = spec.boxed and col or nil,
			borderWidth = spec.boxed and 1 or nil,
			zIndex = z,
		})

		local textCol = col
		if spec.solid then
			textCol = spec.darkText and Color3.fromRGB(24, 24, 24) or Color3.fromRGB(255, 255, 255)
		end

		P.label(holder, {
			name = "SetiGlyph",
			size = UDim2.fromScale(1, 1),
			text = spec.text or spec.glyph or "≡",
			mono = true,
			bold = true,
			textSize = 9,
			color = textCol,
			alignX = Enum.TextXAlignment.Center,
			zIndex = z + 1,
		})
		return holder
	end

	return M
end
end)()

-- ==========================================================================
-- ui/mobile_bar
-- ==========================================================================
__VSRBLX_MODULES["ui/mobile_bar"] = (function()
-- Acode-Inspired Mobile Quick-Keys Bar & Play-While-Coding Strip (`src/ui/mobile_bar.lua`):
-- Provides 1-tap touch access to programming symbols (`Tab`, `{`, `}`, `(`, `)`, `[`, `]`,
-- `"`, `'`, `=`, `.`, `:`, `,`, `;`, `_`, `+`, `-`, `<`, `>`), Undo/Redo, Play+Code split-peek,
-- and Run (`▶`) so mobile/Android players can code smoothly on touch screens.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local commands = env.require("runtime/command_catalog")

	local M = {}

	local KEYS = {
		{ id = "tab", label = "⇥ Tab", width = 50, insert = "\t" },
		{ id = "lbrace", label = "{", width = 32, insert = "{" },
		{ id = "rbrace", label = "}", width = 32, insert = "}" },
		{ id = "lparen", label = "(", width = 32, insert = "(" },
		{ id = "rparen", label = ")", width = 32, insert = ")" },
		{ id = "lbrack", label = "[", width = 32, insert = "[" },
		{ id = "rbrack", label = "]", width = 32, insert = "]" },
		{ id = "dquote", label = '"', width = 32, insert = '"' },
		{ id = "squote", label = "'", width = 32, insert = "'" },
		{ id = "eq", label = "=", width = 32, insert = "=" },
		{ id = "dot", label = ".", width = 30, insert = "." },
		{ id = "colon", label = ":", width = 30, insert = ":" },
		{ id = "comma", label = ",", width = 30, insert = "," },
		{ id = "semi", label = ";", width = 30, insert = ";" },
		{ id = "under", label = "_", width = 32, insert = "_" },
		{ id = "minus", label = "-", width = 32, insert = "-" },
		{ id = "plus", label = "+", width = 32, insert = "+" },
		{ id = "lt", label = "<", width = 32, insert = "<" },
		{ id = "gt", label = ">", width = 32, insert = ">" },
		{ id = "undo", label = "↶", width = 36, cmd = "edit.undo" },
		{ id = "redo", label = "↷", width = 36, cmd = "edit.redo" },
		{ id = "play", label = "🎮 Play+Code", width = 88, cmd = "mobile.togglePlayWhileCoding", accent = true },
		{ id = "run", label = "▶ Run", width = 56, cmd = "run.active", good = true },
	}

	function M.new(parent, onInsertSymbol)
		local height = 38
		local root = P.frame(parent, {
			name = "MobileQuickKeysBar",
			size = UDim2.new(1, 0, 0, height),
			bg = theme.color.sideBarHeader,
			visible = false,
			zIndex = 36,
		})
		local topRule = P.frame(root, {
			size = UDim2.new(1, 0, 0, 1),
			bg = theme.color.border,
			zIndex = 37,
		})

		local keyScroll = P.scroll(root, {
			name = "MobileQuickKeysScroll",
			size = UDim2.new(1, 0, 1, -1),
			pos = UDim2.fromOffset(0, 1),
			direction = Enum.ScrollingDirection.X,
			autoCanvas = Enum.AutomaticSize.X,
			barThickness = 2,
			zIndex = 37,
		})
		P.pad(keyScroll, 3, 6, 3, 6)
		P.list(keyScroll, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local keyBtns = {}
		for idx, spec in ipairs(KEYS) do
			local btnBg = theme.color.inputBg
			local txtCol = theme.color.tabActiveText
			if spec.accent then
				btnBg = theme.color.accent
				txtCol = Color3.fromRGB(255, 255, 255)
			elseif spec.good then
				btnBg = theme.color.good
				txtCol = Color3.fromRGB(20, 24, 20)
			end
			local btn = P.button(keyScroll, {
				name = "QuickKey_" .. spec.id,
				size = UDim2.fromOffset(spec.width, 30),
				bg = btnBg,
				hoverBg = theme.color.hover,
				color = txtCol,
				mono = (spec.insert ~= nil),
				bold = true,
				text = spec.label,
				textSize = 12,
				radius = 5,
				order = idx,
				zIndex = 38,
				onClick = function()
					if spec.insert and onInsertSymbol then
						onInsertSymbol(spec.insert)
					elseif spec.cmd then
						commands.run(spec.cmd)
					end
				end,
			})
			btn.BackgroundTransparency = 0
			keyBtns[#keyBtns + 1] = { btn = btn, spec = spec }
		end

		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.sideBarHeader
			topRule.BackgroundColor3 = theme.color.border
			for _, entry in ipairs(keyBtns) do
				if entry.spec.accent then
					entry.btn.BackgroundColor3 = theme.color.accent
				elseif entry.spec.good then
					entry.btn.BackgroundColor3 = theme.color.good
				else
					entry.btn.BackgroundColor3 = theme.color.inputBg
					entry.btn.TextColor3 = theme.color.tabActiveText
				end
			end
		end)

		return {
			root = root,
			height = height,
			setTransparency = function(bgTrans)
				root.BackgroundTransparency = math.min(0.45, bgTrans)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/overlay
-- ==========================================================================
__VSRBLX_MODULES["ui/overlay"] = (function()
-- VS Code popups, dropdown menus, input prompts, modals, and bottom-right toast notifications.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local util = env.require("runtime/util")

	local M = {
		layer = nil,
		toastStack = nil,
		activeMenu = nil,
		activeModal = nil,
	}

	function M.mount(parentScreen)
		if M.layer then
			pcall(function() M.layer:Destroy() end)
		end
		M.layer = P.frame(parentScreen, {
			name = "OverlayLayer",
			size = UDim2.fromScale(1, 1),
			zIndex = 200,
		})
		M.toastStack = P.frame(M.layer, {
			name = "ToastStack",
			size = UDim2.fromOffset(320, 260),
			pos = UDim2.new(1, -332, 1, -296),
			zIndex = 260,
		})
		P.list(M.toastStack, Enum.FillDirection.Vertical, 6, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Bottom)
	end

	function M.closeMenu()
		if M.activeMenu then
			pcall(function() M.activeMenu:Destroy() end)
			M.activeMenu = nil
		end
	end

	function M.closeModal()
		if M.activeModal then
			pcall(function() M.activeModal:Destroy() end)
			M.activeModal = nil
		end
	end

	local function clampModalDims(prefW, prefH)
		local vp = responsive.usableRect(6)
		local w = math.min(prefW or 480, math.max(260, vp.width - 16))
		local h = math.min(prefH or 320, math.max(150, vp.height - 16))
		return w, h, vp
	end

	function M.openModal(name, width, height)
		M.closeModal()
		local parentTarget = M.layer
		local clampedW, clampedH = clampModalDims(width or 480, height or 320)
		local backdrop = P.button(parentTarget, {
			name = "ModalBackdrop_" .. tostring(name or "Dialog"),
			size = UDim2.fromScale(1, 1),
			bg = Color3.fromRGB(0, 0, 0),
			transparency = 0.45,
			text = "",
			zIndex = 230,
			onClick = function() M.closeModal() end,
		})
		local card = P.frame(backdrop, {
			name = tostring(name or "ModalCard"),
			size = UDim2.fromOffset(clampedW, clampedH),
			pos = UDim2.new(0.5, 0, 0.48, 0),
			anchor = Vector2.new(0.5, 0.5),
			bg = theme.color.sideBar,
			radius = 6,
			border = theme.color.border,
			clip = true,
			active = true,
			zIndex = 231,
		})
		M.activeModal = backdrop
		return card, backdrop
	end

	function M.dropdown(x, y, items, width)
		M.closeMenu()
		if not M.layer then return end

		local vp = responsive.usableRect(4)
		local backdrop = P.button(M.layer, {
			name = "MenuBackdrop",
			size = UDim2.fromScale(1, 1),
			text = "",
			zIndex = 210,
			onClick = function() M.closeMenu() end,
		})
		backdrop.BackgroundTransparency = 1

		local menuW = math.min(width or 220, math.max(160, vp.width - 12))
		local rawH = 8
		for _, it in ipairs(items) do
			rawH = rawH + (it.separator and 7 or 24)
		end
		local menuH = math.min(rawH, math.max(120, vp.height - 16))
		local safeX = util.clamp(math.floor(x or 8), 4, math.max(4, vp.x + vp.width - menuW - 4))
		local safeY = util.clamp(math.floor(y or 32), 4, math.max(4, vp.y + vp.height - menuH - 4))

		local card = P.scroll(backdrop, {
			name = "DropdownCard",
			size = UDim2.fromOffset(menuW, menuH),
			pos = UDim2.fromOffset(safeX, safeY),
			bg = theme.color.dropdownBg,
			transparency = 0,
			barThickness = 4,
			zIndex = 215,
		})
		P.corner(card, 4)
		P.stroke(card, theme.color.border, 1)
		P.pad(card, 4, 4, 4, 4)
		P.list(card, Enum.FillDirection.Vertical, 0)

		for idx, item in ipairs(items) do
			if item.separator then
				local sepWrap = P.frame(card, {
					size = UDim2.new(1, 0, 0, 7),
					order = idx,
					zIndex = 216,
				})
				P.frame(sepWrap, {
					size = UDim2.new(1, -8, 0, 1),
					pos = UDim2.fromOffset(4, 3),
					bg = theme.color.border,
					zIndex = 217,
				})
			else
				local row = P.button(card, {
					name = "MenuItem_" .. tostring(idx),
					size = UDim2.new(1, 0, 0, 24),
					hoverBg = theme.color.listActive,
					text = "",
					radius = 3,
					order = idx,
					zIndex = 216,
					onClick = function()
						M.closeMenu()
						if item.onClick then item.onClick() end
					end,
				})
				P.label(row, {
					size = UDim2.new(1, -70, 1, 0),
					pos = UDim2.fromOffset(10, 0),
					text = item.label or "",
					color = theme.color.sideBarText,
					textSize = 12,
					zIndex = 217,
				})
				if item.shortcut and item.shortcut ~= "" then
					P.label(row, {
						size = UDim2.fromOffset(64, 24),
						pos = UDim2.new(1, -70, 0, 0),
						text = item.shortcut,
						color = theme.color.muted,
						textSize = 11,
						alignX = Enum.TextXAlignment.Right,
						zIndex = 217,
					})
				end
			end
		end

		M.activeMenu = backdrop
		return backdrop
	end

	function M.prompt(spec)
		M.closeModal()
		if not M.layer then return end

		local backdrop = P.button(M.layer, {
			name = "ModalBackdrop",
			size = UDim2.fromScale(1, 1),
			bg = Color3.fromRGB(0, 0, 0),
			transparency = 0.45,
			text = "",
			zIndex = 230,
			onClick = function() M.closeModal() end,
		})

		local promptW, promptH = clampModalDims(spec.width or 420, spec.height or 146)
		local boxCard = P.frame(backdrop, {
			name = "PromptModal",
			size = UDim2.fromOffset(promptW, promptH),
			pos = UDim2.new(0.5, 0, 0.42, 0),
			anchor = Vector2.new(0.5, 0.5),
			bg = theme.color.sideBar,
			radius = 6,
			border = theme.color.border,
			active = true,
			zIndex = 235,
		})
		P.pad(boxCard, 12, 14, 12, 14)

		P.label(boxCard, {
			size = UDim2.new(1, 0, 0, 20),
			text = spec.title or "Input",
			bold = true,
			textSize = 14,
			color = theme.color.tabActiveText,
			zIndex = 236,
		})

		if spec.subtitle then
			P.label(boxCard, {
				size = UDim2.new(1, 0, 0, 18),
				pos = UDim2.fromOffset(0, 22),
				text = spec.subtitle,
				textSize = 12,
				color = theme.color.muted,
				zIndex = 236,
			})
		end

		local inputWrap, field = P.input(boxCard, {
			name = "PromptField",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.fromOffset(0, 48),
			value = spec.default or "",
			placeholder = spec.placeholder or "",
			mono = spec.mono == true,
			zIndex = 236,
			onSubmit = function(val)
				M.closeModal()
				if spec.onConfirm then spec.onConfirm(val) end
			end,
		})
		inputWrap.Active = true

		local actions = P.frame(boxCard, {
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.new(0, 0, 1, -28),
			zIndex = 236,
		})
		P.list(actions, Enum.FillDirection.Horizontal, 8, Enum.HorizontalAlignment.Right)

		P.button(actions, {
			name = "CancelBtn",
			size = UDim2.fromOffset(74, 26),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "Cancel",
			radius = 4,
			order = 1,
			zIndex = 237,
			onClick = function() M.closeModal() end,
		})
		P.button(actions, {
			name = "ConfirmBtn",
			size = UDim2.fromOffset(92, 26),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = spec.confirmText or "Confirm",
			radius = 4,
			order = 2,
			zIndex = 237,
			onClick = function()
				local v = field.Text
				M.closeModal()
				if spec.onConfirm then spec.onConfirm(v) end
			end,
		})

		M.activeModal = backdrop
		task.defer(function()
			pcall(function() field:CaptureFocus() end)
		end)
		return backdrop, field
	end

	function M.confirm(spec)
		M.closeModal()
		if not M.layer then return end
		spec = spec or {}

		local backdrop = P.button(M.layer, {
			name = "ConfirmBackdrop",
			size = UDim2.fromScale(1, 1),
			bg = Color3.fromRGB(0, 0, 0),
			transparency = 0.45,
			text = "",
			zIndex = 230,
			onClick = function()
				M.closeModal()
				if spec.onCancel then spec.onCancel() end
			end,
		})

		local confW, confH = clampModalDims(spec.width or 430, spec.height or 152)
		local card = P.frame(backdrop, {
			name = "ConfirmModal",
			size = UDim2.fromOffset(confW, confH),
			pos = UDim2.new(0.5, 0, 0.44, 0),
			anchor = Vector2.new(0.5, 0.5),
			bg = theme.color.sideBar,
			radius = 6,
			border = theme.color.border,
			active = true,
			zIndex = 235,
		})
		P.pad(card, 14, 16, 14, 16)

		P.label(card, {
			name = "ConfirmTitle",
			size = UDim2.new(1, 0, 0, 22),
			text = spec.title or "Confirm Action",
			bold = true,
			textSize = 13,
			color = theme.color.tabActiveText,
			truncate = true,
			zIndex = 236,
		})

		P.label(card, {
			name = "ConfirmMessage",
			size = UDim2.new(1, 0, 0, 38),
			pos = UDim2.fromOffset(0, 26),
			text = spec.message or "",
			wrap = true,
			textSize = 12,
			color = theme.color.muted,
			alignY = Enum.TextYAlignment.Top,
			zIndex = 236,
		})

		local actions = P.frame(card, {
			name = "ConfirmActions",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.new(0, 0, 1, -28),
			zIndex = 236,
		})
		P.list(actions, Enum.FillDirection.Horizontal, 8, Enum.HorizontalAlignment.Right)

		P.button(actions, {
			name = "ConfirmCancelBtn",
			size = UDim2.fromOffset(74, 26),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = spec.cancelText or "Cancel",
			radius = 4,
			order = 1,
			zIndex = 237,
			onClick = function()
				M.closeModal()
				if spec.onCancel then spec.onCancel() end
			end,
		})

		if spec.secondaryText then
			P.button(actions, {
				name = "ConfirmSecondaryBtn",
				size = UDim2.fromOffset(92, 26),
				bg = theme.color.inputBg,
				hoverBg = theme.color.bad,
				text = spec.secondaryText,
				radius = 4,
				order = 2,
				zIndex = 237,
				onClick = function()
					M.closeModal()
					if spec.onSecondary then spec.onSecondary() end
				end,
			})
		end

		P.button(actions, {
			name = "ConfirmPrimaryBtn",
			size = UDim2.fromOffset(96, 26),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = spec.primaryText or "Save",
			radius = 4,
			order = 3,
			zIndex = 237,
			onClick = function()
				M.closeModal()
				if spec.onPrimary then spec.onPrimary() end
			end,
		})

		M.activeModal = backdrop
		return backdrop, card
	end

	function M.toast(message, kind, durationSec)
		if not M.toastStack then return end
		local stripeColor = theme.color.accent
		if kind == "good" then stripeColor = theme.color.good
		elseif kind == "warn" then stripeColor = theme.color.warn
		elseif kind == "bad" then stripeColor = theme.color.bad end

		local card = P.frame(M.toastStack, {
			name = "Toast",
			size = UDim2.fromOffset(310, 44),
			bg = theme.color.sideBar,
			radius = 4,
			border = theme.color.border,
			zIndex = 262,
		})
		P.frame(card, {
			size = UDim2.new(0, 4, 1, 0),
			bg = stripeColor,
			radius = 2,
			zIndex = 263,
		})
		P.label(card, {
			size = UDim2.new(1, -22, 1, -8),
			pos = UDim2.fromOffset(12, 4),
			text = tostring(message or ""),
			wrap = true,
			textSize = 12,
			color = theme.color.sideBarText,
			zIndex = 263,
		})

		task.delay(durationSec or 3.5, function()
			pcall(function() card:Destroy() end)
		end)
		return card
	end

	return M
end
end)()

