__VSRBLX_MODULES["ui/panels/explorer"] = (function()
-- VS Code Explorer Sidebar Viewlet:
-- Open Editors, Local Disk File Tree (`writefile`/`readfile`), and Live Roblox DataModel
-- Explorer (3D/GUI Eyedropper Picker, Copy Luau Path, Property Inspector & Script Decompiler).
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local icons = env.require("ui/icons")
	local explorerTreeMod = env.require("ui/code/explorer")
	local workspaceFs = env.require("runtime/workspace_fs")
	local codeStore = env.require("runtime/code_store")
	local clipboard = env.require("runtime/clipboard")
	local robloxExplorer = env.require("runtime/roblox_explorer")
	local commands = env.require("runtime/command_catalog")
	local decompiler = env.require("tools/decompiler")
	local fsSync = env.require("tools/fs_sync")
	local overlay = env.require("ui/overlay")

	local M = {}

	function M.new(parent)
		local root = P.frame(parent, {
			name = "ExplorerViewlet",
			size = UDim2.fromScale(1, 1),
			zIndex = 21,
		})

		local titleRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 30),
			zIndex = 22,
		})
		P.label(titleRow, {
			size = UDim2.new(1, -134, 1, 0),
			pos = UDim2.fromOffset(12, 0),
			text = "EXPLORER",
			bold = true,
			textSize = 11,
			color = theme.color.muted,
			zIndex = 23,
		})

		local toolRow = P.frame(titleRow, {
			size = UDim2.fromOffset(128, 26),
			pos = UDim2.new(1, -132, 0, 2),
			zIndex = 23,
		})
		P.list(toolRow, Enum.FillDirection.Horizontal, 2, Enum.HorizontalAlignment.Right, Enum.VerticalAlignment.Center)

		local fileTree = nil
		local toolBtns = {}

		local function makeToolBtn(name, iconName, order, onClick)
			local btn = P.button(toolRow, {
				name = name,
				size = UDim2.fromOffset(24, 22),
				text = "",
				radius = 3,
				order = order,
				zIndex = 24,
				onClick = onClick,
			})
			toolBtns[#toolBtns + 1] = { btn = btn, icon = iconName }
			return btn
		end

		local function redrawToolbarIcons()
			for _, spec in ipairs(toolBtns) do
				spec.btn:ClearAllChildren()
				P.corner(spec.btn, 3)
				local ic = icons.codicon(spec.btn, spec.icon, 15, theme.color.sideBarText, 25)
				ic.Position = UDim2.fromOffset(4, 3)
			end
		end

		makeToolBtn("NewFileBtn", "newFile", 1, function()
			if fileTree then fileTree.promptNewFile("") end
		end)
		makeToolBtn("NewFolderBtn", "newFolder", 2, function()
			if fileTree then fileTree.promptNewFolder("") end
		end)
		makeToolBtn("ReloadDiskBtn", "refresh", 3, function()
			fsSync.reloadFromDisk()
			overlay.toast("Synced with local disk", "good", 2)
		end)
		makeToolBtn("SaveAllBtn", "saveAll", 4, function()
			local n = codeStore.saveAll()
			overlay.toast(string.format("Saved %d file(s) to disk", n), "good", 2)
		end)
		P.button(toolRow, {
			name = "BundleProjectBtn",
			size = UDim2.fromOffset(24, 22),
			text = "📦",
			textSize = 12,
			radius = 3,
			order = 5,
			zIndex = 24,
			onClick = function()
				commands.run("workspace.bundle")
			end,
		})
		redrawToolbarIcons()

		local scroll = P.scroll(root, {
			name = "ExplorerScroll",
			size = UDim2.new(1, 0, 1, -30),
			pos = UDim2.fromOffset(0, 30),
			zIndex = 22,
		})
		P.list(scroll, Enum.FillDirection.Vertical, 2)

		-- Section 1: Open Editors
		local openExpanded = true
		local openHeader = P.button(scroll, {
			name = "OpenEditorsHeader",
			size = UDim2.new(1, 0, 0, 22),
			bg = theme.color.sideBarHeader,
			hoverBg = theme.color.hover,
			text = "",
			order = 1,
			zIndex = 23,
		})
		local openHeaderLbl = P.label(openHeader, {
			size = UDim2.new(1, -12, 1, 0),
			pos = UDim2.fromOffset(8, 0),
			text = "▾ OPEN EDITORS",
			bold = true,
			textSize = 11,
			color = theme.color.sideBarText,
			zIndex = 24,
		})

		local openList = P.frame(scroll, {
			name = "OpenEditorsList",
			size = UDim2.new(1, 0, 0, 0),
			order = 2,
			zIndex = 23,
		})
		openList.AutomaticSize = Enum.AutomaticSize.Y
		P.list(openList, Enum.FillDirection.Vertical, 1)

		-- Section 2: Local Disk Folder
		local wsHeader = P.frame(scroll, {
			size = UDim2.new(1, 0, 0, 22),
			bg = theme.color.sideBarHeader,
			order = 3,
			zIndex = 23,
		})
		local wsHeaderLbl = P.label(wsHeader, {
			size = UDim2.new(1, -12, 1, 0),
			pos = UDim2.fromOffset(8, 0),
			text = "▾ WORKSPACE: " .. workspaceFs.activeName:upper(),
			bold = true,
			textSize = 11,
			color = theme.color.sideBarText,
			truncate = true,
			zIndex = 24,
		})

		local treeWrap = P.frame(scroll, {
			size = UDim2.new(1, 0, 0, 0),
			order = 4,
			zIndex = 23,
		})
		treeWrap.AutomaticSize = Enum.AutomaticSize.Y
		fileTree = explorerTreeMod.new(treeWrap)

		-- Section 3: Roblox Game DataModel Explorer + Eyedropper
		local gameExpanded = false
		local gameHeader = P.frame(scroll, {
			size = UDim2.new(1, 0, 0, 22),
			bg = theme.color.sideBarHeader,
			order = 5,
			zIndex = 23,
		})
		local gameBtn = P.button(gameHeader, {
			name = "GameTreeToggle",
			size = UDim2.new(1, -58, 1, 0),
			hoverBg = theme.color.hover,
			alignX = Enum.TextXAlignment.Left,
			bold = true,
			textSize = 11,
			color = theme.color.sideBarText,
			text = "  ▸ ROBLOX DATAMODEL",
			zIndex = 24,
		})
		P.button(gameHeader, {
			name = "DataModelEyedropperBtn",
			size = UDim2.fromOffset(52, 18),
			pos = UDim2.new(1, -56, 0, 2),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = "🎯 Pick",
			textSize = 10,
			radius = 3,
			zIndex = 25,
			onClick = function()
				commands.run("roblox.pickInstance")
			end,
		})

		local gameContainer = P.frame(scroll, {
			size = UDim2.new(1, 0, 0, 0),
			visible = false,
			order = 6,
			zIndex = 23,
		})
		gameContainer.AutomaticSize = Enum.AutomaticSize.Y
		P.list(gameContainer, Enum.FillDirection.Vertical, 1)

		local function openInstanceInspector(inst)
			local props = robloxExplorer.inspectProperties(inst)
			local luauPath = robloxExplorer.luauPathOf(inst)
			local lines = {
				"-- Roblox Instance Inspector (Read-Only Snapshot)",
				"-- Luau Path: " .. luauPath,
				"",
				"local target = " .. luauPath,
				"local properties = {",
			}
			for _, kv in ipairs(props) do
				lines[#lines + 1] = string.format("\t[%q] = %q,", kv.key, kv.value)
			end
			lines[#lines + 1] = "}"
			local doc = codeStore.newUntitled(table.concat(lines, "\n"), "luau")
			doc.title = "Inspect: " .. tostring(inst.Name)
			codeStore.changed:fire({ reason = "inspect", id = doc.id })
		end

		local expandedInstances = {}
		local function renderGameTree()
			gameContainer:ClearAllChildren()
			if not gameExpanded then return end
			P.list(gameContainer, Enum.FillDirection.Vertical, 1)
			local ord = 0

			local function walkInst(inst, _labelName, depth)
				if depth > 5 or ord > 80 then return end
				for _, ch in ipairs(robloxExplorer.childrenOf(inst, 40)) do
					ord = ord + 1
					local row = P.frame(gameContainer, {
						size = UDim2.new(1, 0, 0, 21),
						order = ord,
						zIndex = 24,
					})
					local mainBtn = P.button(row, {
						size = UDim2.new(1, -42, 1, 0),
						hoverBg = theme.color.hover,
						alignX = Enum.TextXAlignment.Left,
						textSize = 11,
						color = ch.isScript and theme.color.accent or theme.color.sideBarText,
						text = string.rep("   ", depth) .. (ch.isScript and "📜 " or (ch.hasChildren and "▸ " or "  ")) .. ch.name .. " (" .. ch.className .. ")",
						zIndex = 25,
						onClick = function()
							if ch.isScript then
								decompiler.openInstanceScript(ch.instance, true)
								overlay.toast("Decompiled & saved " .. ch.name .. " to disk", "good", 2.5)
							elseif ch.hasChildren then
								expandedInstances[ch.instance] = not expandedInstances[ch.instance]
								renderGameTree()
							else
								openInstanceInspector(ch.instance)
							end
						end,
					})
					mainBtn.TextTruncate = Enum.TextTruncate.AtEnd

					-- Copy Luau Path (`📋`)
					P.button(row, {
						name = "CopyPath_" .. ch.name,
						size = UDim2.fromOffset(18, 18),
						pos = UDim2.new(1, -40, 0, 1),
						text = "📋",
						textSize = 10,
						radius = 2,
						zIndex = 26,
						onClick = function()
							local lp = robloxExplorer.luauPathOf(ch.instance)
							clipboard.copy(lp)
							overlay.toast("Copied Luau path: " .. lp, "good", 2.2)
						end,
					})

					-- Inspect Properties (`ℹ`)
					P.button(row, {
						name = "InspectInst_" .. ch.name,
						size = UDim2.fromOffset(18, 18),
						pos = UDim2.new(1, -20, 0, 1),
						text = "ℹ",
						textSize = 10,
						color = theme.color.accent,
						radius = 2,
						zIndex = 26,
						onClick = function()
							openInstanceInspector(ch.instance)
						end,
					})

					if expandedInstances[ch.instance] then
						walkInst(ch.instance, ch.name, depth + 1)
					end
				end
			end

			for _, rootSvc in ipairs(robloxExplorer.rootServices()) do
				ord = ord + 1
				local svcInst = rootSvc.instance
				P.button(gameContainer, {
					size = UDim2.new(1, 0, 0, 22),
					hoverBg = theme.color.hover,
					alignX = Enum.TextXAlignment.Left,
					bold = true,
					textSize = 11,
					color = theme.color.sideBarText,
					text = "  " .. (expandedInstances[svcInst] and "▾ " or "▸ ") .. rootSvc.name,
					order = ord,
					zIndex = 24,
					onClick = function()
						expandedInstances[svcInst] = not expandedInstances[svcInst]
						renderGameTree()
					end,
				})
				if expandedInstances[svcInst] then
					walkInst(svcInst, rootSvc.name, 2)
				end
			end
		end

		gameBtn.Activated:Connect(function()
			gameExpanded = not gameExpanded
			gameBtn.Text = gameExpanded and "  ▾ ROBLOX DATAMODEL" or "  ▸ ROBLOX DATAMODEL"
			gameContainer.Visible = gameExpanded
			renderGameTree()
		end)

		local function renderOpenEditors()
			openList:ClearAllChildren()
			openList.Visible = openExpanded
			local arrow = openExpanded and "▾" or "▸"
			openHeaderLbl.Text = string.format("%s OPEN EDITORS (%d)", arrow, #codeStore.tabs)
			if not openExpanded then return end

			P.list(openList, Enum.FillDirection.Vertical, 1)
			local activeDoc = codeStore.active()
			for idx, tab in ipairs(codeStore.tabs) do
				local isCur = activeDoc and activeDoc.id == tab.id
				local row = P.button(openList, {
					name = "OpenEditor_" .. tab.title,
					size = UDim2.new(1, 0, 0, 21),
					bg = isCur and theme.color.listActive or nil,
					hoverBg = theme.color.hover,
					text = "",
					order = idx,
					zIndex = 24,
					activeState = function() return isCur end,
					onClick = function() codeStore.activate(tab.id) end,
				})
				P.button(row, {
					name = "CloseOpenEditorBtn",
					size = UDim2.fromOffset(16, 16),
					pos = UDim2.fromOffset(6, 2),
					text = tab.dirty and "●" or "✕",
					textSize = tab.dirty and 10 or 9,
					color = tab.dirty and theme.color.tabActiveText or theme.color.muted,
					radius = 2,
					zIndex = 25,
					onClick = function() codeStore.requestClose(tab.id) end,
				})
				local badge = icons.fileBadge(row, tab.path ~= "" and tab.path or tab.langId, false, 25)
				badge.Position = UDim2.fromOffset(24, 3)
				P.label(row, {
					size = UDim2.new(1, -50, 1, 0),
					pos = UDim2.fromOffset(46, 0),
					text = tab.title,
					textSize = 12,
					color = isCur and theme.color.tabActiveText or theme.color.sideBarText,
					truncate = true,
					zIndex = 25,
				})
			end
		end

		openHeader.Activated:Connect(function()
			openExpanded = not openExpanded
			renderOpenEditors()
		end)

		codeStore.changed:connect(renderOpenEditors)
		workspaceFs.changed:connect(function()
			wsHeaderLbl.Text = "▾ WORKSPACE: " .. workspaceFs.activeName:upper()
		end)
		theme.changed:connect(function()
			openHeader.BackgroundColor3 = theme.color.sideBarHeader
			wsHeader.BackgroundColor3 = theme.color.sideBarHeader
			gameHeader.BackgroundColor3 = theme.color.sideBarHeader
			redrawToolbarIcons()
			renderOpenEditors()
			if gameExpanded then renderGameTree() end
		end)

		renderOpenEditors()
		return {
			root = root,
			fileTree = fileTree,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/extensions
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/extensions"] = (function()
-- VS Code Extensions, Locked 5-Template Community Extension Hub, Malware Scanner & Capabilities Viewlet (`Ctrl+Shift+X`).
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local icons = env.require("ui/icons")
	local caps = env.require("runtime/caps")
	local languages = env.require("runtime/languages")
	local extensionHub = env.require("runtime/extension_hub")
	local clipboard = env.require("runtime/clipboard")
	local codeStore = env.require("runtime/code_store")
	local commands = env.require("runtime/command_catalog")
	local util = env.require("runtime/util")
	local overlay = env.require("ui/overlay")

	local M = {}

	function M.new(parent)
		local activeSubTab = "hub" -- `"hub"` | `"scanner"` | `"system"`
		local scannerText = util.jsonEncode(extensionHub.STARTER_CATALOG[1]) or "{}"
		local lastScanResult = extensionHub.scanSubmission(scannerText)

		local root = P.frame(parent, {
			name = "ExtensionsViewlet",
			size = UDim2.fromScale(1, 1),
			visible = false,
			zIndex = 21,
		})
		P.pad(root, 6, 8, 6, 8)

		P.label(root, {
			size = UDim2.new(1, 0, 0, 20),
			text = "EXTENSIONS & SECURITY HUB",
			bold = true,
			textSize = 11,
			color = theme.color.muted,
			zIndex = 22,
		})

		local tabStrip = P.frame(root, {
			name = "ExtensionsSubTabs",
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 22),
			zIndex = 22,
		})
		P.list(tabStrip, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left)

		local scroll = P.scroll(root, {
			name = "ExtensionsScroll",
			size = UDim2.new(1, 0, 1, -54),
			pos = UDim2.fromOffset(0, 52),
			zIndex = 22,
		})
		P.list(scroll, Enum.FillDirection.Vertical, 5)

		local tabButtons = {}
		local renderView

		local SUB_TABS = {
			{ id = "hub", label = "📦 Hub" },
			{ id = "scanner", label = "🛡 Scanner" },
			{ id = "system", label = "⚙ Host & Themes" },
		}
		for idx, st in ipairs(SUB_TABS) do
			local b = P.button(tabStrip, {
				name = "ExtTab_" .. st.id,
				size = UDim2.fromOffset(#st.label * 6 + 14, 24),
				bg = (st.id == activeSubTab) and theme.color.accent or theme.color.inputBg,
				hoverBg = theme.color.hover,
				color = (st.id == activeSubTab) and Color3.fromRGB(255, 255, 255) or theme.color.sideBarText,
				bold = true,
				text = st.label,
				textSize = 11,
				radius = 4,
				order = idx,
				zIndex = 23,
				onClick = function()
					activeSubTab = st.id
					renderView()
				end,
			})
			b.BackgroundTransparency = 0
			tabButtons[st.id] = b
		end

		local function renderExtensionCard(ord, item)
			local scan = item.scan or extensionHub.scanSubmission(item.manifest or {})
			local manifest = scan.manifest or item.manifest or {}
			local extId = tostring(manifest.id or ("issue-" .. tostring(item.issueNumber or ord)))
			local tmplInfo = extensionHub.ALLOWED_TEMPLATES[tostring(manifest.template or "")]
			local isInst = scan.ok and extensionHub.isInstalled(extId)

			local card = P.frame(scroll, {
				name = "ExtCard_" .. extId,
				size = UDim2.new(1, 0, 0, 86),
				bg = theme.color.inputBg,
				radius = 5,
				border = scan.ok and theme.color.border or theme.color.bad,
				order = ord,
				zIndex = 23,
			})
			P.pad(card, 6, 8, 6, 8)

			P.label(card, {
				size = UDim2.new(1, -78, 0, 16),
				bold = true,
				textSize = 12,
				color = theme.color.tabActiveText,
				text = tostring(manifest.name or item.title or extId),
				truncate = true,
				zIndex = 24,
			})

			-- Security Verdict Badge (`🛡 CLEAN` vs `⛔ BLOCKED`)
			P.label(card, {
				name = "ExtScanBadge_" .. extId,
				size = UDim2.fromOffset(74, 16),
				pos = UDim2.new(1, -74, 0, 0),
				bold = true,
				mono = true,
				textSize = 10,
				alignX = Enum.TextXAlignment.Right,
				color = scan.ok and theme.color.good or theme.color.bad,
				text = scan.ok and "🛡 CLEAN" or "⛔ BLOCKED",
				zIndex = 24,
			})

			local metaLine = string.format(
				"%s  ·  v%s  ·  @%s%s",
				tmplInfo and tmplInfo.badge or "⛔ INVALID",
				tostring(manifest.version or "0.0.0"),
				tostring(manifest.author or item.author or "community"),
				item.issueNumber and (" (#" .. tostring(item.issueNumber) .. ")") or ""
			)
			P.label(card, {
				size = UDim2.new(1, 0, 0, 14),
				pos = UDim2.fromOffset(0, 17),
				mono = true,
				textSize = 10,
				color = theme.color.accent,
				text = metaLine,
				truncate = true,
				zIndex = 24,
			})

			local summaryStr = scan.ok
				and tostring(manifest.summary or "")
				or ("Blocked: " .. tostring((scan.findings and scan.findings[1]) or "Failed template/malware verification"))
			P.label(card, {
				size = UDim2.new(1, 0, 0, 18),
				pos = UDim2.fromOffset(0, 32),
				textSize = 10,
				color = scan.ok and theme.color.muted or theme.color.bad,
				text = summaryStr,
				truncate = true,
				zIndex = 24,
			})

			local actions = P.frame(card, {
				size = UDim2.new(1, 0, 0, 22),
				pos = UDim2.new(0, 0, 1, -22),
				zIndex = 24,
			})
			P.list(actions, Enum.FillDirection.Horizontal, 6, Enum.HorizontalAlignment.Left)

			if scan.ok then
				local installBtn = P.button(actions, {
					name = (isInst and "ExtUninstallBtn_" or "ExtInstallBtn_") .. extId,
					size = UDim2.fromOffset(74, 20),
					bg = isInst and theme.color.hover or theme.color.accent,
					hoverBg = isInst and theme.color.bad or theme.color.accentHover,
					color = Color3.fromRGB(255, 255, 255),
					bold = true,
					text = isInst and "Uninstall" or "Install",
					textSize = 10,
					radius = 3,
					order = 1,
					zIndex = 25,
					onClick = function()
						if isInst then
							extensionHub.uninstall(extId)
							overlay.toast("Uninstalled " .. tostring(manifest.name), "info", 2)
						else
							local okI, errOrMan = extensionHub.install(manifest)
							if okI then
								overlay.toast("🛡 Verified & installed: " .. tostring(manifest.name), "good", 2.4)
								if manifest.template == "theme-pack" then
									local tid = "ext_" .. extId:gsub("[^%w_]", "_")
									theme.apply(tid)
								end
							else
								overlay.toast(tostring(errOrMan), "bad", 3)
							end
						end
					end,
				})
				installBtn.BackgroundTransparency = 0
			end

			local inspectBtn = P.button(actions, {
				name = "ExtInspectBtn_" .. extId,
				size = UDim2.fromOffset(66, 20),
				bg = theme.color.sideBar,
				hoverBg = theme.color.hover,
				text = "Inspect",
				textSize = 10,
				radius = 3,
				order = 2,
				zIndex = 25,
				onClick = function()
					local body = util.jsonEncode(manifest) or "{}"
					codeStore.openVirtualTab("ext_" .. extId, extId .. ".json", body, "json", true)
				end,
			})
			inspectBtn.BackgroundTransparency = 0
		end

		renderView = function()
			for tid, btn in pairs(tabButtons) do
				local on = (tid == activeSubTab)
				btn.BackgroundColor3 = on and theme.color.accent or theme.color.inputBg
				btn.TextColor3 = on and Color3.fromRGB(255, 255, 255) or theme.color.sideBarText
			end

			scroll:ClearAllChildren()
			P.list(scroll, Enum.FillDirection.Vertical, 5)
			local ord = 0

			local function addSection(title)
				ord = ord + 1
				P.label(scroll, {
					size = UDim2.new(1, 0, 0, 20),
					bold = true,
					textSize = 11,
					color = theme.color.tabActiveText,
					text = "▾ " .. title,
					order = ord,
					zIndex = 23,
				})
			end

			if activeSubTab == "hub" then
				-- Sync Header Banner
				ord = ord + 1
				local syncCard = P.frame(scroll, {
					name = "HubSyncBanner",
					size = UDim2.new(1, 0, 0, 56),
					bg = theme.color.sideBarHeader,
					radius = 5,
					border = theme.color.border,
					order = ord,
					zIndex = 23,
				})
				P.pad(syncCard, 6, 8, 6, 8)
				P.label(syncCard, {
					size = UDim2.new(1, 0, 0, 18),
					text = "🛡 Locked 5-Template GitHub Issues Hub",
					bold = true,
					textSize = 11,
					color = theme.color.good,
					truncate = true,
					zIndex = 24,
				})
				local syncBtn = P.button(syncCard, {
					name = "SyncGitHubExtensionsBtn",
					size = UDim2.new(1, 0, 0, 22),
					pos = UDim2.fromOffset(0, 22),
					bg = theme.color.accent,
					hoverBg = theme.color.accentHover,
					color = Color3.fromRGB(255, 255, 255),
					bold = true,
					text = "↻ Sync Community Extensions (GitHub Issues)",
					textSize = 10,
					radius = 4,
					zIndex = 24,
					onClick = function()
						local list, err = extensionHub.syncFromGitHub()
						if not list then
							overlay.toast("Hub sync failed: " .. tostring(err), "bad", 3)
						else
							overlay.toast(string.format("Scanned %d GitHub Issue extension(s)", #list), "good", 2.4)
						end
					end,
				})
				syncBtn.BackgroundTransparency = 0

				-- Installed Quick-Tools Bar (`toolbar-tool` extensions)
				local activeTools = extensionHub.listActiveToolbarTools()
				if #activeTools > 0 then
					addSection(string.format("ACTIVE QUICK-TOOLS (%d)", #activeTools))
					for _, tl in ipairs(activeTools) do
						ord = ord + 1
						local tb = P.button(scroll, {
							name = "RunExtTool_" .. tl.commandId,
							size = UDim2.new(1, 0, 0, 24),
							bg = theme.color.inputBg,
							hoverBg = theme.color.accent,
							alignX = Enum.TextXAlignment.Left,
							text = "  🛠 " .. tl.label .. "  (" .. tl.extName .. ")",
							textSize = 11,
							radius = 4,
							order = ord,
							zIndex = 23,
							onClick = function()
								commands.run(tl.commandId)
								overlay.toast("Applied tool: " .. tl.label, "good", 1.8)
							end,
						})
						tb.BackgroundTransparency = 0
					end
				end

				-- Live Synced GitHub Issues Extensions
				if #extensionHub.remoteCatalog > 0 then
					addSection(string.format("GITHUB ISSUES COMMUNITY FEED (%d)", #extensionHub.remoteCatalog))
					for _, rem in ipairs(extensionHub.remoteCatalog) do
						ord = ord + 1
						renderExtensionCard(ord, rem)
					end
				end

				-- Verified Official 5-Template Starter Packs
				addSection("OFFICIAL VERIFIED 5-TEMPLATE PACKS (5)")
				for _, starter in ipairs(extensionHub.STARTER_CATALOG) do
					ord = ord + 1
					renderExtensionCard(ord, {
						manifest = starter,
						scan = extensionHub.scanSubmission(starter),
						author = starter.author,
					})
				end

			elseif activeSubTab == "scanner" then
				addSection("GENERATE ALLOWED TEMPLATE MANIFEST")
				ord = ord + 1
				local genRow = P.frame(scroll, {
					size = UDim2.new(1, 0, 0, 52),
					zIndex = 23,
					order = ord,
				})
				P.list(genRow, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left)
				for idx, tmplId in ipairs(extensionHub.TEMPLATE_LIST) do
					if idx <= 3 then
						local gb = P.button(genRow, {
							name = "GenTemplate_" .. tmplId,
							size = UDim2.fromOffset(72, 22),
							bg = theme.color.inputBg,
							hoverBg = theme.color.hover,
							text = tmplId:gsub("%-pack$", ""):gsub("%-preset$", ""),
							mono = true,
							textSize = 10,
							radius = 3,
							order = idx,
							zIndex = 24,
							onClick = function()
								local sample = extensionHub.generateSampleManifest(tmplId)
								scannerText = util.jsonEncode(sample) or "{}"
								lastScanResult = extensionHub.scanSubmission(scannerText)
								renderView()
							end,
						})
						gb.BackgroundTransparency = 0
					end
				end
				ord = ord + 1
				local genRow2 = P.frame(scroll, {
					size = UDim2.new(1, 0, 0, 24),
					pos = UDim2.fromOffset(0, 0),
					zIndex = 23,
					order = ord,
				})
				P.list(genRow2, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left)
				for idx = 4, #extensionHub.TEMPLATE_LIST do
					local tmplId = extensionHub.TEMPLATE_LIST[idx]
					local gb = P.button(genRow2, {
						name = "GenTemplate_" .. tmplId,
						size = UDim2.fromOffset(96, 22),
						bg = theme.color.inputBg,
						hoverBg = theme.color.hover,
						text = tmplId,
						mono = true,
						textSize = 10,
						radius = 3,
						order = idx,
						zIndex = 24,
						onClick = function()
							local sample = extensionHub.generateSampleManifest(tmplId)
							scannerText = util.jsonEncode(sample) or "{}"
							lastScanResult = extensionHub.scanSubmission(scannerText)
							renderView()
						end,
					})
					gb.BackgroundTransparency = 0
				end

				addSection("CLIENT MALWARE & SCHEMA SCANNER")
				ord = ord + 1
				local boxWrap = P.frame(scroll, {
					size = UDim2.new(1, 0, 0, 96),
					bg = theme.color.inputBg,
					radius = 4,
					border = theme.color.border,
					order = ord,
					zIndex = 23,
				})
				local payloadBox = Instance.new("TextBox", boxWrap)
				payloadBox.Name = "ScannerPayloadInput"
				payloadBox.Size = UDim2.new(1, -10, 1, -8)
				payloadBox.Position = UDim2.fromOffset(5, 4)
				payloadBox.BackgroundTransparency = 1
				payloadBox.BorderSizePixel = 0
				payloadBox.MultiLine = true
				payloadBox.ClearTextOnFocus = false
				payloadBox.TextWrapped = true
				payloadBox.Font = theme.font.mono
				payloadBox.TextSize = 10
				payloadBox.TextColor3 = theme.color.editorText
				payloadBox.TextXAlignment = Enum.TextXAlignment.Left
				payloadBox.TextYAlignment = Enum.TextYAlignment.Top
				payloadBox.Text = scannerText
				payloadBox.ZIndex = 24

				payloadBox:GetPropertyChangedSignal("Text"):Connect(function()
					scannerText = payloadBox.Text
				end)

				ord = ord + 1
				local btnBar = P.frame(scroll, {
					size = UDim2.new(1, 0, 0, 24),
					order = ord,
					zIndex = 23,
				})
				P.list(btnBar, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left)

				local runScanBtn = P.button(btnBar, {
					name = "RunMalwareScanBtn",
					size = UDim2.fromOffset(66, 22),
					bg = theme.color.accent,
					hoverBg = theme.color.accentHover,
					color = Color3.fromRGB(255, 255, 255),
					bold = true,
					text = "🛡 Scan",
					textSize = 10,
					radius = 3,
					order = 1,
					zIndex = 24,
					onClick = function()
						lastScanResult = extensionHub.scanSubmission(scannerText)
						renderView()
					end,
				})
				runScanBtn.BackgroundTransparency = 0

				local instCustomBtn = P.button(btnBar, {
					name = "InstallScannedPayloadBtn",
					size = UDim2.fromOffset(68, 22),
					bg = theme.color.good,
					hoverBg = theme.color.accent,
					color = Color3.fromRGB(16, 24, 20),
					bold = true,
					text = "Install",
					textSize = 10,
					radius = 3,
					order = 2,
					zIndex = 24,
					onClick = function()
						local okI, msg = extensionHub.install(scannerText)
						lastScanResult = extensionHub.scanSubmission(scannerText)
						if okI then
							overlay.toast("🛡 Installed verified extension!", "good", 2.4)
						else
							overlay.toast(tostring(msg), "bad", 3.2)
						end
						renderView()
					end,
				})
				instCustomBtn.BackgroundTransparency = 0

				local copyIssueBtn = P.button(btnBar, {
					name = "CopyGitHubIssueMarkdownBtn",
					size = UDim2.fromOffset(82, 22),
					bg = theme.color.inputBg,
					hoverBg = theme.color.hover,
					text = "Copy Issue MD",
					textSize = 10,
					radius = 3,
					order = 3,
					zIndex = 24,
					onClick = function()
						local sc = extensionHub.scanSubmission(scannerText)
						if not sc.ok or not sc.manifest then
							overlay.toast("Fix scanner errors before copying Issue Markdown", "warn", 2.5)
							return
						end
						local md = extensionHub.generateIssueMarkdown(sc.manifest)
						clipboard.copy(md)
						overlay.toast("Copied GitHub Issue Form Markdown to clipboard!", "good", 2.5)
					end,
				})
				copyIssueBtn.BackgroundTransparency = 0

				-- Scan Verdict Card
				ord = ord + 1
				local resCard = P.frame(scroll, {
					name = "MalwareScanVerdictCard",
					size = UDim2.new(1, 0, 0, 74),
					bg = theme.color.sideBarHeader,
					radius = 4,
					border = lastScanResult.ok and theme.color.good or theme.color.bad,
					order = ord,
					zIndex = 23,
				})
				P.pad(resCard, 6, 8, 6, 8)
				P.label(resCard, {
					name = "MalwareScanVerdictTitle",
					size = UDim2.new(1, 0, 0, 16),
					bold = true,
					textSize = 11,
					color = lastScanResult.ok and theme.color.good or theme.color.bad,
					text = lastScanResult.ok
						and ("🛡 VERIFIED CLEAN — Template `" .. tostring(lastScanResult.manifest.template) .. "`")
						or string.format("⛔ BLOCKED (%d security/schema violation(s))", #(lastScanResult.findings or {})),
					truncate = true,
					zIndex = 24,
				})
				P.label(resCard, {
					name = "MalwareScanVerdictDetail",
					size = UDim2.new(1, 0, 0, 44),
					pos = UDim2.fromOffset(0, 18),
					wrap = true,
					textSize = 10,
					alignY = Enum.TextYAlignment.Top,
					color = theme.color.sideBarText,
					text = lastScanResult.ok
						and "Zero executable code, webhooks, obfuscators, or disallowed fields detected."
						or table.concat(lastScanResult.findings or {}, " | "),
					zIndex = 24,
				})

			else
				-- 1. Executor Capabilities
				addSection("EXECUTOR HOST CAPABILITIES (" .. caps.executor .. ")")
				local capRows = {
					{ name = "Local Disk File Read/Write", detail = "writefile / readfile", ok = caps.has("fs") },
					{ name = "Local Disk Folder Tree", detail = "listfiles / makefolder", ok = caps.has("fsTree") },
					{ name = "GitHub HTTP Request API", detail = tostring(caps.requestName or caps.http), ok = caps.has("httpRequest") or caps.has("httpGet") },
					{ name = "Luau Compiler & Runner", detail = "loadstring", ok = caps.has("loadstring") },
					{ name = "System Clipboard", detail = "setclipboard", ok = caps.has("clipboard") },
					{ name = "Instance Script Decompiler", detail = "decompile", ok = caps.has("decompile") },
				}
				for _, c in ipairs(capRows) do
					ord = ord + 1
					local card = P.frame(scroll, {
						size = UDim2.new(1, 0, 0, 34),
						bg = theme.color.inputBg,
						radius = 4,
						order = ord,
						zIndex = 23,
					})
					P.label(card, {
						size = UDim2.new(1, -66, 0, 18),
						pos = UDim2.fromOffset(8, 2),
						bold = true,
						textSize = 11,
						color = theme.color.tabActiveText,
						text = c.name,
						truncate = true,
						zIndex = 24,
					})
					P.label(card, {
						size = UDim2.new(1, -66, 0, 14),
						pos = UDim2.fromOffset(8, 18),
						mono = true,
						textSize = 10,
						color = theme.color.muted,
						text = c.detail,
						zIndex = 24,
					})
					P.label(card, {
						size = UDim2.fromOffset(56, 34),
						pos = UDim2.new(1, -60, 0, 0),
						bold = true,
						textSize = 10,
						alignX = Enum.TextXAlignment.Right,
						color = c.ok and theme.color.good or theme.color.warn,
						text = c.ok and "ACTIVE" or "FALLBACK",
						zIndex = 24,
					})
				end

				-- 2. Installed Color Themes (Built-in + Community Theme Packs!)
				local allThemes = theme.list()
				addSection(string.format("INSTALLED COLOR THEMES (%d)", #allThemes))
				for _, t in ipairs(allThemes) do
					ord = ord + 1
					local themeId = t.id
					P.button(scroll, {
						name = "ApplyThemeBtn_" .. themeId,
						size = UDim2.new(1, 0, 0, 26),
						bg = theme.color.inputBg,
						hoverBg = theme.color.listActive,
						alignX = Enum.TextXAlignment.Left,
						textSize = 12,
						color = theme.color.sideBarText,
						text = "  🎨  " .. t.label,
						radius = 4,
						order = ord,
						zIndex = 23,
						onClick = function()
							theme.apply(themeId)
							overlay.toast("Applied theme: " .. t.label, "good", 2)
						end,
					})
				end

				-- 3. Built-in Multi-Language Support
				addSection(string.format("BUILT-IN LANGUAGE MODES (%d)", #languages.list))
				for _, lang in ipairs(languages.list) do
					ord = ord + 1
					local row = P.frame(scroll, {
						size = UDim2.new(1, 0, 0, 26),
						bg = theme.color.inputBg,
						radius = 4,
						order = ord,
						zIndex = 23,
					})
					local b = icons.fileBadge(row, lang, false, 24)
					b.Position = UDim2.fromOffset(6, 6)
					local extLabel = (#(lang.extensions or {}) > 0) and ("  (." .. table.concat(lang.extensions, ", .") .. ")") or ""
					P.label(row, {
						size = UDim2.new(1, -44, 1, 0),
						pos = UDim2.fromOffset(36, 0),
						textSize = 11,
						color = theme.color.sideBarText,
						text = lang.name .. extLabel,
						truncate = true,
						zIndex = 24,
					})
				end
			end
		end

		extensionHub.changed:connect(renderView)
		theme.changed:connect(renderView)
		renderView()

		return {
			root = root,
			refresh = renderView,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/github_connect
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/github_connect"] = (function()
-- Modal Dialog for GitHub Repository Cloning, Token Authentication, & Repo Browser.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local cryptoVault = env.require("runtime/crypto_vault")
	local commands = env.require("runtime/command_catalog")
	local github = env.require("net/github")
	local githubSync = env.require("tools/github_sync")

	local M = {}

	function M.openModal()
		local card = overlay.openModal("GitHubCloneModal", 520, 390)
		P.pad(card, 14, 16, 14, 16)

		P.label(card, {
			size = UDim2.new(1, -34, 0, 22),
			text = "GitHub Repository Sync & Executor HTTP Loader",
			bold = true,
			textSize = 14,
			color = theme.color.tabActiveText,
			zIndex = 232,
		})
		P.button(card, {
			size = UDim2.fromOffset(26, 24),
			pos = UDim2.new(1, -26, 0, 0),
			text = "✕",
			radius = 4,
			zIndex = 232,
			onClick = function() overlay.closeModal() end,
		})

		P.label(card, {
			size = UDim2.new(1, 0, 0, 18),
			pos = UDim2.fromOffset(0, 24),
			text = "HTTP Transport: " .. tostring(caps.requestName or caps.http) .. "   |   Files persist via writefile / readfile",
			textSize = 11,
			color = theme.color.muted,
			zIndex = 232,
		})

		P.label(card, {
			size = UDim2.new(1, 0, 0, 18),
			pos = UDim2.fromOffset(0, 50),
			text = "Clone Repository (owner/repo, owner/repo@branch, or https://github.com/...)",
			textSize = 12,
			color = theme.color.sideBarText,
			zIndex = 232,
		})
		local _, repoBox = P.input(card, {
			name = "CloneRepoInput",
			size = UDim2.new(1, -110, 0, 28),
			pos = UDim2.fromOffset(0, 70),
			mono = true,
			value = config.get("github.activeRepo", ""),
			placeholder = "TheStrongestOfTomorrow/VS-RBLX",
			zIndex = 232,
		})
		local cloneBtn = P.button(card, {
			name = "RunCloneBtn",
			size = UDim2.fromOffset(102, 28),
			pos = UDim2.new(1, -102, 0, 70),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = "Clone to Disk",
			radius = 4,
			zIndex = 232,
		})

		P.label(card, {
			size = UDim2.new(1, -110, 0, 18),
			pos = UDim2.fromOffset(0, 108),
			text = cryptoVault.isEncrypted()
				and (cryptoVault.isUnlocked() and "🔓 Vault Encrypted PAT (Session Unlocked)" or "🔒 Vault Locked — Unlock to use saved PAT")
				or "Personal Access Token (optional for public; encrypt via 🔐 Vault)",
			textSize = 11,
			color = cryptoVault.isEncrypted() and (cryptoVault.isUnlocked() and theme.color.good or theme.color.warn) or theme.color.sideBarText,
			truncate = true,
			zIndex = 232,
		})
		P.button(card, {
			name = "GitHubOpenVaultBtn",
			size = UDim2.fromOffset(102, 18),
			pos = UDim2.new(1, -102, 0, 108),
			bg = theme.color.inputBg,
			hoverBg = theme.color.accent,
			text = cryptoVault.isEncrypted() and (cryptoVault.isUnlocked() and "🔓 Vault Settings" or "🔒 Unlock Vault") or "🔐 Encrypt PAT",
			textSize = 10,
			radius = 4,
			zIndex = 232,
			onClick = function()
				commands.run("vault.open")
			end,
		})
		local _, patBox = P.input(card, {
			name = "PatInput",
			size = UDim2.new(1, -188, 0, 28),
			pos = UDim2.fromOffset(0, 128),
			mono = true,
			value = github.token(),
			placeholder = "ghp_xxxxxxxxxxxxxxxxxxxx",
			zIndex = 232,
		})
		local verifyBtn = P.button(card, {
			name = "VerifyPatBtn",
			size = UDim2.fromOffset(88, 28),
			pos = UDim2.new(1, -180, 0, 128),
			bg = theme.color.inputBg,
			text = "Save & Verify",
			textSize = 11,
			radius = 4,
			zIndex = 232,
		})
		local listReposBtn = P.button(card, {
			name = "ListUserReposBtn",
			size = UDim2.fromOffset(86, 28),
			pos = UDim2.new(1, -86, 0, 128),
			bg = theme.color.inputBg,
			text = "My Repos",
			textSize = 11,
			radius = 4,
			zIndex = 232,
		})

		P.label(card, {
			size = UDim2.new(1, 0, 0, 18),
			pos = UDim2.fromOffset(0, 166),
			text = "Import Raw URL into Current Workspace",
			textSize = 11,
			color = theme.color.sideBarText,
			zIndex = 232,
		})
		local _, rawUrlBox = P.input(card, {
			name = "RawUrlInput",
			size = UDim2.new(1, -110, 0, 26),
			pos = UDim2.fromOffset(0, 186),
			mono = true,
			placeholder = "https://raw.githubusercontent.com/...",
			zIndex = 232,
		})
		local importUrlBtn = P.button(card, {
			name = "ImportRawUrlBtn",
			size = UDim2.fromOffset(102, 26),
			pos = UDim2.new(1, -102, 0, 186),
			bg = theme.color.inputBg,
			text = "Fetch File",
			textSize = 11,
			radius = 4,
			zIndex = 232,
		})

		local feedbackLbl = P.label(card, {
			size = UDim2.new(1, 0, 0, 20),
			pos = UDim2.fromOffset(0, 218),
			text = "Ready.",
			mono = true,
			textSize = 11,
			color = theme.color.accent,
			zIndex = 232,
		})

		local repoListScroll = P.scroll(card, {
			name = "UserRepoBrowser",
			size = UDim2.new(1, 0, 0, 118),
			pos = UDim2.fromOffset(0, 242),
			bg = theme.color.editor,
			zIndex = 232,
		})
		P.pad(repoListScroll, 4, 6, 4, 6)
		P.list(repoListScroll, Enum.FillDirection.Vertical, 2)

		local function executeClone(spec)
			if spec == "" then
				feedbackLbl.Text = "Enter owner/repo first."
				return
			end
			if patBox.Text ~= github.token() then
				github.setToken(patBox.Text)
			end
			feedbackLbl.Text = "Cloning " .. spec .. " via Executor HTTP..."
			task.spawn(function()
				local snap, err = githubSync.cloneRepo(spec)
				if snap then
					overlay.toast(string.format("Cloned %s (%d files written to disk)", snap.fullName, snap.fetched), "good", 4)
					overlay.closeModal()
				else
					feedbackLbl.Text = "Clone failed: " .. tostring(err)
					overlay.toast("Clone failed: " .. tostring(err), "bad", 4)
				end
			end)
		end

		cloneBtn.Activated:Connect(function() executeClone(repoBox.Text) end)

		verifyBtn.Activated:Connect(function()
			feedbackLbl.Text = "Verifying GitHub token..."
			task.spawn(function()
				local user, err = githubSync.authenticate(patBox.Text)
				if user then
					feedbackLbl.Text = "Authenticated as @" .. tostring(user.login)
					overlay.toast("GitHub authenticated: @" .. tostring(user.login), "good", 3)
				else
					feedbackLbl.Text = "Auth error: " .. tostring(err)
				end
			end)
		end)

		listReposBtn.Activated:Connect(function()
			if patBox.Text ~= "" then github.setToken(patBox.Text) end
			feedbackLbl.Text = "Loading repositories..."
			task.spawn(function()
				local repos, err = github.listUserRepos()
				repoListScroll:ClearAllChildren()
				P.pad(repoListScroll, 4, 6, 4, 6)
				P.list(repoListScroll, Enum.FillDirection.Vertical, 2)
				if not repos then
					feedbackLbl.Text = "Error: " .. tostring(err)
					return
				end
				feedbackLbl.Text = string.format("Loaded %d repositories — click any to clone:", #repos)
				for idx, r in ipairs(repos) do
					local fullName = tostring(r.fullName or "")
					P.button(repoListScroll, {
						size = UDim2.new(1, 0, 0, 22),
						hoverBg = theme.color.listActive,
						alignX = Enum.TextXAlignment.Left,
						mono = true,
						textSize = 11,
						color = theme.color.tabActiveText,
						text = string.format("  %s %s  [%s]", r.private and "🔒" or "🌐", fullName, tostring(r.defaultBranch or "main")),
						order = idx,
						zIndex = 233,
						onClick = function()
							repoBox.Text = fullName
							executeClone(fullName)
						end,
					})
				end
			end)
		end)

		importUrlBtn.Activated:Connect(function()
			local target = rawUrlBox.Text
			if target == "" then return end
			feedbackLbl.Text = "Fetching " .. target .. " ..."
			task.spawn(function()
				local doc, err = githubSync.importUrl(target)
				if doc then
					overlay.toast("Imported " .. doc.title .. " into workspace!", "good", 3)
					overlay.closeModal()
				else
					feedbackLbl.Text = "Import failed: " .. tostring(err)
				end
			end)
		end)
	end

	return M
end
end)()

