-- ui/panels/scm
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/scm"] = (function()
-- VS Code Source Control (`Ctrl+Shift+G`):
-- Clone/Pull/Commit/Push via Executor HTTP, Stage/Unstage/Discard changes,
-- 1-click Side-by-Side Diff Viewer, GitHub Gist Import/Publish, and Commit History.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local codeStore = env.require("runtime/code_store")
	local gitState = env.require("runtime/git_state")
	local githubSync = env.require("tools/github_sync")
	local githubConnect = env.require("ui/panels/github_connect")
	local commands = env.require("runtime/command_catalog")

	local M = {}

	function M.new(parent)
		local root = P.frame(parent, {
			name = "SourceControlViewlet",
			size = UDim2.fromScale(1, 1),
			visible = false,
			zIndex = 21,
		})
		P.pad(root, 6, 10, 6, 10)

		P.label(root, {
			size = UDim2.new(1, 0, 0, 22),
			text = "SOURCE CONTROL (GITHUB)",
			bold = true,
			textSize = 11,
			color = theme.color.muted,
			zIndex = 22,
		})

		local repoStatusLbl = P.label(root, {
			size = UDim2.new(1, 0, 0, 18),
			pos = UDim2.fromOffset(0, 22),
			textSize = 11,
			color = theme.color.accent,
			text = "No GitHub repository linked",
			truncate = true,
			zIndex = 22,
		})

		-- Row 1: Connect / Pull / Branch
		local btnRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 42),
			zIndex = 22,
		})
		P.list(btnRow, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		P.button(btnRow, {
			name = "ScmConnectBtn",
			size = UDim2.fromOffset(74, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "Clone / PAT",
			textSize = 11,
			radius = 4,
			order = 1,
			zIndex = 23,
			onClick = function() githubConnect.openModal() end,
		})
		P.button(btnRow, {
			name = "ScmPullBtn",
			size = UDim2.fromOffset(52, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "↻ Pull",
			textSize = 11,
			radius = 4,
			order = 2,
			zIndex = 23,
			onClick = function()
				task.spawn(function()
					local snap, err = githubSync.pull()
					if snap then overlay.toast("Pulled " .. snap.fullName, "good", 3)
					else overlay.toast("Pull failed: " .. tostring(err), "bad", 4) end
				end)
			end,
		})
		P.button(btnRow, {
			name = "ScmBranchBtn",
			size = UDim2.fromOffset(72, 24),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "⎇ Branch",
			textSize = 11,
			radius = 4,
			order = 3,
			zIndex = 23,
			onClick = function()
				commands.run("github.switchBranch")
			end,
		})

		-- Row 2: GitHub Gists (Import & Publish)
		local gistRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 24),
			pos = UDim2.fromOffset(0, 72),
			zIndex = 22,
		})
		P.list(gistRow, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		P.button(gistRow, {
			name = "ImportGistBtn",
			size = UDim2.fromOffset(96, 22),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "⬇ Import Gist",
			textSize = 11,
			radius = 4,
			order = 1,
			zIndex = 23,
			onClick = function() commands.run("github.importGist") end,
		})
		P.button(gistRow, {
			name = "PublishGistBtn",
			size = UDim2.fromOffset(102, 22),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "⬆ Publish Gist",
			textSize = 11,
			radius = 4,
			order = 2,
			zIndex = 23,
			onClick = function() commands.run("github.publishGist") end,
		})

		local _, msgInput = P.input(root, {
			name = "CommitMessageInput",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.fromOffset(0, 100),
			placeholder = "Message (Commit & Push via HTTP)",
			zIndex = 22,
		})

		local commitBtn = P.button(root, {
			name = "CommitAndPushBtn",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.fromOffset(0, 132),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = "✓ Commit & Push to GitHub",
			textSize = 12,
			radius = 4,
			zIndex = 22,
		})

		-- Stage All / Unstage All bar
		local stageBar = P.frame(root, {
			size = UDim2.new(1, 0, 0, 22),
			pos = UDim2.fromOffset(0, 164),
			zIndex = 22,
		})
		P.list(stageBar, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
		P.button(stageBar, {
			name = "StageAllBtn",
			size = UDim2.fromOffset(72, 20),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "+ Stage All",
			textSize = 10,
			radius = 3,
			order = 1,
			zIndex = 23,
			onClick = function() gitState.stageAll() end,
		})
		P.button(stageBar, {
			name = "UnstageAllBtn",
			size = UDim2.fromOffset(82, 20),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "− Unstage All",
			textSize = 10,
			radius = 3,
			order = 2,
			zIndex = 23,
			onClick = function() gitState.unstageAll() end,
		})

		local listScroll = P.scroll(root, {
			name = "ScmChangesList",
			size = UDim2.new(1, 0, 1, -190),
			pos = UDim2.fromOffset(0, 190),
			zIndex = 22,
		})
		P.list(listScroll, Enum.FillDirection.Vertical, 2)

		commitBtn.Activated:Connect(function()
			local msg = msgInput.Text ~= "" and msgInput.Text or "Update from VS-RBLX"
			task.spawn(function()
				commitBtn.Text = "Pushing via HTTP..."
				local res, err = githubSync.commitAndPush(msg)
				commitBtn.Text = "✓ Commit & Push to GitHub"
				if res then
					msgInput.Text = ""
					overlay.toast(string.format("Pushed commit %s (%d files)", res.commitSha:sub(1, 7), res.files), "good", 3.5)
				else
					overlay.toast("Push failed: " .. tostring(err), "bad", 4.5)
				end
			end)
		end)

		local function renderFileGroup(headerTitle, items, isStaged, startOrd)
			local ord = startOrd
			if #items == 0 then return ord end
			ord = ord + 1
			P.label(listScroll, {
				size = UDim2.new(1, 0, 0, 20),
				bold = true,
				textSize = 11,
				color = theme.color.muted,
				text = string.format("%s (%d)", headerTitle, #items),
				order = ord,
				zIndex = 23,
			})

			for _, ch in ipairs(items) do
				ord = ord + 1
				local row = P.frame(listScroll, {
					size = UDim2.new(1, 0, 0, 22),
					order = ord,
					zIndex = 23,
				})
				local badgeCol = ch.status == "A" and theme.color.good or (ch.status == "D" and theme.color.bad or theme.color.warn)
				local fileBtn = P.button(row, {
					name = "DiffRow_" .. ch.path,
					size = UDim2.new(1, -46, 1, 0),
					hoverBg = theme.color.hover,
					alignX = Enum.TextXAlignment.Left,
					textSize = 11,
					color = theme.color.sideBarText,
					text = "  [" .. ch.status .. "] " .. ch.path,
					zIndex = 24,
					onClick = function()
						local orig = gitState.originalContent(ch.path) or ""
						local cur = ch.status == "D" and "" or (codeStore.findByPath(ch.path) and codeStore.findByPath(ch.path).content or env.require("runtime/workspace_fs").readFile(ch.path) or "")
						codeStore.openDiff(ch.path, orig, cur)
					end,
				})
				fileBtn.TextTruncate = Enum.TextTruncate.AtEnd
				P.label(row, {
					size = UDim2.fromOffset(16, 22),
					pos = UDim2.new(1, -64, 0, 0),
					text = ch.status,
					bold = true,
					textSize = 11,
					color = badgeCol,
					alignX = Enum.TextXAlignment.Center,
					zIndex = 25,
				})
				P.button(row, {
					name = (isStaged and "Unstage_" or "Stage_") .. ch.path,
					size = UDim2.fromOffset(20, 20),
					pos = UDim2.new(1, -42, 0, 1),
					text = isStaged and "−" or "+",
					bold = true,
					textSize = 12,
					radius = 3,
					zIndex = 25,
					onClick = function()
						if isStaged then gitState.unstage(ch.path) else gitState.stage(ch.path) end
					end,
				})
				P.button(row, {
					name = "Discard_" .. ch.path,
					size = UDim2.fromOffset(20, 20),
					pos = UDim2.new(1, -20, 0, 1),
					text = "↺",
					textSize = 11,
					color = theme.color.bad,
					radius = 3,
					zIndex = 25,
					onClick = function()
						gitState.discardFile(ch.path)
						local openDoc = codeStore.findByPath(ch.path)
						if openDoc then
							codeStore.openFile(ch.path, { reloadFromDisk = true })
						end
						overlay.toast("Discarded changes in " .. ch.path, "warn", 2)
					end,
				})
			end
			return ord
		end

		local function refresh()
			local st = gitState.status()
			if st.repo then
				repoStatusLbl.Text = string.format("⎇ %s @ %s (%s)", st.repo, st.branch or "main", tostring(st.headSha or "local"):sub(1, 7))
			else
				repoStatusLbl.Text = "Local Workspace (Click Clone / PAT to link GitHub)"
			end

			listScroll:ClearAllChildren()
			P.list(listScroll, Enum.FillDirection.Vertical, 2)
			local ord = 0

			ord = renderFileGroup("STAGED CHANGES", st.staged, true, ord)
			ord = renderFileGroup("CHANGES", st.unstaged, false, ord)

			if st.total == 0 then
				ord = ord + 1
				P.label(listScroll, {
					size = UDim2.new(1, 0, 0, 24),
					text = "Working tree clean — all disk files match HEAD.",
					textSize = 11,
					color = theme.color.muted,
					order = ord,
					zIndex = 23,
				})
			end

			if #gitState.commits > 0 then
				ord = ord + 1
				P.label(listScroll, {
					size = UDim2.new(1, 0, 0, 22),
					bold = true,
					textSize = 11,
					color = theme.color.muted,
					text = "COMMIT HISTORY",
					order = ord,
					zIndex = 23,
				})
				for i = 1, math.min(10, #gitState.commits) do
					local c = gitState.commits[i]
					ord = ord + 1
					P.label(listScroll, {
						size = UDim2.new(1, 0, 0, 19),
						mono = true,
						textSize = 11,
						color = theme.color.sideBarText,
						text = string.format("● %s  %s (%s)", tostring(c.sha or ""):sub(1, 7), tostring(c.message or ""), tostring(c.time or "")),
						truncate = true,
						order = ord,
						zIndex = 23,
					})
				end
			end
		end

		gitState.changed:connect(refresh)
		codeStore.changed:connect(refresh)
		theme.changed:connect(refresh)

		refresh()
		return { root = root, refresh = refresh }
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/search
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/search"] = (function()
-- VS Code Workspace Search & Replace Sidebar Viewlet (`Ctrl+Shift+F`).
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local util = env.require("runtime/util")
	local codeSearch = env.require("runtime/code_search")
	local codeStore = env.require("runtime/code_store")

	local M = {}

	function M.new(parent)
		local root = P.frame(parent, {
			name = "SearchViewlet",
			size = UDim2.fromScale(1, 1),
			visible = false,
			zIndex = 21,
		})
		P.pad(root, 6, 10, 6, 10)

		P.label(root, {
			size = UDim2.new(1, 0, 0, 22),
			text = "SEARCH",
			bold = true,
			textSize = 11,
			color = theme.color.muted,
			zIndex = 22,
		})

		local _, queryBox = P.input(root, {
			name = "WorkspaceSearchInput",
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 26),
			placeholder = "Search across files...",
			zIndex = 22,
		})

		local _, replaceBox = P.input(root, {
			name = "WorkspaceReplaceInput",
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 56),
			placeholder = "Replace with...",
			zIndex = 22,
		})

		local optsRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 86),
			zIndex = 22,
		})
		P.list(optsRow, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local caseSensitive = false
		local wholeWord = false

		local caseBtn = P.button(optsRow, {
			size = UDim2.fromOffset(30, 22),
			bg = theme.color.inputBg,
			text = "Aa",
			mono = true,
			textSize = 11,
			radius = 3,
			order = 1,
			zIndex = 23,
		})
		local wordBtn = P.button(optsRow, {
			size = UDim2.fromOffset(32, 22),
			bg = theme.color.inputBg,
			text = "[ab]",
			mono = true,
			textSize = 10,
			radius = 3,
			order = 2,
			zIndex = 23,
		})
		local replaceAllBtn = P.button(optsRow, {
			name = "WorkspaceReplaceAllBtn",
			size = UDim2.fromOffset(92, 22),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			text = "Replace All",
			textSize = 11,
			radius = 3,
			order = 3,
			zIndex = 23,
		})

		local statusLbl = P.label(root, {
			size = UDim2.new(1, 0, 0, 18),
			pos = UDim2.fromOffset(0, 114),
			text = "Type a query to search workspace files.",
			textSize = 11,
			color = theme.color.muted,
			zIndex = 22,
		})

		local resultsScroll = P.scroll(root, {
			name = "SearchResultsScroll",
			size = UDim2.new(1, 0, 1, -136),
			pos = UDim2.fromOffset(0, 136),
			zIndex = 22,
		})
		P.list(resultsScroll, Enum.FillDirection.Vertical, 2)

		local function runSearch()
			resultsScroll:ClearAllChildren()
			P.list(resultsScroll, Enum.FillDirection.Vertical, 2)
			local q = queryBox.Text
			if q == "" then
				statusLbl.Text = "Type a query to search workspace files."
				return
			end
			local scan = codeSearch.searchWorkspace(q, {
				caseSensitive = caseSensitive,
				wholeWord = wholeWord,
			})
			statusLbl.Text = string.format("%d result(s) in %d file(s)", scan.totalMatches, #scan.files)

			local ord = 0
			for _, fileGroup in ipairs(scan.files) do
				ord = ord + 1
				P.label(resultsScroll, {
					size = UDim2.new(1, 0, 0, 20),
					bold = true,
					textSize = 11,
					color = theme.color.tabActiveText,
					text = string.format("▾ %s (%d)", fileGroup.path, #fileGroup.matches),
					truncate = true,
					order = ord,
					zIndex = 23,
				})
				for _, hit in ipairs(fileGroup.matches) do
					if ord < 160 then
						ord = ord + 1
						local targetPath = fileGroup.path
						local targetLn, targetCol = hit.line, hit.col
						local hitBtn = P.button(resultsScroll, {
							size = UDim2.new(1, 0, 0, 20),
							hoverBg = theme.color.hover,
							alignX = Enum.TextXAlignment.Left,
							mono = true,
							textSize = 11,
							color = theme.color.sideBarText,
							text = string.format("  %3d: %s", hit.line, util.trim(hit.lineText)),
							order = ord,
							zIndex = 23,
							onClick = function()
								codeStore.openFile(targetPath, { line = targetLn, col = targetCol })
							end,
						})
						hitBtn.TextTruncate = Enum.TextTruncate.AtEnd
					end
				end
			end
		end

		caseBtn.Activated:Connect(function()
			caseSensitive = not caseSensitive
			caseBtn.BackgroundColor3 = caseSensitive and theme.color.accent or theme.color.inputBg
			runSearch()
		end)
		wordBtn.Activated:Connect(function()
			wholeWord = not wholeWord
			wordBtn.BackgroundColor3 = wholeWord and theme.color.accent or theme.color.inputBg
			runSearch()
		end)
		queryBox:GetPropertyChangedSignal("Text"):Connect(runSearch)

		replaceAllBtn.Activated:Connect(function()
			if queryBox.Text == "" then return end
			local filesChanged, totalRep = codeSearch.replaceAcrossWorkspace(queryBox.Text, replaceBox.Text, {
				caseSensitive = caseSensitive,
				wholeWord = wholeWord,
			})
			overlay.toast(string.format("Replaced %d occurrence(s) across %d file(s)", totalRep, filesChanged), "good", 3)
			runSearch()
		end)

		return {
			root = root,
			focus = function()
				task.defer(function() pcall(function() queryBox:CaptureFocus() end) end)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settings
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/settings"] = (function()
-- Upgraded Interactive VS Code Settings Sidebar Viewlet (`Ctrl+,`):
-- Category Filter Pills, Dropdown Option Menus, Live Hotkey Capture,
-- `Open settings.json` raw JSON editor sync, and `Reset Defaults`.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local config = env.require("runtime/config")
	local catalog = env.require("runtime/settings_catalog")
	local commands = env.require("runtime/command_catalog")

	local M = {}

	function M.new(parent)
		local activeCategory = "All"

		local root = P.frame(parent, {
			name = "SettingsViewlet",
			size = UDim2.fromScale(1, 1),
			visible = false,
			zIndex = 21,
		})
		P.pad(root, 6, 10, 6, 10)

		local headerRow = P.frame(root, {
			size = UDim2.new(1, 0, 0, 24),
			zIndex = 22,
		})
		P.label(headerRow, {
			size = UDim2.new(1, -138, 1, 0),
			text = "SETTINGS",
			bold = true,
			textSize = 11,
			color = theme.color.muted,
			zIndex = 23,
		})

		P.button(headerRow, {
			name = "OpenSettingsJsonBtn",
			size = UDim2.fromOffset(72, 22),
			pos = UDim2.new(1, -136, 0, 1),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "{ } JSON",
			mono = true,
			bold = true,
			textSize = 10,
			radius = 4,
			zIndex = 23,
			onClick = function()
				commands.run("preferences.openSettingsJson")
			end,
		})

		P.button(headerRow, {
			name = "ResetSettingsBtn",
			size = UDim2.fromOffset(60, 22),
			pos = UDim2.new(1, -60, 0, 1),
			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "↺ Reset",
			textSize = 10,
			color = theme.color.warn,
			radius = 4,
			zIndex = 23,
			onClick = function()
				config.reset()
				overlay.toast("Settings restored to defaults", "info", 2.2)
			end,
		})

		local _, filterBox = P.input(root, {
			name = "SettingsFilterInput",
			size = UDim2.new(1, 0, 0, 26),
			pos = UDim2.fromOffset(0, 28),
			placeholder = "Search settings (theme, font, git, roblox, keymap)...",
			zIndex = 22,
		})

		-- Category filter bar
		local catScroll = P.scroll(root, {
			name = "SettingsCategoryBar",
			size = UDim2.new(1, 0, 0, 24),
			pos = UDim2.fromOffset(0, 58),
			canvasX = true,
			zIndex = 22,
		})
		catScroll.AutomaticCanvasSize = Enum.AutomaticSize.X
		catScroll.CanvasSize = UDim2.fromOffset(0, 0)
		catScroll.ScrollBarThickness = 2
		P.list(catScroll, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)

		local scroll = P.scroll(root, {
			name = "SettingsScroll",
			size = UDim2.new(1, 0, 1, -88),
			pos = UDim2.fromOffset(0, 86),
			zIndex = 22,
		})
		P.list(scroll, Enum.FillDirection.Vertical, 6)

		local rebuild

		local function rebuildCategories()
			catScroll:ClearAllChildren()
			P.list(catScroll, Enum.FillDirection.Horizontal, 4, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
			for idx, cat in ipairs(catalog.categories()) do
				local isSel = (cat == activeCategory)
				local pill = P.button(catScroll, {
					name = "SettingsCat_" .. cat,
					size = UDim2.fromOffset(#cat * 6 + 16, 20),
					bg = isSel and theme.color.accent or theme.color.inputBg,
					hoverBg = theme.color.hover,
					color = isSel and Color3.fromRGB(255, 255, 255) or theme.color.sideBarText,
					bold = isSel,
					text = cat,
					textSize = 10,
					radius = 10,
					order = idx,
					zIndex = 23,
					activeState = function() return cat == activeCategory end,
					onClick = function()
						activeCategory = cat
						rebuildCategories()
						if rebuild then rebuild() end
					end,
				})
				pill.BackgroundTransparency = 0
			end
		end

		local function optionLabelFor(item, val)
			if item.options then
				for _, opt in ipairs(item.options) do
					if opt.value == val then
						return opt.label or tostring(val)
					end
				end
			end
			return tostring(val)
		end

		rebuild = function()
			scroll:ClearAllChildren()
			P.list(scroll, Enum.FillDirection.Vertical, 6)
			local list = catalog.search(filterBox.Text, activeCategory)
			for idx, item in ipairs(list) do
				local card = P.frame(scroll, {
					size = UDim2.new(1, 0, 0, 62),
					bg = theme.color.inputBg,
					radius = 4,
					order = idx,
					zIndex = 23,
				})
				P.pad(card, 6, 8, 6, 8)
				P.label(card, {
					size = UDim2.new(1, -96, 0, 18),
					bold = true,
					textSize = 12,
					color = theme.color.tabActiveText,
					text = (item.category and (item.category .. ": ") or "") .. (item.title or item.key),
					truncate = true,
					zIndex = 24,
				})
				P.label(card, {
					size = UDim2.new(1, -96, 0, 28),
					pos = UDim2.fromOffset(0, 20),
					textSize = 10,
					color = theme.color.muted,
					text = item.description or "",
					wrap = true,
					zIndex = 24,
				})

				local curVal = config.get(item.key)
				if item.kind == "boolean" then
					local onBtn = P.button(card, {
						name = "Toggle_" .. item.key,
						size = UDim2.fromOffset(74, 24),
						pos = UDim2.new(1, -74, 0, 12),
						bg = curVal and theme.color.accent or theme.color.sideBar,
						color = Color3.fromRGB(255, 255, 255),
						bold = true,
						text = curVal and "✓ ON" or "OFF",
						textSize = 11,
						radius = 4,
						zIndex = 24,
						onClick = function()
							config.set(item.key, not curVal)
						end,
					})
					onBtn.BackgroundTransparency = 0
				elseif item.kind == "number" then
					P.button(card, {
						size = UDim2.fromOffset(24, 24),
						pos = UDim2.new(1, -78, 0, 12),
						bg = theme.color.sideBar,
						text = "−",
						radius = 3,
						zIndex = 24,
						onClick = function()
							local nextN = math.max(item.min or 1, (tonumber(curVal) or 14) - (item.step or 1))
							config.set(item.key, nextN)
						end,
					})
					P.label(card, {
						size = UDim2.fromOffset(28, 24),
						pos = UDim2.new(1, -52, 0, 12),
						mono = true,
						textSize = 11,
						alignX = Enum.TextXAlignment.Center,
						text = tostring(curVal),
						zIndex = 24,
					})
					P.button(card, {
						size = UDim2.fromOffset(24, 24),
						pos = UDim2.new(1, -24, 0, 12),
						bg = theme.color.sideBar,
						text = "+",
						radius = 3,
						zIndex = 24,
						onClick = function()
							local nextN = math.min(item.max or 99, (tonumber(curVal) or 14) + (item.step or 1))
							config.set(item.key, nextN)
						end,
					})
				elseif item.kind == "select" and item.options then
					local ddBtn = P.button(card, {
						name = "Select_" .. item.key,
						size = UDim2.fromOffset(88, 24),
						pos = UDim2.new(1, -88, 0, 12),
						bg = theme.color.sideBar,
						hoverBg = theme.color.hover,
						textSize = 10,
						text = tostring(curVal) .. " ▾",
						radius = 4,
						zIndex = 24,
					})
					ddBtn.BackgroundTransparency = 0
					ddBtn.TextTruncate = Enum.TextTruncate.AtEnd
					ddBtn.Activated:Connect(function()
						local menu = {}
						for _, opt in ipairs(item.options) do
							local optVal = opt.value
							menu[#menu + 1] = {
								label = (optVal == curVal and "✓ " or "   ") .. optionLabelFor(item, optVal),
								onClick = function()
									config.set(item.key, optVal)
								end,
							}
						end
						if item.key == "keybindings.toggleKey" then
							menu[#menu + 1] = { separator = true }
							menu[#menu + 1] = {
								label = "⌨ Capture Any Key...",
								onClick = function()
									commands.run("workbench.changeToggleKey")
								end,
							}
						end
						local p = ddBtn.AbsolutePosition
						overlay.dropdown(math.max(12, p.X - 110), p.Y + 26, menu, 210)
					end)
				end
			end
		end

		filterBox:GetPropertyChangedSignal("Text"):Connect(rebuild)
		config.changed:connect(rebuild)
		theme.changed:connect(function()
			rebuildCategories()
			rebuild()
		end)

		rebuildCategories()
		rebuild()
		return {
			root = root,
			refresh = rebuild,
			setCategory = function(cat)
				activeCategory = cat or "All"
				rebuildCategories()
				rebuild()
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/vault_modal
-- ==========================================================================
__VSRBLX_MODULES["ui/panels/vault_modal"] = (function()
-- Zero-Knowledge Master Vault Onboarding, Unlock, Lock & Reset Modal (`src/ui/panels/vault_modal.lua`).
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local responsive = env.require("ui/responsive")
	local cryptoVault = env.require("runtime/crypto_vault")
	local github = env.require("net/github")
	local util = env.require("runtime/util")

	local M = {}

	local function clampedModalSize(prefW, prefH)
		local vp = responsive.usableRect(8)
		return math.min(prefW, math.max(280, vp.width - 16)), math.min(prefH, math.max(200, vp.height - 16))
	end

	function M.openSetupModal()
		local mw, mh = clampedModalSize(446, 224)
		local card = overlay.openModal("VaultSetupModal", mw, mh)
		P.pad(card, 12, 14, 12, 14)

		P.label(card, {
			name = "VaultModalTitle",
			size = UDim2.new(1, -30, 0, 20),
			text = "🔐 Zero-Knowledge Master Vault",
			bold = true,
			textSize = 13,
			color = theme.color.tabActiveText,
			truncate = true,
			zIndex = 232,
		})
		P.button(card, {
			name = "VaultCloseBtn",
			size = UDim2.fromOffset(24, 22),
			pos = UDim2.new(1, -24, 0, 0),
			text = "✕",
			radius = 4,
			zIndex = 232,
			onClick = function() overlay.closeModal() end,
		})

		P.label(card, {
			size = UDim2.new(1, 0, 0, 54),
			pos = UDim2.fromOffset(0, 24),
			wrap = true,
			textSize = 11,
			alignY = Enum.TextYAlignment.Top,
			color = theme.color.muted,
			text = "Create a private Master Vault Key to deeply encrypt your GitHub PAT (PBKDF2-HMAC-SHA256). Even VS-RBLX cannot recover your PAT without this key. Don't want encryption? Click 'Leave Unencrypted'.",
			zIndex = 232,
		})

		local _, keyBox = P.input(card, {
			name = "VaultKeyInput",
			size = UDim2.new(1, 0, 0, 28),
			pos = UDim2.fromOffset(0, 84),
			mono = true,
			placeholder = "Create Master Vault Key (4+ characters)...",
			zIndex = 232,
		})

		local errLbl = P.label(card, {
			name = "VaultStatusLabel",
