			statusBar = hex("#007acc"),
			statusBarRemote = hex("#16825d"),
			statusBarText = hex("#ffffff"),
			inputBg = hex("#ffffff"),
			inputBorder = hex("#cecece"),
			inputFocus = hex("#007acc"),
			dropdownBg = hex("#f3f3f3"),
			hover = hex("#e8e8e8"),
			listActive = hex("#d6ebff"),
			border = hex("#e0e0e0"),
			accent = hex("#007acc"),
			accentHover = hex("#005a9e"),
			muted = hex("#6e6e6e"),
			good = hex("#1a7f37"),
			warn = hex("#9a6700"),
			bad = hex("#cf222e"),
			diffAddBg = hex("#dafbe1"),
			diffRemoveBg = hex("#ffebe9"),
			syntax = {
				keyword = "#0000ff",
				builtin = "#267f99",
				type = "#267f99",
				string = "#a31515",
				number = "#098658",
				comment = "#008000",
				call = "#795e26",
				property = "#001080",
				tag = "#800000",
				decorator = "#af00db",
			},
		},
	}

	M.palettes = PALETTES
	M.color = {}
	M.syntax = {}

	local function resolveFont(candidates, fallback)
		for _, name in ipairs(candidates) do
			local ok, f = pcall(function() return Enum.Font[name] end)
			if ok and f then return f end
		end
		return fallback
	end

	M.font = {
		ui = resolveFont({ "BuilderSans", "Gotham", "SourceSans" }, Enum.Font.SourceSans),
		uiMedium = resolveFont({ "BuilderSansMedium", "GothamMedium", "SourceSansSemibold" }, Enum.Font.SourceSans),
		uiBold = resolveFont({ "BuilderSansBold", "GothamBold", "SourceSansBold" }, Enum.Font.SourceSans),
		mono = resolveFont({ "RobotoMono", "Code", "Ubuntu" }, Enum.Font.Code),
	}

	M.sizes = {
		titleBar = 32,
		activityBar = 48,
		tabBar = 35,
		breadcrumbs = 22,
		statusBar = 22,
		editorFont = 14,
		editorLineHeight = 20,
		uiFont = 13,
		smallFont = 11,
	}

	local THEME_ORDER = {
		"dark_plus",
		"one_dark",
		"github_dark",
		"monokai",
		"dracula",
		"catppuccin",
		"solarized_dark",
		"light_plus",
	}

	local CUSTOM_ORDER = {}

	function M.registerCustomTheme(themeId, spec)
		if type(themeId) ~= "string" or themeId == "" or type(spec) ~= "table" then return false end
		local basePal = (spec.isLight == true) and PALETTES.light_plus or PALETTES.dark_plus
		local built = {
			name = tostring(spec.name or spec.label or themeId),
			isLight = spec.isLight == true,
			isCustom = true,
			syntax = {},
		}
		for k, v in pairs(basePal) do
			if k ~= "syntax" and k ~= "name" and k ~= "isLight" then
				built[k] = v
			end
		end
		for k, v in pairs(basePal.syntax) do
			built.syntax[k] = v
		end
		if type(spec.colors) == "table" then
			for k, hexStr in pairs(spec.colors) do
				if type(hexStr) == "string" and hexStr:match("^#%x%x%x%x%x%x$") and built[k] ~= nil then
					built[k] = hex(hexStr)
				end
			end
		end
		if type(spec.syntax) == "table" then
			for k, hexStr in pairs(spec.syntax) do
				if type(hexStr) == "string" and hexStr:match("^#%x%x%x%x%x%x$") and built.syntax[k] ~= nil then
					built.syntax[k] = hexStr
				end
			end
		end
		PALETTES[themeId] = built
		local found = false
		for _, id in ipairs(CUSTOM_ORDER) do
			if id == themeId then found = true; break end
		end
		if not found then CUSTOM_ORDER[#CUSTOM_ORDER + 1] = themeId end
		return true
	end

	function M.unregisterCustomTheme(themeId)
		if not PALETTES[themeId] or not PALETTES[themeId].isCustom then return false end
		PALETTES[themeId] = nil
		for i = #CUSTOM_ORDER, 1, -1 do
			if CUSTOM_ORDER[i] == themeId then table.remove(CUSTOM_ORDER, i) end
		end
		if M.activeId == themeId then
			M.apply("dark_plus")
		end
		return true
	end

	function M.list()
		local out = {}
		for _, id in ipairs(THEME_ORDER) do
			local p = PALETTES[id]
			if p then
				out[#out + 1] = { id = id, label = p.name, isLight = p.isLight }
			end
		end
		for _, id in ipairs(CUSTOM_ORDER) do
			local p = PALETTES[id]
			if p then
				out[#out + 1] = { id = id, label = p.name, isLight = p.isLight, isCustom = true }
			end
		end
		return out
	end

	function M.apply(explicitId)
		if type(explicitId) == "string" and PALETTES[explicitId] then
			if config.get("workbench.colorTheme", "dark_plus") ~= explicitId then
				config.set("workbench.colorTheme", explicitId)
				return true
			end
		end
		local id = tostring(config.get("workbench.colorTheme", "dark_plus") or "dark_plus")
		local pal = PALETTES[id] or PALETTES.dark_plus
		M.activeId = PALETTES[id] and id or "dark_plus"
		for k, v in pairs(pal) do
			if k ~= "syntax" then
				M.color[k] = v
			end
		end
		for k, v in pairs(pal.syntax) do
			M.syntax[k] = v
		end
		local fontSz = util.clamp(tonumber(config.get("editor.fontSize", 14)) or 14, 11, 24)
		M.sizes.editorFont = fontSz
		M.sizes.editorLineHeight = math.floor(fontSz * 1.42 + 0.5)
		return PALETTES[id] ~= nil
	end

	M.apply()
	config.changed:connect(function(key)
		if key == "*" or key == "workbench.colorTheme" or key == "editor.fontSize" then
			M.apply()
			M.changed:fire(M.activeId)
		end
	end)

	return M
end
end)()

