			bg = theme.color.inputBg,
			hoverBg = theme.color.hover,
			text = "",
			radius = 4,
			border = theme.color.inputBorder,
			order = 1,
			zIndex = 34,
		})
		local opacityFill = P.frame(opacityBtn, {
			name = "OpacityFill",
			size = UDim2.new((curOpacity - 0.30) / 0.70, 0, 0, 3),
			pos = UDim2.new(0, 0, 1, -3),
			bg = theme.color.accent,
			radius = 2,
			zIndex = 35,
		})
		local opacityIconSlot = P.frame(opacityBtn, {
			size = UDim2.fromOffset(14, 14),
			pos = UDim2.fromOffset(5, 4),
			zIndex = 35,
		})
		icons.codicon(opacityIconSlot, "opacity", 13, theme.color.titleBarText, 36)
		local opacityLbl = P.label(opacityBtn, {
			name = "OpacityLabel",
			size = UDim2.new(1, -21, 1, -2),
			pos = UDim2.fromOffset(20, 0),
			text = string.format("%d%%", math.floor(curOpacity * 100 + 0.5)),
			mono = true,
			bold = true,
			textSize = 10,
			color = theme.color.titleBarText,
			alignX = Enum.TextXAlignment.Center,
			zIndex = 36,
		})

		local function refreshOpacityUi(alpha)
			curOpacity = util.clamp(tonumber(alpha) or 1.0, 0.30, 1.0)
			opacityLbl.Text = string.format("%d%%", math.floor(curOpacity * 100 + 0.5))
			opacityFill.Size = UDim2.new(util.clamp((curOpacity - 0.30) / 0.70, 0, 1), 0, 0, 3)
			opacityFill.BackgroundColor3 = curOpacity < 0.99 and theme.color.good or theme.color.accent
		end

		local scrubbingOpacity = false
		local didScrubMove = false
		local scrubStartX = 0

		local function applyScrubAt(screenX)
			local absX = opacityBtn.AbsolutePosition.X
			local absW = math.max(1, opacityBtn.AbsoluteSize.X)
			local ratio = util.clamp((screenX - absX) / absW, 0, 1)
			local nextAlpha = 0.30 + ratio * 0.70
			refreshOpacityUi(nextAlpha)
			if callbacks.onSetOpacity then
				callbacks.onSetOpacity(nextAlpha)
			end
		end

		opacityBtn.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
				scrubbingOpacity = true
				didScrubMove = false
				scrubStartX = input.Position.X
			end
		end)

		if env.uis then
			dispose.connection(env.uis.InputChanged:Connect(function(input)
				if not scrubbingOpacity then return end
				local kind = input.UserInputType
				if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end
				if math.abs(input.Position.X - scrubStartX) >= 3 then
					didScrubMove = true
					applyScrubAt(input.Position.X)
				end
			end))
			dispose.connection(env.uis.InputEnded:Connect(function(input)
				if not scrubbingOpacity then return end
				local kind = input.UserInputType
				if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
					scrubbingOpacity = false
				end
			end))
		end

		opacityBtn.Activated:Connect(function()
			if didScrubMove then
				didScrubMove = false
				return
			end
			local p = opacityBtn.AbsolutePosition
			local presets = {
				{ label = "100% — Solid Window", shortcut = "Default", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(1.0) end end },
				{ label = "85% — Subtle Peek", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.85) end end },
				{ label = "70% — Translucent", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.70) end end },
				{ label = "50% — Ghost Coding", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.50) end end },
				{ label = "30% — Ultra Ghost", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.30) end end },
			}
			overlay.dropdown(math.max(8, p.X - 70), p.Y + opacityBtn.AbsoluteSize.Y + 4, presets, 196)
		end)

		local iconBtnSpecs = {}
		local function makeIconBtn(name, iconName, order, hoverCol, onClick)
			local b = P.button(rightCluster, {
				name = name,
				size = UDim2.fromOffset(28, h),
				hoverBg = hoverCol or theme.color.hover,
				text = "",
				order = order,
				zIndex = 34,
				onClick = onClick,
			})
			local holder = P.frame(b, {
				size = UDim2.fromOffset(16, 16),
				pos = UDim2.fromOffset(6, math.floor((h - 16) / 2)),
				zIndex = 35,
			})
			icons.codicon(holder, iconName, 16, theme.color.titleBarText, 35)
			iconBtnSpecs[#iconBtnSpecs + 1] = { holder = holder, iconName = iconName }
			return b
		end

		local zenBtn = makeIconBtn("ZenModeBtn", "zen", 2, nil, function() commands.run("workbench.toggleZenMode") end)
		local toggleSidebarBtn = makeIconBtn("ToggleSidebarBtn", "sidebar", 3, nil, function() commands.run("view.toggleSidebar") end)
		local togglePanelBtn = makeIconBtn("TogglePanelBtn", "panel", 4, nil, function() commands.run("view.togglePanel") end)
		local splitEditorBtn = makeIconBtn("SplitEditorBtn", "split", 5, nil, function() commands.run("view.splitEditor") end)

		-- Compact `⋯` Overflow Button for narrow windows / phones so RightControls NEVER collide with Menu or Search!
		local compactMoreBtn = P.button(rightCluster, {
			name = "CompactMoreBtn",
			size = UDim2.fromOffset(26, 22),
			hoverBg = theme.color.hover,
			text = "⋯",
			bold = true,
			textSize = 13,
			color = theme.color.titleBarText,
			radius = 4,
			visible = false,
			order = 5,
			zIndex = 34,
			onClick = function()
				local p = rightCluster.AbsolutePosition
				local items = {
					{ label = "⌕ Command Palette...", shortcut = "Ctrl+Shift+P", onClick = function() commands.run("workbench.commandPalette") end },
					{ label = string.format("◑ Window Opacity (%d%%)...", math.floor(curOpacity * 100 + 0.5)), onClick = function()
						local presets = {
							{ label = "100% — Solid", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(1.0) end end },
							{ label = "85% — Subtle Peek", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.85) end end },
							{ label = "70% — Translucent", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.70) end end },
							{ label = "50% — Ghost Coding", onClick = function() if callbacks.onSetOpacity then callbacks.onSetOpacity(0.50) end end },
						}
						overlay.dropdown(p.X, p.Y + h + 2, presets, 190)
					end },
					{ separator = true },
					{ label = "Toggle Primary Sidebar", shortcut = "Ctrl+B", onClick = function() commands.run("view.toggleSidebar") end },
					{ label = "Toggle Bottom Panel", shortcut = "Ctrl+J", onClick = function() commands.run("view.togglePanel") end },
					{ label = "Split Editor Right", shortcut = "Ctrl+\\", onClick = function() commands.run("view.splitEditor") end },
					{ label = "✦ Toggle Zen Mode", onClick = function() commands.run("workbench.toggleZenMode") end },
					{ separator = true },
					{ label = "🔐 Zero-Knowledge Master Vault...", onClick = function() commands.run("vault.open") end },
				}
				overlay.dropdown(p.X, p.Y + h + 2, items, 230)
			end,
		})

		makeIconBtn("MinimizeWindowBtn", "minimize", 6, nil, function()
			if callbacks.onMinimize then callbacks.onMinimize() end
		end)
		makeIconBtn("MaximizeWindowBtn", "maximize", 7, nil, function()
			if callbacks.onMaximize then callbacks.onMaximize() end
		end)
		makeIconBtn("CloseWindowBtn", "close", 8, Color3.fromRGB(232, 17, 35), function()
			if callbacks.onClose then callbacks.onClose() end
		end)

		local currentBarWidth = 980
		local isCompactWidth = false
		local isUltraCompact = false

		local function refreshTitle()
			local doc = codeStore.active()
			local filePart = doc and doc.title or "Welcome"
			if isUltraCompact then
				centerText.Text = "⌕"
			elseif isCompactWidth then
				centerText.Text = "⌕  " .. filePart
			else
				local zenPrefix = config.get("workbench.zenMode", false) and "✦ ZEN  •  " or "⌕  "
				centerText.Text = string.format("%s%s — %s  (Ctrl+P)", zenPrefix, workspaceFs.activeName, filePart)
			end
		end

		-- Width-Aware Zero-Overlap Reflow (`>= 880px` full, `560–879px` compact menu + overflow, `< 560px` phone-safe!)
		local function reflowForWidth(barW)
			currentBarWidth = tonumber(barW) or bar.AbsoluteSize.X
			if currentBarWidth <= 0 then currentBarWidth = 980 end

			isCompactWidth = (currentBarWidth < 880) or mobileMode
			isUltraCompact = currentBarWidth < 540

			drawerBtn.Visible = mobileMode
			drawerBtn.Size = UDim2.fromOffset(34, h - 2)
			logo.Visible = (not mobileMode) and (not isUltraCompact)

			-- Left Menu Bar vs Compact `≡ Menu`
			if mobileMode then
				menuRow.Visible = false
				compactMenuBtn.Visible = false
			elseif isCompactWidth then
				menuRow.Visible = false
				compactMenuBtn.Visible = true
				compactMenuBtn.Position = UDim2.fromOffset(isUltraCompact and 6 or 30, math.floor((h - 22) * 0.5))
			else
				menuRow.Visible = true
				menuRow.Position = UDim2.fromOffset(34, 0)
				menuRow.Size = UDim2.fromOffset(250, h)
				compactMenuBtn.Visible = false
			end

			-- Secondary Right Toggles vs `⋯` Overflow
			local showFullRight = (currentBarWidth >= 780) and (not mobileMode)
			opacityBtn.Visible = (currentBarWidth >= 660) and (not isUltraCompact)
			zenBtn.Visible = showFullRight
			toggleSidebarBtn.Visible = showFullRight
			togglePanelBtn.Visible = showFullRight
			splitEditorBtn.Visible = showFullRight
			compactMoreBtn.Visible = not showFullRight
			vaultBtn.Visible = not isUltraCompact

			local rightW
			if showFullRight then
				rightW = 386
			elseif opacityBtn.Visible then
				rightW = 278
			elseif isUltraCompact then
				rightW = 182
			else
				rightW = 212
			end
			rightCluster.Size = UDim2.fromOffset(rightW, h)
			rightCluster.Position = UDim2.new(1, -rightW, 0, 0)

			-- Left occupied width & Center Search Pill exact non-overlapping slot
			local leftOccupied = mobileMode and 42 or (isCompactWidth and (isUltraCompact and 58 or 84) or 288)
			local availCenter = currentBarWidth - leftOccupied - rightW - 12
			if availCenter < 30 then
				centerPill.Visible = false
			else
				centerPill.Visible = true
				local pillW = isUltraCompact and math.min(44, availCenter) or math.min(236, availCenter)
				local centerX = leftOccupied + math.floor((availCenter + 12) * 0.5)
				centerPill.Size = UDim2.fromOffset(pillW, 22)
				centerPill.Position = UDim2.new(0, centerX, 0.5, 0)
			end
			refreshTitle()
		end

		config.changed:connect(function(key, val)
			if key == "window.opacity" or key == "*" then
				refreshOpacityUi(config.get("window.opacity", 1.0))
			end
			if key == "workbench.zenMode" or key == "*" then
				refreshTitle()
			end
		end)
		codeStore.changed:connect(refreshTitle)
		workspaceFs.changed:connect(refreshTitle)
		theme.changed:connect(function()
			bar.BackgroundColor3 = theme.color.titleBar
			bottomBorder.BackgroundColor3 = theme.color.border
			centerPill.BackgroundColor3 = theme.color.inputBg
			centerText.TextColor3 = theme.color.muted
			compactMenuBtn.TextColor3 = theme.color.titleBarText
			compactMoreBtn.TextColor3 = theme.color.titleBarText
			opacityBtn.BackgroundColor3 = theme.color.inputBg
			opacityLbl.TextColor3 = theme.color.titleBarText
			opacityIconSlot:ClearAllChildren()
			icons.codicon(opacityIconSlot, "opacity", 13, theme.color.titleBarText, 36)
			for _, spec in ipairs(iconBtnSpecs) do
				spec.holder:ClearAllChildren()
				icons.codicon(spec.holder, spec.iconName, 16, theme.color.titleBarText, 35)
			end
			for _, b in ipairs(menuButtons) do
				b.TextColor3 = theme.color.titleBarText
			end
			refreshOpacityUi(curOpacity)
			refreshResizeBtn(resizeActive)
			refreshVaultBtn()
		end)

		refreshOpacityUi(curOpacity)
		refreshResizeBtn(false)
		refreshVaultBtn()
		reflowForWidth(980)
		return {
			root = bar,
			drawerButton = drawerBtn,
			mobileButton = mobileToggleBtn,
			resizeButton = resizeModeBtn,
			vaultButton = vaultBtn,
			opacityButton = opacityBtn,
			refresh = refreshTitle,
			refreshOpacity = refreshOpacityUi,
			setResizeMode = refreshResizeBtn,
			reflow = reflowForWidth,
			setMobileMode = function(flag)
				mobileMode = flag == true
				h = mobileMode and 38 or theme.sizes.titleBar
				bar.Size = UDim2.new(1, 0, 0, h)
				mobileToggleBtn.BackgroundColor3 = mobileMode and theme.color.accent or theme.color.titleBar
				mobileToggleBtn.BackgroundTransparency = mobileMode and 0 or 1
				reflowForWidth(currentBarWidth)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/window
-- ==========================================================================
__VSRBLX_MODULES["ui/window"] = (function()
-- Draggable, Auto-Resized, and Explicit Toggle-Resizable (`⤢` ON/OFF) Window Shell for VS-RBLX.
-- Supports both Desktop and Mobile Acode Mode as a movable floating window (with `□` Maximize
-- when full-bleed is desired) + a draggable `MinimizedPill` (`VS-RBLX ↗`).
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local dispose = env.require("runtime/dispose")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local brand = env.require("ui/brand")
	local P = env.require("ui/primitives")

	local DESKTOP_MIN_W = 360
	local DESKTOP_MIN_H = 240
	local MOBILE_MIN_W = 280
	local MOBILE_MIN_H = 200
	local SNAP_EDGE = 12

	local M = {}

	function M.new(parentScreen)
		local initOpacity = util.clamp(tonumber(config.get("window.opacity", 1.0)) or 1.0, 0.30, 1.0)
		local win = {
			visible = true,
			minimised = false,
			maximised = config.get("window.maximised", false) == true,
			mobileMode = false,
			resizeMode = false, -- Explicit Topbar `⤢` Resize Toggle (OFF by default so edges never hijack moving!)
			playWhileCoding = config.get("mobile.playWhileCoding", false) == true,
			opacity = initOpacity,
			opacityChanged = signal.new("window.opacityChanged"),
			resizeModeChanged = signal.new("window.resizeModeChanged"),
			snappedSide = nil,
			onResize = nil,
		}
		local prePlayOpacity = nil

		local root = P.frame(parentScreen, {
			name = "VSCodeWindow",
			size = UDim2.fromOffset(980, 620),
			pos = UDim2.fromOffset(100, 60),
			bg = theme.color.editor,
			transparency = 1,
			radius = 6,
			clip = true,
			active = true,
			zIndex = 10,
		})
		local borderStroke = P.stroke(root, theme.color.border, 1)
		win.root = root

		local contentHost = P.frame(root, {
			name = "WorkbenchHost",
			size = UDim2.fromScale(1, 1),
			clip = true,
			zIndex = 11,
		})
		win.body = contentHost

		-- Minimized floating launcher pill (now draggable so mobile players can move it away from thumbsticks!)
		local pill = P.button(parentScreen, {
			name = "MinimizedPill",
			size = UDim2.fromOffset(128, 32),
			pos = UDim2.new(0, 16, 1, -52),
			bg = theme.color.titleBar,
			hoverBg = theme.color.hover,
			text = "",
			radius = 16,
			border = theme.color.accent,
			visible = false,
			zIndex = 190,
		})
		local pillBrand = brand.draw(pill, 16, 192)
		pillBrand.Position = UDim2.fromOffset(10, 8)
		P.label(pill, {
			size = UDim2.new(1, -34, 1, 0),
			pos = UDim2.fromOffset(32, 0),
			text = "VS-RBLX  ↗",
			bold = true,
			textSize = 12,
			color = theme.color.titleBarText,
			zIndex = 192,
		})
		win.pill = pill

		local preSnapRect = nil
		local activeGesture = nil
		local pillDidDrag = false

		pill.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			pillDidDrag = false
			local absP = pill.AbsolutePosition
			activeGesture = {
				mode = "pillDrag",
				input = input,
				startMouse = input.Position,
				startX = absP.X,
				startY = absP.Y,
			}
		end)
		pill.Activated:Connect(function()
			if pillDidDrag then
				pillDidDrag = false
				return
			end
			win.restore()
		end)

		local function persistRect()
			if win.maximised or win.snappedSide then return end
			config.set("window.width", math.floor(root.Size.X.Offset), { quiet = true })
			config.set("window.height", math.floor(root.Size.Y.Offset), { quiet = true })
			config.set("window.x", math.floor(root.Position.X.Offset), { quiet = true })
			config.set("window.y", math.floor(root.Position.Y.Offset), { quiet = true })
			config.set("window.placed", true, { quiet = true })
		end

		function win.effectiveMinBounds(bounds)
			local minW = win.mobileMode and MOBILE_MIN_W or DESKTOP_MIN_W
			local minH = win.mobileMode and MOBILE_MIN_H or DESKTOP_MIN_H
			return math.min(minW, bounds.width), math.min(minH, bounds.height)
		end

		function win.applyLayout(reason)
			local bounds = responsive.usableRect(win.maximised and 0 or 6)
			local effMinW, effMinH = win.effectiveMinBounds(bounds)

			if win.playWhileCoding then
				-- Play-While-Coding Split Peek: docks to right ~52% so left half stays free for thumbstick & gameplay!
				local dockW = math.max(effMinW, math.floor(bounds.width * 0.52))
				local dockH = math.max(effMinH, math.floor(bounds.height * 0.94))
				root.Position = UDim2.fromOffset(bounds.x + bounds.width - dockW, bounds.y)
				root.Size = UDim2.fromOffset(dockW, dockH)
			elseif win.maximised then
				root.Position = UDim2.fromOffset(bounds.x, bounds.y)
				root.Size = UDim2.fromOffset(bounds.width, bounds.height)
			elseif win.snappedSide == "left" then
				root.Position = UDim2.fromOffset(bounds.x, bounds.y)
				root.Size = UDim2.fromOffset(math.floor(bounds.width * 0.5), bounds.height)
			elseif win.snappedSide == "right" then
				local half = math.floor(bounds.width * 0.5)
				root.Position = UDim2.fromOffset(bounds.x + bounds.width - half, bounds.y)
				root.Size = UDim2.fromOffset(half, bounds.height)
			else
				local autoScale = config.get("window.autoResize", true) == true
				local customSize = config.get("window.customSize", false) == true
				local placed = config.get("window.placed", false) == true

				local w, h
				if autoScale and (not customSize or reason == "resetAuto") then
					local defScaleW = win.mobileMode and 0.90 or 0.84
					local defScaleH = win.mobileMode and 0.86 or 0.84
					local scaleW = tonumber(config.get("window.widthScale", defScaleW)) or defScaleW
					local scaleH = tonumber(config.get("window.heightScale", defScaleH)) or defScaleH
					if win.mobileMode and not customSize then
						scaleW = defScaleW
						scaleH = defScaleH
					end
					w = math.floor(bounds.width * scaleW)
					h = math.floor(bounds.height * scaleH)
				else
					w = tonumber(config.get("window.width", 980)) or 980
					h = tonumber(config.get("window.height", 620)) or 620
				end

				w = util.clamp(w, effMinW, bounds.width)
				h = util.clamp(h, effMinH, bounds.height)

				local x, y
				if placed then
					x = tonumber(config.get("window.x", 0)) or 0
					y = tonumber(config.get("window.y", 0)) or 0
				else
					x = bounds.x + math.floor((bounds.width - w) * 0.5)
					y = bounds.y + math.floor((bounds.height - h) * 0.5)
				end
				x = util.clamp(x, bounds.x, math.max(bounds.x, bounds.x + bounds.width - w))
				y = util.clamp(y, bounds.y, math.max(bounds.y, bounds.y + bounds.height - h))

				root.Size = UDim2.fromOffset(w, h)
				root.Position = UDim2.fromOffset(x, y)
			end

			if win.onResize then
				pcall(win.onResize, root.Size.X.Offset, root.Size.Y.Offset)
			end
		end

		-- 8-way Push/Pull Resize Handles (ONLY active & visible when `win.resizeMode == true`!)
		local resizeHandles = {}

		local function makeResizeZone(name, dirX, dirY, isCorner)
			local zone = P.frame(root, {
				name = name,
				size = UDim2.fromOffset(14, 14),
				pos = UDim2.fromOffset(0, 0),
				bg = theme.color.accent,
				transparency = 0.20,
				radius = isCorner and 6 or 3,
				visible = false,
				active = false,
				zIndex = 95,
			})
			resizeHandles[#resizeHandles + 1] = {
				zone = zone,
				dirX = dirX,
				dirY = dirY,
				isCorner = isCorner == true,
			}

			zone.InputBegan:Connect(function(input)
				if not win.resizeMode then return end
				local kind = input.UserInputType
				if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
				if win.maximised then return end
				win.snappedSide = nil
				activeGesture = {
					mode = "resize",
					input = input,
					startMouse = input.Position,
					startX = root.Position.X.Offset,
					startY = root.Position.Y.Offset,
					startW = root.Size.X.Offset,
					startH = root.Size.Y.Offset,
					dirX = dirX,
					dirY = dirY,
				}
			end)
		end

		makeResizeZone("ResizeLeft", -1, 0, false)
		makeResizeZone("ResizeRight", 1, 0, false)
		makeResizeZone("ResizeTop", 0, -1, false)
		makeResizeZone("ResizeBottom", 0, 1, false)
		makeResizeZone("ResizeTopLeft", -1, -1, true)
		makeResizeZone("ResizeTopRight", 1, -1, true)
		makeResizeZone("ResizeBottomLeft", -1, 1, true)
		makeResizeZone("ResizeBottomRight", 1, 1, true)

		-- Visual Resize-Mode Banner Pill at top-center while Resize Mode is ON
		local resizeBanner = P.button(root, {
			name = "ResizeModeBanner",
			size = UDim2.fromOffset(224, 24),
			pos = UDim2.new(0.5, 0, 0, 42),
			anchor = Vector2.new(0.5, 0),
			bg = theme.color.accent,
			hoverBg = theme.color.accentHover,
			color = Color3.fromRGB(255, 255, 255),
			bold = true,
			text = "⤢ RESIZE ON — Pull/Push Edges (Tap to Lock)",
			textSize = 10,
			radius = 12,
			visible = false,
			zIndex = 96,
			onClick = function()
				win.setResizeMode(false)
			end,
		})
		resizeBanner.BackgroundTransparency = 0.05

		local function layoutResizeHandles()
			local edgeT = win.mobileMode and 14 or 8
			local cornerS = win.mobileMode and 24 or 16
			for _, h in ipairs(resizeHandles) do
				local z = h.zone
				z.BackgroundColor3 = theme.color.accent
				if h.isCorner then
					z.Size = UDim2.fromOffset(cornerS, cornerS)
					local px = (h.dirX == -1) and UDim.new(0, 0) or UDim.new(1, -cornerS)
					local py = (h.dirY == -1) and UDim.new(0, 0) or UDim.new(1, -cornerS)
					z.Position = UDim2.new(px.Scale, px.Offset, py.Scale, py.Offset)
					z.BackgroundTransparency = 0.12
				elseif h.dirX ~= 0 then
					z.Size = UDim2.new(0, edgeT, 1, -cornerS * 2)
					z.Position = (h.dirX == -1)
						and UDim2.fromOffset(0, cornerS)
						or UDim2.new(1, -edgeT, 0, cornerS)
					z.BackgroundTransparency = 0.35
				else
					z.Size = UDim2.new(1, -cornerS * 2, 0, edgeT)
					z.Position = (h.dirY == -1)
						and UDim2.fromOffset(cornerS, 0)
						or UDim2.new(0, cornerS, 1, -edgeT)
					z.BackgroundTransparency = 0.35
				end
			end
		end

		local function updateResizeVisibility()
			local show = win.resizeMode and (not win.maximised)
			layoutResizeHandles()
			for _, h in ipairs(resizeHandles) do
				h.zone.Visible = show
				h.zone.Active = show
			end
			resizeBanner.Visible = show
			borderStroke.Color = show and theme.color.accent or theme.color.border
			borderStroke.Thickness = show and 2 or 1
		end

		function win.setResizeMode(flag)
			local nextFlag = flag == true
			if nextFlag and win.maximised then
				-- Automatically un-maximize slightly so the player has edges to push/pull!
				local bounds = responsive.usableRect(6)
				win.maximised = false
				config.set("window.maximised", false, { quiet = true })
				local nw = math.floor(bounds.width * 0.90)
				local nh = math.floor(bounds.height * 0.88)
				root.Size = UDim2.fromOffset(nw, nh)
				root.Position = UDim2.fromOffset(
					bounds.x + math.floor((bounds.width - nw) * 0.5),
					bounds.y + math.floor((bounds.height - nh) * 0.5)
				)
				if win.onResize then pcall(win.onResize, nw, nh) end
			end
			win.resizeMode = nextFlag
			activeGesture = nil
			updateResizeVisibility()
			win.resizeModeChanged:fire(win.resizeMode)
			return win.resizeMode
		end

		function win.toggleResizeMode()
			return win.setResizeMode(not win.resizeMode)
		end

		local lastTitleClickMs = -1000
		local lastTitleClickX = -1000
		local lastTitleClickY = -1000

		function win.bindDragBar(dragSurface)
			local function isInteractiveDescendant(input)
				for _, child in ipairs(dragSurface:GetDescendants()) do
					if child:IsA("GuiButton") or child:IsA("TextBox") then
						local p, s = child.AbsolutePosition, child.AbsoluteSize
						if child.Visible
							and input.Position.X >= p.X and input.Position.X <= p.X + s.X
							and input.Position.Y >= p.Y and input.Position.Y <= p.Y + s.Y then
							return true
						end
					end
				end
				return false
			end

			dragSurface.InputBegan:Connect(function(input)
				-- While Resize Mode is ON, pause TitleBar move-dragging so pull/push handles never fight moving!
				if win.resizeMode then return end
				local kind = input.UserInputType
				if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
				if isInteractiveDescendant(input) then return end

				local nowMs = clock.ms()
				if (nowMs - lastTitleClickMs < 320)
					and math.abs(input.Position.X - lastTitleClickX) < 6
					and math.abs(input.Position.Y - lastTitleClickY) < 6 then
					lastTitleClickMs = -1000
					win.toggleMaximise()
					return
				end
				lastTitleClickMs = nowMs
				lastTitleClickX = input.Position.X
				lastTitleClickY = input.Position.Y

				if win.maximised or win.snappedSide then
					local bounds = responsive.usableRect(6)
					local restoreW = preSnapRect and preSnapRect.w or math.floor(bounds.width * 0.82)
					local restoreH = preSnapRect and preSnapRect.h or math.floor(bounds.height * 0.82)
					win.maximised = false
					win.snappedSide = nil
					config.set("window.maximised", false, { quiet = true })
					local newX = util.clamp(math.floor(input.Position.X - restoreW * 0.5), bounds.x, math.max(bounds.x, bounds.x + bounds.width - restoreW))
					local newY = bounds.y
					root.Size = UDim2.fromOffset(restoreW, restoreH)
					root.Position = UDim2.fromOffset(newX, newY)
					updateResizeVisibility()
				end

				activeGesture = {
					mode = "drag",
					input = input,
					startMouse = input.Position,
					startX = root.Position.X.Offset,
					startY = root.Position.Y.Offset,
				}
			end)
		end

		if env.uis then
			dispose.connection(env.uis.InputChanged:Connect(function(input)
				if not activeGesture then return end
				local kind = input.UserInputType
				if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end

				local bounds = responsive.usableRect(4)
				local dx = input.Position.X - activeGesture.startMouse.X
				local dy = input.Position.Y - activeGesture.startMouse.Y

				if activeGesture.mode == "pillDrag" then
					if math.abs(dx) >= 6 or math.abs(dy) >= 6 then
						pillDidDrag = true
					end
					if pillDidDrag then
						local pw = pill.AbsoluteSize.X
						local ph = pill.AbsoluteSize.Y
						local px = util.clamp(math.floor(activeGesture.startX + dx), 4, math.max(4, bounds.x + bounds.width - pw - 4))
						local py = util.clamp(math.floor(activeGesture.startY + dy), 4, math.max(4, bounds.y + bounds.height - ph - 4))
						pill.Position = UDim2.fromOffset(px, py)
					end
				elseif activeGesture.mode == "drag" then
					local w = root.Size.X.Offset
					local h = root.Size.Y.Offset
					local nx = util.clamp(math.floor(activeGesture.startX + dx), bounds.x, math.max(bounds.x, bounds.x + bounds.width - w))
					local ny = util.clamp(math.floor(activeGesture.startY + dy), bounds.y, math.max(bounds.y, bounds.y + bounds.height - h))
					root.Position = UDim2.fromOffset(nx, ny)
				elseif activeGesture.mode == "resize" and win.resizeMode then
					local effMinW, effMinH = win.effectiveMinBounds(bounds)
					local nx = activeGesture.startX
					local ny = activeGesture.startY
					local nw = activeGesture.startW
					local nh = activeGesture.startH

					if activeGesture.dirX == 1 then
						nw = util.clamp(math.floor(activeGesture.startW + dx), effMinW, bounds.x + bounds.width - nx)
					elseif activeGesture.dirX == -1 then
						local rightEdge = activeGesture.startX + activeGesture.startW
						nx = util.clamp(math.floor(activeGesture.startX + dx), bounds.x, rightEdge - effMinW)
						nw = rightEdge - nx
					end

					if activeGesture.dirY == 1 then
						nh = util.clamp(math.floor(activeGesture.startH + dy), effMinH, bounds.y + bounds.height - ny)
					elseif activeGesture.dirY == -1 then
						local bottomEdge = activeGesture.startY + activeGesture.startH
						ny = util.clamp(math.floor(activeGesture.startY + dy), bounds.y, bottomEdge - effMinH)
						nh = bottomEdge - ny
					end

					root.Position = UDim2.fromOffset(nx, ny)
					root.Size = UDim2.fromOffset(nw, nh)
					if win.onResize then
						pcall(win.onResize, nw, nh)
					end
				end
			end))

			dispose.connection(env.uis.InputEnded:Connect(function(input)
				if not activeGesture then return end
				local kind = input.UserInputType
				if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end

				local g = activeGesture
				activeGesture = nil
				local bounds = responsive.usableRect(6)

				if g.mode == "drag" then
					-- Only Aero-Snap on Desktop Mode (on Mobile Mode let players position near edges freely!)
					if not win.mobileMode then
						if input.Position.Y <= bounds.y + SNAP_EDGE then
							preSnapRect = { w = root.Size.X.Offset, h = root.Size.Y.Offset }
							win.setMaximised(true)
							return
						elseif input.Position.X <= bounds.x + SNAP_EDGE then
							preSnapRect = { w = root.Size.X.Offset, h = root.Size.Y.Offset }
							win.snappedSide = "left"
							win.applyLayout("snap")
							return
						elseif input.Position.X >= bounds.x + bounds.width - SNAP_EDGE then
							preSnapRect = { w = root.Size.X.Offset, h = root.Size.Y.Offset }
							win.snappedSide = "right"
							win.applyLayout("snap")
							return
						end
					end
					persistRect()
					config.saveNow()
				elseif g.mode == "pillDrag" then
					if pillDidDrag then
						task.delay(0.05, function()
							pillDidDrag = false
						end)
					end
				elseif g.mode == "resize" then
					config.set("window.customSize", true, { quiet = true })
					config.set("window.widthScale", root.Size.X.Offset / math.max(1, bounds.width), { quiet = true })
					config.set("window.heightScale", root.Size.Y.Offset / math.max(1, bounds.height), { quiet = true })
					persistRect()
					config.saveNow()
				end
			end))
		end

		function win.setMaximised(flag)
			if flag and not win.maximised then
				preSnapRect = { w = root.Size.X.Offset, h = root.Size.Y.Offset }
			end
			win.maximised = flag == true
			if win.maximised and win.resizeMode then
				win.resizeMode = false
				win.resizeModeChanged:fire(false)
			end
			win.snappedSide = nil
			config.set("window.maximised", win.maximised, { immediate = true })
			updateResizeVisibility()
			win.applyLayout("maximise")
		end

		function win.toggleMaximise()
			win.setMaximised(not win.maximised)
		end

		function win.setOpacity(alpha, opts)
			opts = opts or {}
			local clamped = math.floor(util.clamp(tonumber(alpha) or 1.0, 0.30, 1.0) * 100 + 0.5) / 100
			win.opacity = clamped
			config.set("window.opacity", clamped, { quiet = opts.quiet == true, immediate = opts.immediate == true })
			win.opacityChanged:fire(clamped)
			return clamped
		end

		function win.getOpacity()
			return win.opacity
		end

		function win.stepOpacity(delta)
			return win.setOpacity(win.opacity + (tonumber(delta) or 0))
		end

		function win.setMobileMode(flag)
			win.mobileMode = flag == true
			pill.Size = flag and UDim2.fromOffset(148, 40) or UDim2.fromOffset(128, 32)
			pillBrand.Position = UDim2.fromOffset(12, flag and 12 or 8)
			updateResizeVisibility()
			win.applyLayout("mobileMode")
		end

		function win.setPlayWhileCoding(flag)
			local nextPlay = flag == true
			win.playWhileCoding = nextPlay
			config.set("mobile.playWhileCoding", nextPlay, { immediate = true })
			if nextPlay then
				if win.opacity > 0.80 then
					prePlayOpacity = win.opacity
					win.setOpacity(0.72)
				end
			elseif prePlayOpacity then
				win.setOpacity(prePlayOpacity)
				prePlayOpacity = nil
			end
			win.applyLayout("playWhileCoding")
			return nextPlay
		end

		function win.resetAutoSize()
			win.maximised = false
			win.snappedSide = nil
			config.set("window.maximised", false, { quiet = true })
			config.set("window.customSize", false, { quiet = true })
			config.set("window.placed", false, { immediate = true })
			updateResizeVisibility()
			win.applyLayout("resetAuto")
		end

		function win.minimise()
			win.minimised = true
			root.Visible = false
			pill.Visible = true
		end

		function win.restore()
			win.minimised = false
			win.visible = true
			pill.Visible = false
			root.Visible = true
			win.applyLayout("restore")
		end

		function win.hide()
			win.visible = false
			root.Visible = false
			pill.Visible = false
		end

		function win.show()
			win.visible = true
			win.minimised = false
			pill.Visible = false
			root.Visible = true
			win.applyLayout("show")
		end

		function win.toggle()
			if win.minimised or not win.visible then
				win.restore()
			else
				win.minimise()
			end
		end

		responsive.changed:connect(function()
			if win.visible and not win.minimised then
				win.applyLayout("viewport")
			end
		end)

		theme.changed:connect(function()
			root.BackgroundColor3 = theme.color.editor
			pill.BackgroundColor3 = theme.color.titleBar
			resizeBanner.BackgroundColor3 = theme.color.accent
			updateResizeVisibility()
		end)

		updateResizeVisibility()
		win.applyLayout("init")
		return win
	end

	return M
end
end)()

-- ==========================================================================
-- bootstrap
-- ==========================================================================
--!globals __VSRBLX_MODULES __VSRBLX_BUILD
-- VS-RBLX Bootstrap (`init.lua`).
--
-- Every file under `src/` is a factory of the form `return function(env) ... end`.
-- `tools/bundle.lua` emits `local __VSRBLX_BUILD` and `local __VSRBLX_MODULES` above
-- this bootstrap in `dist/vsrblx.lua`, so `__VSRBLX_MODULES` is bound directly as a
-- lexical local inside the single-file bundle:
--
--     loadstring(game:HttpGet("https://raw.githubusercontent.com/TheStrongestOfTomorrow/VS-RBLX/main/dist/vsrblx.lua"))()

local MODULES = __VSRBLX_MODULES
local isDevFallback = false

if type(MODULES) ~= "table" then
	if type(loadfile) == "function" then
		isDevFallback = true
		MODULES = setmetatable({}, {
			__index = function(cache, id)
				local relPath = "src/" .. tostring(id) .. ".lua"
				local chunk = loadfile(relPath)
				if not chunk then return nil end
				local factory = chunk()
				cache[id] = factory
				return factory
			end,
		})
	else
		warn("[vsrblx] no module table -- run the bundled dist/vsrblx.lua, not init.lua")
		return nil
	end
end

local hostContext = ...

local VERSION = "1.0.0"
local FOLDER = "VSRBLX"
local BUILD = type(__VSRBLX_BUILD) == "string" and __VSRBLX_BUILD or (VERSION .. "-dev")

-- If executed from autoexec before the DataModel finishes loading, wait cleanly.
if game and type(game.IsLoaded) == "function" then
	local ok, loadedFlag = pcall(function() return game:IsLoaded() end)
	if ok and not loadedFlag and game.Loaded then
		pcall(function() game.Loaded:Wait() end)
	end
end

local globalTable = nil
if type(getgenv) == "function" then
	local ok, g = pcall(getgenv)
	if ok and type(g) == "table" then
		globalTable = g
	end
end
if not globalTable and type(_G) == "table" then
	globalTable = _G
end

local function lookupGlobal(key, directVal)
	if directVal ~= nil then return directVal end
	if globalTable ~= nil then
		local ok, v = pcall(function() return globalTable[key] end)
		if ok and v ~= nil then return v end
	end
	return nil
end

local options = (type(hostContext) == "table" and hostContext)
	or (globalTable and type(globalTable.VSRBLX_CONFIG) == "table" and globalTable.VSRBLX_CONFIG)
	or {}

-- Re-running the same build toggles/reopens the existing window unless `reload = true`;
-- running a newer build tears down the old instance cleanly and mounts the update.
if globalTable then
	local okExisting, existing = pcall(function() return globalTable.VSRBLX end)
	if okExisting and type(existing) == "table" and existing.alive then
		if existing.build == BUILD and options.reload ~= true and not isDevFallback then
			if options.reuse ~= true and type(existing.toggle) == "function" then
				pcall(existing.toggle)
			end
			return existing
		end
		if type(existing.destroy) == "function" then
			pcall(existing.destroy)
		end
	end
end

-- Lazy memoised service lookup via game:GetService (safe even if instances were renamed).
local services = setmetatable({}, {
	__index = function(cache, name)
		if not game or type(game.GetService) ~= "function" then return nil end
		local ok, svc = pcall(function() return game:GetService(name) end)
		if not ok or not svc then return nil end
		cache[name] = svc
		return svc
	end,
})

local playersService = services.Players
local localPlr = playersService and playersService.LocalPlayer or nil
if not localPlr and playersService then
	pcall(function()
		local sig = playersService:GetPropertyChangedSignal("LocalPlayer")
		if sig and not playersService.LocalPlayer then
			-- Brief non-blocking check in case LocalPlayer attaches on the next frame
			task.wait()
		end
		localPlr = playersService.LocalPlayer
	end)
end

local env = {
	version = VERSION,
	buildId = BUILD,
	channel = type(__VSRBLX_BUILD) == "string" and "release" or "dev",
	info = {
		name = "VSRBLX",
		version = VERSION,
		build = BUILD,
		folder = options.folder or FOLDER,
	},
	opts = options,
	context = options,
	services = services,

	-- Service shortcuts
	game = game,
	workspace = services.Workspace or workspace,
	players = playersService,
	plr = localPlr,
	uis = services.UserInputService,
	tween = services.TweenService,
	hs = services.HttpService,
	httpService = services.HttpService,
	runService = services.RunService,
	textService = services.TextService,
	guisvc = services.GuiService,
	guiService = services.GuiService,
	coreGui = services.CoreGui,

	-- Executor host capabilities
	getgenv = lookupGlobal("getgenv", getgenv),
	gethui = lookupGlobal("gethui", gethui),
	identifyexecutor = lookupGlobal("identifyexecutor", identifyexecutor)
		or lookupGlobal("getexecutorname", getexecutorname),
	loadstring = lookupGlobal("loadstring", loadstring),

	-- Executor local disk filesystem (`writefile` / `readfile`)
	writefile = lookupGlobal("writefile", writefile),
	readfile = lookupGlobal("readfile", readfile),
	appendfile = lookupGlobal("appendfile", appendfile),
	isfile = lookupGlobal("isfile", isfile),
	isfolder = lookupGlobal("isfolder", isfolder),
	makefolder = lookupGlobal("makefolder", makefolder),
	listfiles = lookupGlobal("listfiles", listfiles),
	delfile = lookupGlobal("delfile", delfile),
	delfolder = lookupGlobal("delfolder", delfolder),

	-- Executor HTTP transport (`request` / `http_request` / `syn.request`)
	request = lookupGlobal("request", request),
	http_request = lookupGlobal("http_request", http_request),
	http = lookupGlobal("http", http),
	syn = lookupGlobal("syn", syn),
	fluxus = lookupGlobal("fluxus", fluxus),

	-- Clipboard & script inspection
	setclipboard = lookupGlobal("setclipboard", setclipboard)
		or lookupGlobal("toclipboard", toclipboard),
	getclipboard = lookupGlobal("getclipboard", getclipboard),
	decompile = lookupGlobal("decompile", decompile),
	getscriptbytecode = lookupGlobal("getscriptbytecode", getscriptbytecode),
}

local loaded, loading, requireStack = {}, {}, {}

env.moduleTotal = 0
if not isDevFallback then
	for _ in pairs(MODULES) do
		env.moduleTotal = env.moduleTotal + 1
	end
end
env.moduleCount = 0
env.loadedModules = loaded

function env.require(id)
	local cached = loaded[id]
	if cached ~= nil then return cached end
	if loading[id] then
		local cycle = {}
		for i = 1, #requireStack do cycle[#cycle + 1] = requireStack[i] end
		cycle[#cycle + 1] = tostring(id)
		error("[vsrblx] circular require: " .. table.concat(cycle, " -> "), 2)
	end
	local factory = MODULES[id]
	if type(factory) ~= "function" then
		error("[vsrblx] no module '" .. tostring(id) .. "'", 2)
	end
	loading[id] = true
	requireStack[#requireStack + 1] = tostring(id)
	local ok, result = pcall(factory, env)
	requireStack[#requireStack] = nil
	loading[id] = nil
	if not ok then
		error("[vsrblx] module '" .. tostring(id) .. "' failed to load: " .. tostring(result), 2)
	end
	if result == nil then
		error("[vsrblx] module '" .. tostring(id) .. "' returned nothing", 2)
	end
	loaded[id] = result
	env.moduleCount = env.moduleCount + 1
	if env.onModuleLoaded then
		pcall(env.onModuleLoaded, id, env.moduleCount, env.moduleTotal)
	end
	return result
end

local bootCard = nil

local function start()
	local mountUi = options.headless ~= true and options.ui ~= false

	if mountUi then
		pcall(function()
			bootCard = env.require("ui/boot").show()
		end)
	end

	local lastYield = os.clock()
	env.onModuleLoaded = function(id, count, total)
		if bootCard and bootCard.moduleStep then
			pcall(bootCard.moduleStep, id, count, total)
		end
		if os.clock() - lastYield >= 0.03 then
			task.wait()
			lastYield = os.clock()
		end
	end

	if bootCard then
		task.wait()
	end

	local caps = env.require("runtime/caps")
	env.caps = caps
	local log = env.require("runtime/log")
	local dispose = env.require("runtime/dispose")

	log.info("boot", string.format("VS-RBLX %s (%s) starting -- %s", VERSION, BUILD, caps.summary()))

	local appInstance = nil
	if mountUi then
		options.splash = bootCard
		local appMod = env.require("ui/app")
		appInstance = appMod.mount(options)
		options.splash = nil
	else
		local config = env.require("runtime/config")
		local cryptoVault = env.require("runtime/crypto_vault")
		local workspaceFs = env.require("runtime/workspace_fs")
		local gitState = env.require("runtime/git_state")
		config.load()
		cryptoVault.init()
		workspaceFs.init()
		gitState.loadMeta()
	end

	local sdkMod = env.require("embedding/sdk")
	local handle
	handle = sdkMod.buildHandle(appInstance, function()
		dispose.drain()
		if appInstance and appInstance.screenGui then
			pcall(function() appInstance.screenGui:Destroy() end)
		end
		if globalTable then
			pcall(function()
				if globalTable.VSRBLX == handle then
					globalTable.VSRBLX = nil
				end
			end)
		end
	end)

	env.onModuleLoaded = nil
	if bootCard then
		pcall(bootCard.close)
		bootCard = nil
	end

	if globalTable then
		pcall(function() globalTable.VSRBLX = handle end)
	end
	log.info("boot", "VS-RBLX ready")
	return handle
end

local ok, result = pcall(start)
if not ok then
	env.onModuleLoaded = nil
	warn("[vsrblx] failed to start: " .. tostring(result))
	local disposer = loaded["runtime/dispose"]
	if disposer then pcall(disposer.drain) end
	if bootCard and bootCard.fail then
		pcall(bootCard.fail, result)
	end
	return nil
end

return result
